  pointer-events: none;
  transition: opacity .3s ease, transform .35s cubic-bezier(.2,.9,.3,1.2);
  z-index: 25;
}
.sale-banner.show { opacity: 1; transform: translate(0, -50%); }
.sale-banner .sb-eyebrow { display: flex; align-items: center; gap: 6px; font-size: 8.5px; font-weight: 800; letter-spacing: .18em; text-transform: uppercase; color: var(--gold-2); }
.sale-banner .sb-eyebrow svg { width: 13px; height: 13px; }
.sale-banner .sb-name { font-family: var(--serif); font-size: 18px; margin: 3px 0 1px; }
.sale-banner .sb-price { font-size: 11px; color: rgba(246, 238, 219, .7); }
.sale-banner .sb-price b { color: var(--gold-2); font-size: 13px; }

.corner-hint {
  position: absolute;
  right: max(20px, env(safe-area-inset-right));
  bottom: 104px;
  font-size: 9px;
  font-weight: 700;
  letter-spacing: .08em;
  text-transform: uppercase;
  color: rgba(255, 255, 255, .55);
  text-shadow: 0 1px 3px rgba(0, 0, 0, .4);
