/* ============================================================
   START SCREEN
   ============================================================ */
.start-screen {
  position: absolute;
  inset: 0;
  z-index: 60;
  display: flex;
  flex-direction: column;
  padding: max(24px, env(safe-area-inset-top)) max(34px, env(safe-area-inset-right)) max(20px, env(safe-area-inset-bottom)) max(34px, env(safe-area-inset-left));
  overflow: auto;
  color: var(--cream);
  transition: opacity .6s ease, visibility .6s;
}
.start-screen.out { opacity: 0; visibility: hidden; pointer-events: none; }
.start-wash {
  position: absolute;
  inset: 0;
  z-index: -1;
  background:
    radial-gradient(80% 70% at 70% 40%, rgba(20, 33, 24, 0) 0%, rgba(17, 28, 21, .32) 58%, rgba(13, 23, 17, .88) 100%),
    linear-gradient(90deg, rgba(14, 24, 18, .94) 0%, rgba(15, 26, 19, .72) 42%, rgba(15, 26, 19, .12) 74%, rgba(14, 24, 18, .45) 100%);
  pointer-events: none;
}
.start-brand {
  display: flex;
  align-items: center;
  gap: 10px;
  font-family: var(--serif);
  font-size: 15px;
  letter-spacing: .02em;
  color: rgba(246, 238, 219, .82);
  animation: fade-in .9s .1s both;
}
.brand-mark { display: grid; place-items: center; width: 27px; height: 27px; border: 1px solid rgba(246, 238, 219, .4); border-radius: 50%; color: var(--gold-2); }
.brand-mark svg { width: 14px; height: 14px; }
.start-brand em { font-family: var(--sans); font-size: 8px; font-style: normal; font-weight: 800; letter-spacing: .18em; text-transform: uppercase; opacity: .55; margin-left: 2px; }

.start-main {
  position: relative;
  z-index: 1;
  width: min(1240px, 100%);
  margin: auto;
  display: grid;
  grid-template-columns: minmax(0, 1.25fr) minmax(300px, .75fr);
  align-items: center;
  gap: clamp(28px, 5vw, 84px);
  padding: 36px 0 30px;
}
.start-copy { max-width: 680px; animation: rise-in .85s .12s cubic-bezier(.2,.9,.3,1) both; }
.start-copy .eyebrow { display: flex; align-items: center; gap: 10px; color: var(--gold-2); font-size: 9.5px; letter-spacing: .24em; text-shadow: 0 1px 8px rgba(0,0,0,.4); }
.start-copy .eyebrow span { width: 26px; height: 1px; background: linear-gradient(90deg, transparent, rgba(240, 205, 122, .8)); }
.start-copy .eyebrow span:last-child { background: linear-gradient(90deg, rgba(240, 205, 122, .8), transparent); }
.start-copy h1 {
  margin: 14px 0 12px;
  font-family: var(--serif);
  font-weight: 600;
  font-size: clamp(58px, 8.2vw, 118px);
  line-height: .82;
  letter-spacing: -.015em;
  color: #f8f0dd;
  text-shadow: 0 5px 30px rgba(0, 0, 0, .35), 0 1px 0 rgba(255, 255, 255, .1);
}
.start-copy h1 i { display: inline-block; font-style: italic; font-weight: 400; color: var(--gold-2); font-size: .78em; transform: translateY(-.03em); margin: 0 .04em; text-shadow: 0 0 30px rgba(240, 205, 122, .25); }
.tagline { margin: 0 0 16px; font-family: var(--serif); font-size: clamp(19px, 2vw, 26px); font-style: italic; line-height: 1.25; color: rgba(248, 240, 221, .94); }
.blurb { max-width: 510px; margin: 0 0 26px; font-size: 13.5px; line-height: 1.65; color: rgba(241, 232, 210, .66); }
.start-actions { display: flex; align-items: center; gap: 12px; flex-wrap: wrap; }
.start-meta { display: flex; flex-wrap: wrap; gap: 18px; margin-top: 24px; font-size: 10px; font-weight: 700; letter-spacing: .08em; text-transform: uppercase; color: rgba(246, 238, 219, .52); }
.start-meta span { display: inline-flex; align-items: center; gap: 6px; }
.start-meta kbd { height: 20px; min-width: 20px; background: rgba(247, 238, 218, .12); border-color: rgba(247, 238, 218, .28); color: var(--cream); font-size: 9px; box-shadow: none; }

.start-card {
  width: 100%;
  max-width: 360px;
  justify-self: end;
  padding: 28px 26px 24px;
  transform: rotate(.5deg);
  animation: card-in .9s .28s cubic-bezier(.2,.9,.3,1.15) both;
}
.start-card::before {
  content: "";
  position: absolute;
  top: -9px;
  left: 50%;
  width: 74px;
  height: 18px;
  transform: translateX(-50%) rotate(-2deg);
  background: rgba(236, 218, 178, .65);
  border: 1px solid rgba(180, 153, 105, .4);
  box-shadow: 0 2px 5px rgba(50, 40, 20, .1);
}
.start-card .seal {
  position: absolute;
  top: -24px;
  right: -16px;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  width: 68px;
  height: 68px;
  border-radius: 50%;
  background: radial-gradient(circle at 35% 30%, #c77454, var(--rust-deep));
  border: 2px dashed rgba(246, 230, 194, .6);
  color: #f8e9c8;
  box-shadow: 0 8px 18px rgba(70, 35, 20, .28), inset 0 0 0 4px rgba(246, 230, 194, .12);
  transform: rotate(7deg);
}
.start-card .seal span { font-family: var(--serif); font-size: 27px; font-weight: 700; line-height: .9; }
.start-card .seal small { font-size: 7px; font-weight: 800; letter-spacing: .16em; text-transform: uppercase; opacity: .8; }
.start-card h2 { margin: 5px 0 8px; font-family: var(--serif); font-size: 27px; font-weight: 600; line-height: 1.05; letter-spacing: -.01em; }
.start-card > p:not(.eyebrow) { margin: 0 0 16px; font-size: 12px; line-height: 1.55; color: var(--ink-2); }
.start-card > p b { color: var(--rust-deep); }
.loop-list { list-style: none; margin: 0; padding: 14px 0 0; border-top: 1px dashed var(--line-strong); display: grid; gap: 10px; }
.loop-list li { display: flex; align-items: center; gap: 11px; }
.loop-ico { display: grid; place-items: center; width: 34px; height: 34px; flex: none; border-radius: 9px; background: rgba(78, 122, 75, .1); border: 1px solid rgba(78, 122, 75, .18); }
.loop-ico svg { width: 20px; height: 20px; }
.loop-ico.mine { background: rgba(90, 100, 105, .11); border-color: rgba(90, 100, 105, .2); }
.loop-ico.forge { background: rgba(184, 92, 62, .11); border-color: rgba(184, 92, 62, .22); }
.loop-ico.sell { background: rgba(216, 165, 65, .14); border-color: rgba(154, 108, 31, .24); }
.loop-list b { display: block; font-size: 11.5px; letter-spacing: .02em; }
.loop-list small { display: block; font-size: 10px; color: var(--ink-3); margin-top: 1px; }

.start-footer {
  position: relative;
  z-index: 1;
  display: flex;
  justify-content: space-between;
  gap: 20px;
  font-size: 9px;
  font-weight: 700;
  letter-spacing: .13em;
  text-transform: uppercase;
  color: rgba(246, 238, 219, .4);
  animation: fade-in 1s .6s both;
}
.start-foot-right { display: flex; align-items: center; gap: 6px; }
.start-foot-right svg { width: 11px; height: 11px; color: var(--gold); }

/* ============================================================
   MODAL
   ============================================================ */
.modal-layer {
  position: absolute;
  inset: 0;
  z-index: 80;
  display: grid;
  place-items: center;
  padding: max(16px, env(safe-area-inset-top)) 16px max(16px, env(safe-area-inset-bottom));
}
.modal-scrim {
  position: absolute;
  inset: 0;
  background: rgba(11, 20, 14, .58);
  backdrop-filter: blur(5px);
  -webkit-backdrop-filter: blur(5px);
  animation: fade-in .2s both;
}
.modal-panel {
  position: relative;
  width: min(880px, 94vw);
  max-height: 88dvh;
  border-radius: 20px;
  border: 1px solid #c9b489;
  background:
    radial-gradient(130% 100% at 10% 0%, rgba(255, 255, 255, .8), transparent 55%),
    linear-gradient(150deg, var(--paper), var(--paper-deep));
  box-shadow: 0 30px 80px rgba(5, 12, 8, .5), inset 0 1px 0 rgba(255, 255, 255, .8);
  color: var(--ink);
  animation: modal-in .3s cubic-bezier(.2,.9,.3,1.1) both;
  display: flex;
  flex-direction: column;
  overflow: hidden;
}
.modal-panel::after {
  content: "";
  position: absolute;
  inset: 0;
  border-radius: inherit;
  background-image: var(--grain);
  opacity: .07;
  mix-blend-mode: multiply;
  pointer-events: none;
}
.modal-close {
  position: absolute;
  top: 13px;
  right: 13px;
  z-index: 3;
  display: grid;
  place-items: center;
  width: 34px;
  height: 34px;
  border-radius: 50%;
  border: 1px solid rgba(60, 70, 50, .2);
  background: rgba(255, 252, 242, .6);
  color: var(--ink-2);
  transition: background .15s ease, transform .15s ease;
}
.modal-close:hover { background: rgba(255, 255, 255, .95); transform: rotate(6deg); }
.modal-close svg { width: 16px; height: 16px; }
#modalBody { padding: 28px 30px 26px; overflow-y: auto; overscroll-behavior: contain; }

.modal-head { padding-right: 34px; margin-bottom: 18px; }
.modal-head h2 { margin: 3px 0 5px; font-family: var(--serif); font-size: clamp(26px, 3.2vw, 34px); font-weight: 600; line-height: 1.02; letter-spacing: -.015em; }
.modal-head p { margin: 0; font-size: 12.5px; line-height: 1.5; color: var(--ink-3); max-width: 560px; }
.modal-head .head-row { display: flex; align-items: flex-end; justify-content: space-between; gap: 20px; }
.forge-bonus { flex: none; display: flex; align-items: center; gap: 7px; padding: 7px 11px; border-radius: 8px; background: rgba(78, 122, 75, .1); border: 1px solid rgba(78, 122, 75, .2); font-size: 10px; font-weight: 800; color: var(--leaf-deep); }
.forge-bonus svg { width: 14px; height: 14px; }

.recipe-grid { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 11px; }
.recipe-card {
  display: grid;
  grid-template-columns: 74px minmax(0, 1fr);
  gap: 12px;
  padding: 12px;
  border-radius: 13px;
  border: 1px solid var(--line);
  background: rgba(255, 253, 246, .52);
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, .7);
  transition: border-color .15s ease, background .15s ease, transform .15s ease;
}
.recipe-card:hover { border-color: #bfa878; background: rgba(255, 253, 246, .8); }
.recipe-card.cant { opacity: .72; }
.weapon-thumb { width: 74px; height: 74px; border-radius: 9px; background: radial-gradient(circle at 50% 40%, rgba(216, 165, 65, .16), rgba(63, 78, 58, .06) 65%); border: 1px solid rgba(60, 70, 50, .1); }
.recipe-info { min-width: 0; display: flex; flex-direction: column; }
.recipe-info h3 { margin: 1px 0 1px; font-family: var(--serif); font-size: 17px; font-weight: 600; line-height: 1.1; }
.recipe-tag { font-size: 8.5px; font-weight: 800; letter-spacing: .13em; text-transform: uppercase; color: var(--ink-3); }
.recipe-desc { margin: 3px 0 5px; font-size: 10px; line-height: 1.35; color: var(--ink-3); }
.cost-row { display: flex; flex-wrap: wrap; gap: 4px; margin-top: auto; }
.cost-chip { display: inline-flex; align-items: center; gap: 3px; padding: 2px 5px 2px 3px; border-radius: 5px; background: rgba(60, 70, 50, .06); font-size: 9.5px; font-weight: 800; color: var(--ink-2); }
.cost-chip svg { width: 13px; height: 13px; }
.cost-chip.missing { color: var(--rust-deep); background: rgba(184, 92, 62, .1); }
.recipe-foot { grid-column: 1 / -1; display: flex; align-items: center; justify-content: space-between; gap: 8px; margin-top: 1px; padding-top: 8px; border-top: 1px dashed var(--line); }
.recipe-value { font-family: var(--serif); font-size: 16px; font-weight: 700; color: var(--gold-deep); }
.recipe-value small { font-family: var(--sans); font-size: 8px; font-weight: 800; letter-spacing: .12em; text-transform: uppercase; color: var(--ink-3); margin-left: 3px; }
.craft-btn { border: 1px solid #2d4a33; border-radius: 7px; padding: 6px 13px; background: linear-gradient(180deg, #5e8656, #375c3c); color: #f8f2e1; font-size: 10px; font-weight: 800; letter-spacing: .04em; box-shadow: inset 0 1px 0 rgba(255, 255, 255, .2), 0 3px 6px rgba(40, 60, 40, .18); transition: transform .14s ease, filter .14s ease; }
.craft-btn:hover:not(:disabled) { transform: translateY(-1px); filter: brightness(1.08); }
.craft-btn:disabled { opacity: .4; cursor: not-allowed; }
.craft-note { display: flex; align-items: center; gap: 7px; margin-top: 16px; padding: 9px 12px; border-radius: 8px; background: rgba(60, 70, 50, .05); border: 1px dashed var(--line-strong); font-size: 10.5px; color: var(--ink-3); }
.craft-note svg { width: 14px; height: 14px; color: var(--gold-deep); flex: none; }

/* pedestal */
.display-grid { display: grid; grid-template-columns: 190px minmax(0, 1fr); gap: 24px; align-items: start; }
.display-preview { position: relative; display: grid; place-items: center; aspect-ratio: 1; border-radius: 14px; background: radial-gradient(circle at 50% 38%, rgba(216, 165, 65, .22), rgba(58, 72, 52, .06) 66%); border: 1px solid rgba(60, 70, 50, .12); }
.display-preview canvas { width: 150px; height: 150px; }
.display-preview .dp-stock { position: absolute; bottom: 10px; left: 50%; transform: translateX(-50%); padding: 3px 9px; border-radius: 999px; background: rgba(35, 50, 36, .85); color: var(--cream); font-size: 9px; font-weight: 800; letter-spacing: .08em; text-transform: uppercase; white-space: nowrap; }
.display-info h2 { margin: 0 0 2px; font-family: var(--serif); font-size: 28px; font-weight: 600; line-height: 1.05; }
.display-info .display-tag { font-size: 9px; font-weight: 800; letter-spacing: .14em; text-transform: uppercase; color: var(--ink-3); }
.display-info .display-desc { margin: 8px 0 14px; font-size: 11.5px; line-height: 1.5; color: var(--ink-3); }
.price-editor { display: flex; align-items: center; gap: 12px; padding: 11px 13px; border-radius: 11px; background: rgba(255, 253, 246, .7); border: 1px solid var(--line); }
.price-btn { display: grid; place-items: center; width: 34px; height: 34px; flex: none; border-radius: 8px; border: 1px solid var(--line-strong); background: rgba(255, 255, 255, .6); font-size: 18px; font-weight: 700; color: var(--ink-2); transition: background .14s ease; }
.price-btn:hover { background: #fff; }
.price-main { flex: 1; text-align: center; }
.price-main b { display: block; font-family: var(--serif); font-size: 27px; line-height: 1; color: var(--gold-deep); }
.price-main small { display: block; font-size: 9px; font-weight: 700; color: var(--ink-3); margin-top: 2px; }
.demand { margin: 10px 0 13px; }
.demand-head { display: flex; justify-content: space-between; font-size: 9px; font-weight: 800; letter-spacing: .1em; text-transform: uppercase; color: var(--ink-3); margin-bottom: 5px; }
.demand-head b { color: var(--leaf-deep); }
.demand-track { height: 7px; border-radius: 999px; background: rgba(60, 70, 50, .1); overflow: hidden; }
.demand-track span { display: block; height: 100%; border-radius: inherit; background: linear-gradient(90deg, #5d8b57, #d5a33e 55%, #b85c3e); transition: width .25s ease; }
.display-actions { display: flex; flex-wrap: wrap; gap: 8px; }
.display-actions .btn { padding: 9px 15px; font-size: 11px; }
.stock-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(148px, 1fr)); gap: 10px; }
.stock-card { padding: 10px; border-radius: 11px; border: 1px solid var(--line); background: rgba(255, 253, 246, .55); text-align: center; }
.stock-card canvas { width: 78px; height: 78px; }
.stock-card h3 { margin: 2px 0 1px; font-family: var(--serif); font-size: 14px; font-weight: 600; }
.stock-card small { display: block; font-size: 9px; font-weight: 800; letter-spacing: .1em; text-transform: uppercase; color: var(--ink-3); margin-bottom: 6px; }
.stock-card button { width: 100%; padding: 6px; border-radius: 6px; border: 1px solid #2d4a33; background: linear-gradient(180deg, #5e8656, #375c3c); color: var(--cream); font-size: 9px; font-weight: 800; letter-spacing: .08em; text-transform: uppercase; }
.stock-card button:disabled { opacity: .35; cursor: not-allowed; }
.empty-note { padding: 22px; text-align: center; font-size: 12px; color: var(--ink-3); border: 1px dashed var(--line-strong); border-radius: 11px; }

/* ledger */
.ledger-stats { display: grid; grid-template-columns: repeat(4, 1fr); gap: 9px; margin-bottom: 20px; }
.stat-tile { padding: 10px 12px; border-radius: 10px; background: rgba(255, 253, 246, .6); border: 1px solid var(--line); }
.stat-tile span { display: block; font-size: 8px; font-weight: 800; letter-spacing: .13em; text-transform: uppercase; color: var(--ink-3); }
.stat-tile b { display: block; margin-top: 2px; font-family: var(--serif); font-size: 22px; line-height: 1; }
.stat-tile b.gold { color: var(--gold-deep); }
.ledger-section { margin-bottom: 18px; }
.ledger-section h3 { display: flex; align-items: center; gap: 7px; margin: 0 0 8px; font-family: var(--serif); font-size: 17px; font-weight: 600; }
.ledger-section h3 svg { width: 15px; height: 15px; color: var(--leaf); }
.upgrade-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 9px; }
.upgrade-card { padding: 12px; border-radius: 11px; border: 1px solid var(--line); background: rgba(255, 253, 246, .55); display: flex; flex-direction: column; gap: 4px; }
.upgrade-card .u-ico { display: grid; place-items: center; width: 31px; height: 31px; border-radius: 8px; background: rgba(78, 122, 75, .1); color: var(--leaf-deep); margin-bottom: 3px; }
.upgrade-card .u-ico svg { width: 18px; height: 18px; }
.upgrade-card h4 { margin: 0; font-size: 12px; }
.upgrade-card p { margin: 0 0 7px; font-size: 10px; line-height: 1.4; color: var(--ink-3); flex: 1; }
.upgrade-card .u-buy { display: flex; align-items: center; justify-content: space-between; gap: 6px; }
.u-price { display: inline-flex; align-items: center; gap: 3px; font-family: var(--serif); font-size: 14px; font-weight: 700; color: var(--gold-deep); }
.u-price svg { width: 14px; height: 14px; }
.u-buy button { padding: 5px 10px; border-radius: 6px; border: 1px solid #2d4a33; background: linear-gradient(180deg, #5e8656, #375c3c); color: var(--cream); font-size: 9px; font-weight: 800; letter-spacing: .07em; text-transform: uppercase; }
.u-buy button:disabled { opacity: .35; cursor: not-allowed; }
.u-owned { font-size: 9px; font-weight: 800; letter-spacing: .09em; text-transform: uppercase; color: var(--leaf); }
.ledger-foot { display: flex; align-items: center; justify-content: space-between; gap: 14px; padding-top: 14px; border-top: 1px dashed var(--line-strong); }
.ledger-foot p { margin: 0; font-size: 10px; color: var(--ink-3); max-width: 300px; line-height: 1.4; }

/* help */
.help-grid { display: grid; grid-template-columns: repeat(2, 1fr); gap: 10px; }
.help-step { display: flex; gap: 10px; padding: 12px; border-radius: 11px; border: 1px solid var(--line); background: rgba(255, 253, 246, .5); }
.help-step .h-num { display: grid; place-items: center; width: 25px; height: 25px; flex: none; border-radius: 50%; background: var(--leaf-deep); color: var(--cream); font-family: var(--serif); font-size: 13px; font-weight: 700; }
.help-step h4 { margin: 0 0 2px; font-size: 12px; }
.help-step p { margin: 0; font-size: 10.5px; line-height: 1.45; color: var(--ink-3); }
.help-controls { display: flex; flex-wrap: wrap; gap: 8px 16px; margin-top: 16px; padding: 11px 13px; border-radius: 9px; background: rgba(60, 70, 50, .05); font-size: 10px; color: var(--ink-2); }
.help-controls span { display: inline-flex; align-items: center; gap: 6px; }

/* ============================================================
   OVERLAY SCREENS
   ============================================================ */
.overlay-screen {
  position: absolute;
  inset: 0;
  z-index: 70;
  display: grid;
  place-items: center;
  padding: max(18px, env(safe-area-inset-top)) 16px max(18px, env(safe-area-inset-bottom));
