/* ============================================================
   IRONROOT & IVY — static ground painting
   ============================================================ */
import { WORLD, GROUND_SCALE, mulberry32, TAU, rr, ellipsePath } from './data.js';

function strokePath(g, pts, width, color) {
  g.strokeStyle = color;
  g.lineWidth = width;
  g.beginPath();
  g.moveTo(pts[0].x, pts[0].y);
  for (let i = 1; i < pts.length; i++) g.lineTo(pts[i].x, pts[i].y);
  g.stroke();
}

function paintPath(g, pts, width, rng) {
  g.save();
  g.lineCap = 'round';
  g.lineJoin = 'round';
  strokePath(g, pts, width + 18, 'rgba(91, 74, 48, .16)');
  strokePath(g, pts, width + 10, '#a78c60');
  strokePath(g, pts, width, '#bea374');
  strokePath(g, pts, width * 0.58, 'rgba(211, 188, 146, .55)');
  g.restore();

  // pebbles & worn edges
  for (let i = 0; i < pts.length - 1; i++) {
    const a = pts[i], b = pts[i + 1];
    const len = Math.hypot(b.x - a.x, b.y - a.y);
    const steps = Math.floor(len / 15);
    for (let s = 0; s < steps; s++) {
      const t = s / steps;
      const x = a.x + (b.x - a.x) * t + (rng() - .5) * width * .92;
      const y = a.y + (b.y - a.y) * t + (rng() - .5) * width * .92;
      const r = .6 + rng() * 1.8;
      g.fillStyle = rng() > .5 ? 'rgba(140, 116, 80, .35)' : 'rgba(228, 210, 172, .4)';
      g.beginPath();
      g.arc(x, y, r, 0, TAU);
      g.fill();
    }
  }
}

function flower(g, x, y, color, size, rng) {
  g.fillStyle = 'rgba(45, 78, 45, .32)';
  g.beginPath();
  g.ellipse(x + 1, y + 2, size * 1.3, size * .6, 0, 0, TAU);
  g.fill();
  g.fillStyle = color;
  for (let p = 0; p < 5; p++) {
    const a = (p / 5) * TAU + rng() * .3;
    g.beginPath();
    g.arc(x + Math.cos(a) * size * .7, y + Math.sin(a) * size * .7, size * .55, 0, TAU);
    g.fill();
  }
  g.fillStyle = 'rgba(250, 224, 140, .95)';
  g.beginPath();
  g.arc(x, y, size * .38, 0, TAU);
  g.fill();
}

function grassBlade(g, x, y, h, color, lean) {
  g.strokeStyle = color;
  g.lineWidth = 1;
  g.beginPath();
  g.moveTo(x, y);
  g.quadraticCurveTo(x + lean * .4, y - h * .55, x + lean, y - h);
  g.stroke();
}

function drawFence(g, x, y, w, h) {
  const post = (px, py) => {
    g.fillStyle = 'rgba(58, 48, 28, .22)';
    g.beginPath();
    g.ellipse(px + 3, py + 2, 7, 3, 0, 0, TAU);
    g.fill();
    g.fillStyle = '#9a7244';
    g.fillRect(px - 3, py - 20, 6, 23);
    g.fillStyle = '#c39a62';
    g.fillRect(px - 3, py - 20, 2, 23);
    g.fillStyle = '#6e4e2b';
    g.beginPath();
    g.moveTo(px - 4, py - 20);
    g.lineTo(px, py - 25);
    g.lineTo(px + 4, py - 20);
    g.closePath();
    g.fill();
  };
  // rails
  g.strokeStyle = '#b98e57';
  g.lineWidth = 4;
  g.beginPath();
  g.moveTo(x + 8, y - 13);
  g.lineTo(x + w - 8, y - 13);
  g.moveTo(x + 8, y - 6);
  g.lineTo(x + w - 8, y - 6);
  g.stroke();
  g.strokeStyle = 'rgba(255, 236, 198, .35)';
  g.lineWidth = 1;
  g.beginPath();
  g.moveTo(x + 8, y - 14.5);
  g.lineTo(x + w - 8, y - 14.5);
  g.stroke();
  for (let px = x + 8; px <= x + w - 4; px += 32) post(px, y);
  if (h) {
    for (let py = y; py <= y + h; py += 32) {
      post(x, py);
      post(x + w, py);
    }
    g.strokeStyle = '#b98e57';
    g.lineWidth = 4;
    g.beginPath();
    g.moveTo(x, y - 12);
    g.lineTo(x, y + h - 4);
    g.moveTo(x + w, y - 12);
    g.lineTo(x + w, y + h - 4);
    g.stroke();
  }
}

function drawPond(g, pond, rng) {
  const { x, y, rx, ry } = pond;
  g.save();
  // mud bank
  ellipsePath(g, x, y, rx + 24, ry + 20);
  g.fillStyle = '#8b7a55';
  g.fill();
  ellipsePath(g, x, y, rx + 13, ry + 11);
  g.fillStyle = '#a29168';
  g.fill();
  ellipsePath(g, x, y, rx, ry);
  const grad = g.createRadialGradient(x - rx * .3, y - ry * .35, 20, x, y, rx);
  grad.addColorStop(0, '#71aab0');
  grad.addColorStop(.55, '#4e8b99');
  grad.addColorStop(1, '#386c7d');
  g.fillStyle = grad;
  g.fill();
  // ripples
  g.strokeStyle = 'rgba(213, 240, 236, .25)';
  g.lineWidth = 1.2;
  for (let i = 0; i < 9; i++) {
    const rx2 = 24 + rng() * (rx - 40);
    const ry2 = 6 + rng() * (ry - 20);
    g.beginPath();
    g.ellipse(x + (rng() - .5) * rx * 1.1, y + (rng() - .5) * ry * 1.1, rx2, ry2 * .18, 0, 0, TAU);
    g.stroke();
  }
  // lily pads
  const lilies = [[-96, -32], [60, 38], [-38, 52], [118, -44], [8, -66]];
  for (const [lx, ly] of lilies) {
    const px = x + lx, py = y + ly;
    g.fillStyle = '#5f945c';
    g.beginPath();
    g.ellipse(px, py, 13, 8, rng() * TAU, .35, TAU);
    g.closePath();
    g.fill();
    g.strokeStyle = 'rgba(43, 82, 49, .4)';
    g.lineWidth = .8;
    g.stroke();
    if (rng() > .6) {
      g.fillStyle = '#f2c1cf';
      g.beginPath();
      g.arc(px + 2, py - 2, 2.3, 0, TAU);
      g.fill();
    }
  }
  // reeds
  for (let i = 0; i < 20; i++) {
    const a = rng() * TAU;
    const px = x + Math.cos(a) * (rx + 6 + rng() * 18);
    const py = y + Math.sin(a) * (ry + 4 + rng() * 14);
    g.strokeStyle = i % 3 === 0 ? '#5e7c44' : '#78904f';
    g.lineWidth = 1.4;
    g.beginPath();
    g.moveTo(px, py + 4);
    g.quadraticCurveTo(px + (rng() - .5) * 7, py - 10, px + (rng() - .5) * 12, py - 20 - rng() * 8);
    g.stroke();
    if (i % 4 === 0) {
      g.fillStyle = '#8a6337';
      g.beginPath();
      g.ellipse(px + 1, py - 22, 1.8, 4, .2, 0, TAU);
      g.fill();
    }
  }
  g.restore();
}

function drawShopFloor(g, x, y, w, h) {
  g.save();
  g.fillStyle = 'rgba(40, 32, 18, .22)';
  rr(g, x + 5, y + 7, w, h, 10);
  g.fill();
  rr(g, x, y, w, h, 8);
  const grad = g.createLinearGradient(x, y, x, y + h);
  grad.addColorStop(0, '#b58d58');
  grad.addColorStop(1, '#9a7446');
  g.fillStyle = grad;
  g.fill();
  g.strokeStyle = 'rgba(83, 58, 30, .38)';
  g.lineWidth = 1;
  for (let py = y + 18; py < y + h; py += 24) {
    g.beginPath();
    g.moveTo(x + 6, py);
    g.lineTo(x + w - 6, py);
    g.stroke();
    for (let px = x + 20; px < x + w - 10; px += 48) {
      g.fillStyle = 'rgba(70, 47, 22, .22)';
      g.beginPath();
      g.arc(px + (py % 48), py + 9, 1.1, 0, TAU);
      g.fill();
    }
  }
  // green rug under pedestals
  g.fillStyle = 'rgba(30, 54, 35, .28)';
  rr(g, x + 54, y + 168, w - 108, 112, 8);
  g.fill();
  g.fillStyle = 'rgba(64, 96, 62, .55)';
  rr(g, x + 58, y + 172, w - 116, 104, 6);
  g.fill();
  g.strokeStyle = 'rgba(217, 186, 118, .35)';
  g.lineWidth = 1.4;
  rr(g, x + 66, y + 180, w - 132, 88, 4);
  g.stroke();
  // edge trim
  g.strokeStyle = 'rgba(74, 51, 25, .55)';
  g.lineWidth = 2;
  rr(g, x + 1, y + 1, w - 2, h - 2, 8);
  g.stroke();
  g.restore();
}

function drawSignpost(g, x, y, label, angle = 0) {
  g.save();
  g.translate(x, y);
  g.rotate(angle);
  g.fillStyle = 'rgba(40, 31, 18, .22)';
  g.beginPath();
  g.ellipse(3, 2, 9, 3, 0, 0, TAU);
  g.fill();
  g.fillStyle = '#7b5732';
  g.fillRect(-2.5, -20, 5, 23);
  g.fillStyle = '#a87b48';
  rr(g, -34, -40, 68, 20, 3);
  g.fill();
  g.strokeStyle = 'rgba(74, 50, 24, .55)';
  g.lineWidth = 1;
  rr(g, -34, -40, 68, 20, 3);
  g.stroke();
  g.fillStyle = '#4e3a20';
  g.font = 'bold 7px "Avenir Next", sans-serif';
  g.textAlign = 'center';
  g.textBaseline = 'middle';
  g.fillText(label, 0, -29.5);
  g.restore();
}

export function buildGround(world) {
  const c = document.createElement('canvas');
  c.width = Math.round(WORLD.w * GROUND_SCALE);
  c.height = Math.round(WORLD.h * GROUND_SCALE);
  const g = c.getContext('2d');
  g.scale(GROUND_SCALE, GROUND_SCALE);
  const rng = mulberry32(73921);

  // base meadow
  const base = g.createLinearGradient(0, 0, 0, WORLD.h);
  base.addColorStop(0, '#7ca868');
  base.addColorStop(.5, '#6f9d5d');
  base.addColorStop(1, '#618d51');
  g.fillStyle = base;
  g.fillRect(0, 0, WORLD.w, WORLD.h);

  // broad soft patches
  for (let i = 0; i < 120; i++) {
    const x = rng() * WORLD.w, y = rng() * WORLD.h;
    const rx = 60 + rng() * 210, ry = 40 + rng() * 150;
    const grad = g.createRadialGradient(x, y, 0, x, y, Math.max(rx, ry));
    const tint = rng();
    const col = tint > .62 ? '126, 168, 103' : tint > .3 ? '91, 133, 76' : '143, 180, 111';
    grad.addColorStop(0, `rgba(${col}, .16)`);
    grad.addColorStop(1, `rgba(${col}, 0)`);
    g.fillStyle = grad;
    g.beginPath();
    g.ellipse(x, y, rx, ry, rng() * TAU, 0, TAU);
    g.fill();
  }

  // forest floor + quarry ground
  g.fillStyle = 'rgba(52, 84, 47, .24)';
  g.beginPath();
  g.ellipse(1200, 470, 470, 320, -.05, 0, TAU);
  g.fill();
  g.fillStyle = 'rgba(101, 97, 82, .28)';
  g.beginPath();
  g.moveTo(1620, 840);
  g.quadraticCurveTo(1640, 380, 1850, 300);
  g.quadraticCurveTo(2110, 220, 2240, 420);
  g.quadraticCurveTo(2320, 700, 2130, 830);
  g.quadraticCurveTo(1850, 900, 1620, 840);
  g.fill();

  // paths
  paintPath(g, [{ x: 1220, y: 820 }, { x: 1220, y: 1640 }], 148, rng);
  paintPath(g, [{ x: 500, y: 986 }, { x: 1940, y: 986 }], 126, rng);
  paintPath(g, [{ x: 600, y: 986 }, { x: 600, y: 772 }], 104, rng);
  paintPath(g, [{ x: 1862, y: 986 }, { x: 1988, y: 700 }], 98, rng);
  paintPath(g, [{ x: 1220, y: 826 }, { x: 1220, y: 600 }], 96, rng);

  // meadow grass blades
  const bladeColors = ['rgba(64, 104, 54, .4)', 'rgba(104, 148, 82, .45)', 'rgba(139, 174, 105, .38)', 'rgba(52, 90, 48, .3)'];
  for (let i = 0; i < 5200; i++) {
    const x = rng() * WORLD.w, y = rng() * WORLD.h;
    if (Math.hypot(x - 1220, y - 1450) < 300) continue;
    const h = 2 + rng() * 5;
    grassBlade(g, x, y, h, bladeColors[(rng() * bladeColors.length) | 0], (rng() - .5) * 4);
  }

  // wildflowers
  const flowerCols = ['#f4df9d', '#f0b3c4', '#c7b9ef', '#f2f0dc', '#e7a67a'];
  for (let i = 0; i < 680; i++) {
    const x = rng() * WORLD.w, y = rng() * WORLD.h;
    if (Math.hypot(x - 1220, y - 1450) < 250) continue;
    if (Math.abs(x - 1220) < 90 && y > 800) continue;
    if (Math.abs(y - 986) < 70 && x > 480 && x < 1960) continue;
    if (x > 360 && x < 880 && y > 550 && y < 760) continue;
    flower(g, x, y, flowerCols[(rng() * flowerCols.length) | 0], 1.1 + rng() * 1.6, rng);
  }

  // little stones in the meadow
  for (let i = 0; i < 110; i++) {
    const x = rng() * WORLD.w, y = rng() * WORLD.h;
    g.fillStyle = `rgba(${120 + rng() * 40}, ${118 + rng() * 36}, ${100 + rng() * 34}, .55)`;
    g.beginPath();
    g.ellipse(x, y, 1.5 + rng() * 3.4, 1 + rng() * 2.4, rng() * TAU, 0, TAU);
    g.fill();
  }

  // farm soil
  g.save();
  g.fillStyle = 'rgba(66, 52, 30, .22)';
  rr(g, 372, 560, 508, 198, 14);
  g.fill();
  g.fillStyle = '#7c5f3d';
  rr(g, 376, 564, 500, 190, 12);
  g.fill();
  g.fillStyle = 'rgba(111, 84, 52, .8)';
  for (let i = 0; i < 10; i++) {
    g.fillRect(384, 572 + i * 19, 484, 2);
  }
  g.restore();
  // crop patch signs
  drawSignpost(g, 456, 572, 'TURNIP', -.03);
  drawSignpost(g, 620, 572, 'WHEAT', .02);
  drawSignpost(g, 784, 572, 'SUNBLOOM', -.02);

  // farm fence
  drawFence(g, 350, 548, 532, 0);
  drawFence(g, 350, 548, 0, 196);
  drawFence(g, 882, 548, 0, 196);
  drawFence(g, 350, 748, 236, 0);
  drawFence(g, 664, 748, 218, 0);

  // pond
  drawPond(g, world.pond, rng);

  // shop floor
  drawShopFloor(g, 990, 1290, 470, 370);

  // shop path lantern glow pools (subtle static)
  for (const l of world.lanterns) {
    const grad = g.createRadialGradient(l.x, l.y, 2, l.x, l.y, 74);
    grad.addColorStop(0, 'rgba(245, 203, 112, .12)');
    grad.addColorStop(1, 'rgba(245, 203, 112, 0)');
    g.fillStyle = grad;
    g.beginPath();
    g.arc(l.x, l.y, 74, 0, TAU);
    g.fill();
  }

  // signposts
  drawSignpost(g, 1108, 1062, 'SHOP', -.05);
  drawSignpost(g, 1780, 1076, 'QUARRY', .04);
  drawSignpost(g, 658, 1040, 'FARM', -.04);
  drawSignpost(g, 1264, 790, 'OAKWOOD', .03);

  // path-side detail: lantern posts base stones, footprints
  for (let i = 0; i < 60; i++) {
    const x = 1180 + (rng() - .5) * 120;
    const y = 860 + rng() * 720;
    g.fillStyle = 'rgba(104, 82, 52, .16)';
    g.beginPath();
    g.ellipse(x, y, 2.5, 1.2, rng() * .4, 0, TAU);
    g.fill();
  }

  // small hay scatter near barn
  for (let i = 0; i < 24; i++) {
    const x = 470 + rng() * 130, y = 530 + rng() * 24;
    g.strokeStyle = 'rgba(214, 177, 91, .55)';
    g.lineWidth = 1;
    g.beginPath();
    g.moveTo(x, y);
    g.lineTo(x + (rng() - .5) * 8, y + 2 + rng() * 3);
    g.stroke();
  }

  // border shading
  const edge = g.createRadialGradient(WORLD.w / 2, WORLD.h / 2, 620, WORLD.w / 2, WORLD.h / 2, 1450);
  edge.addColorStop(0, 'rgba(20, 40, 24, 0)');
  edge.addColorStop(1, 'rgba(20, 40, 24, .26)');
  g.fillStyle = edge;
  g.fillRect(0, 0, WORLD.w, WORLD.h);

  return c;
}

/* ============================================================
   IRONROOT & IVY — procedural world art
   ============================================================ */
import { TAU, rr, ellipsePath, hash, CROPS, WEAPONS } from './data.js';

/* ---------------- weapons ---------------- */
export function drawWeapon(ctx, id, x, y, scale = 1, angle = 0, opts = {}) {
  const w = WEAPONS[id];
  if (!w) return;
  const p = w.palette;
  ctx.save();
  ctx.translate(x, y);
  ctx.rotate(angle);
  ctx.scale(scale, scale);
  if (opts.glow) {
    ctx.shadowColor = p.accent;
    ctx.shadowBlur = 16;
  }
  ctx.lineJoin = 'round';
  ctx.lineCap = 'round';

  if (w.kind === 'sword') {
    // blade
    ctx.beginPath();
    ctx.moveTo(0, -36);
    ctx.lineTo(4.2, -29);
    ctx.lineTo(4.2, 1);
    ctx.lineTo(0, 5);
    ctx.lineTo(-4.2, 1);
    ctx.lineTo(-4.2, -29);
    ctx.closePath();
    ctx.fillStyle = p.metal;
    ctx.fill();
    ctx.strokeStyle = p.dark;
    ctx.lineWidth = 1.1;
    ctx.stroke();
    // edge highlight
    ctx.beginPath();
    ctx.moveTo(-1.8, -32.5);
    ctx.lineTo(-1.8, 0);
    ctx.strokeStyle = p.edge;
    ctx.lineWidth = 1.2;
    ctx.stroke();
    // fuller
    ctx.beginPath();
    ctx.moveTo(1.4, -26);
    ctx.lineTo(1.4, -1);
    ctx.strokeStyle = 'rgba(50, 64, 72, .3)';
    ctx.lineWidth = .8;
    ctx.stroke();
    // guard
    ctx.beginPath();
    ctx.moveTo(-11, 4);
    ctx.quadraticCurveTo(0, 8.5, 11, 4);
    ctx.quadraticCurveTo(0, 10.5, -11, 4);
    ctx.fillStyle = p.accent;
    ctx.fill();
    ctx.strokeStyle = p.dark;
    ctx.lineWidth = 1;
    ctx.stroke();
    // grip
    rr(ctx, -3.2, 7, 6.4, 13, 2.4);
    ctx.fillStyle = p.grip;
    ctx.fill();
    ctx.strokeStyle = 'rgba(43, 27, 12, .55)';
    ctx.lineWidth = .8;
    ctx.stroke();
    for (let i = 0; i < 3; i++) {
      ctx.beginPath();
      ctx.moveTo(-3.2, 9.5 + i * 3.6);
      ctx.lineTo(3.2, 10.7 + i * 3.6);
      ctx.strokeStyle = 'rgba(238, 220, 180, .4)';
      ctx.lineWidth = .8;
      ctx.stroke();
    }
    // pommel
    ctx.beginPath();
    ctx.arc(0, 22, 3.1, 0, TAU);
    ctx.fillStyle = p.accent;
    ctx.fill();
    ctx.strokeStyle = p.dark;
    ctx.lineWidth = .8;
    ctx.stroke();
  } else if (w.kind === 'axe') {
    // handle
    ctx.beginPath();
    ctx.moveTo(-1.5, 26);
    ctx.lineTo(2.5, -24);
    ctx.strokeStyle = p.grip;
    ctx.lineWidth = 4.4;
    ctx.stroke();
    ctx.beginPath();
    ctx.moveTo(-1.5, 26);
    ctx.lineTo(2.5, -24);
    ctx.strokeStyle = 'rgba(244, 218, 171, .25)';
    ctx.lineWidth = 1.2;
    ctx.stroke();
    // head
    ctx.beginPath();
    ctx.moveTo(2, -27);
    ctx.quadraticCurveTo(17, -34, 21, -22);
    ctx.quadraticCurveTo(17, -12, 3, -10);
    ctx.quadraticCurveTo(7, -19, 2, -27);
    ctx.closePath();
    ctx.fillStyle = p.metal;
    ctx.fill();
    ctx.strokeStyle = p.dark;
    ctx.lineWidth = 1.2;
    ctx.stroke();
    ctx.beginPath();
    ctx.moveTo(5, -26);
    ctx.quadraticCurveTo(16, -31, 19, -22);
    ctx.strokeStyle = p.edge;
    ctx.lineWidth = 1.1;
    ctx.stroke();
    // crystal spikes
    if (id === 'greataxe') {
      for (let i = 0; i < 3; i++) {
        ctx.beginPath();
        ctx.moveTo(6 + i * 3.5, -15 - i * 1.2);
        ctx.lineTo(10 + i * 3.5, -22 - i * 2.5);
        ctx.lineTo(12 + i * 3.5, -14 - i * 1.2);
        ctx.closePath();
        ctx.fillStyle = 'rgba(185, 166, 241, .9)';
        ctx.fill();
        ctx.strokeStyle = '#6c58ad';
        ctx.lineWidth = .7;
        ctx.stroke();
      }
    }
    // grip wrap
    for (let i = 0; i < 3; i++) {
      ctx.beginPath();
      ctx.moveTo(-1.8, 4 + i * 5);
      ctx.lineTo(1.6, 5.2 + i * 5);
      ctx.strokeStyle = 'rgba(240, 220, 180, .35)';
      ctx.lineWidth = 1;
      ctx.stroke();
    }
  } else if (w.kind === 'scythe') {
    // snath
    ctx.beginPath();
    ctx.moveTo(3, 27);
    ctx.quadraticCurveTo(-1, 2, -7, -26);
    ctx.strokeStyle = p.grip;
    ctx.lineWidth = 4;
    ctx.stroke();
    ctx.beginPath();
    ctx.moveTo(3, 27);
    ctx.quadraticCurveTo(-1, 2, -7, -26);
    ctx.strokeStyle = 'rgba(246, 220, 175, .22)';
    ctx.lineWidth = 1;
    ctx.stroke();
    // blade
    ctx.beginPath();
    ctx.moveTo(-7, -26);
    ctx.bezierCurveTo(6, -37, 20, -30, 24, -17);
    ctx.bezierCurveTo(16, -22, 5, -22, -7, -26);
    ctx.closePath();
    ctx.fillStyle = p.metal;
    ctx.fill();
    ctx.strokeStyle = p.dark;
    ctx.lineWidth = 1.2;
    ctx.stroke();
    ctx.beginPath();
    ctx.moveTo(-5, -25);
    ctx.bezierCurveTo(7, -33, 18, -28, 21, -19);
    ctx.strokeStyle = p.edge;
    ctx.lineWidth = 1.1;
    ctx.stroke();
    // binding
    ctx.beginPath();
    ctx.moveTo(-9, -22);
    ctx.lineTo(-4, -27);
    ctx.strokeStyle = p.accent;
    ctx.lineWidth = 2.4;
    ctx.stroke();
  }
  ctx.restore();
}

export function drawWeaponIcon(canvas, id) {
  const dpr = Math.min(window.devicePixelRatio || 1, 2);
  const size = 74;
  canvas.width = size * dpr;
  canvas.height = size * dpr;
  const ctx = canvas.getContext('2d');
  ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
  ctx.clearRect(0, 0, size, size);
  const grad = ctx.createRadialGradient(size / 2, size * .42, 2, size / 2, size * .5, size * .55);
  grad.addColorStop(0, 'rgba(216, 165, 65, .17)');
  grad.addColorStop(1, 'rgba(63, 78, 58, 0)');
  ctx.fillStyle = grad;
  ctx.fillRect(0, 0, size, size);
  drawWeapon(ctx, id, size / 2, size / 2 + 3, 1.16, -0.08, { glow: true });
}

/* ---------------- farm plots ---------------- */
export function drawPlot(ctx, p, t) {
  const { x, y, w, h } = p;
  ctx.save();
  // soil
  ctx.fillStyle = 'rgba(50, 38, 20, .22)';
  rr(ctx, x + 2, y + 4, w, h, 7);
  ctx.fill();
  const soil = ctx.createLinearGradient(x, y, x, y + h);
  if (p.watered) {
    soil.addColorStop(0, '#5c452b');
    soil.addColorStop(1, '#49361f');
  } else {
    soil.addColorStop(0, '#775736');
    soil.addColorStop(1, '#624729');
  }
  ctx.fillStyle = soil;
  rr(ctx, x, y, w, h, 6);
  ctx.fill();
  ctx.strokeStyle = 'rgba(44, 32, 16, .35)';
  ctx.lineWidth = 1;
  rr(ctx, x + .5, y + .5, w - 1, h - 1, 6);
  ctx.stroke();
  // furrows
  for (let i = 0; i < 4; i++) {
    ctx.strokeStyle = p.watered ? 'rgba(36, 27, 14, .38)' : 'rgba(87, 64, 37, .5)';
    ctx.lineWidth = 1.4;
    ctx.beginPath();
    ctx.moveTo(x + 8, y + 12 + i * 13);
    ctx.quadraticCurveTo(x + w / 2, y + 10 + i * 13, x + w - 8, y + 12 + i * 13);
    ctx.stroke();
    ctx.strokeStyle = 'rgba(179, 141, 91, .22)';
    ctx.lineWidth = .8;
    ctx.beginPath();
    ctx.moveTo(x + 8, y + 13.5 + i * 13);
    ctx.quadraticCurveTo(x + w / 2, y + 11.5 + i * 13, x + w - 8, y + 13.5 + i * 13);
    ctx.stroke();
  }
  // water sheen
  if (p.watered) {
    for (let i = 0; i < 5; i++) {
      const wx = x + 9 + hash(i, x) * (w - 18);
      const wy = y + 9 + hash(y, i) * (h - 18);
      ctx.fillStyle = 'rgba(140, 196, 208, .28)';
      ctx.beginPath();
      ctx.ellipse(wx, wy, 2.4, 1.1, -.3, 0, TAU);
      ctx.fill();
    }
  }
  if (!p.empty) drawCrop(ctx, p, t);
  ctx.restore();
}

function drawCrop(ctx, p, t) {
  const crop = CROPS[p.crop];
  const cx = p.cx;
  const cy = p.cy + 16;
  const stage = p.stage;
  const sway = Math.sin(t * 1.8 + p.sway) * (1 + stage * .35);
  const scale = [.34, .58, .82, 1][stage] || 1;
  ctx.save();
  ctx.translate(cx, cy);
  // little shadow
  ctx.fillStyle = 'rgba(40, 30, 14, .22)';
  ctx.beginPath();
  ctx.ellipse(0, 2, 15 * scale, 4 * scale, 0, 0, TAU);
  ctx.fill();

  if (p.crop === 'turnip') {
    for (let i = 0; i < 5; i++) {
      const a = -Math.PI / 2 + (i - 2) * .38 + sway * .012;
      const len = 22 * scale;
      ctx.strokeStyle = i % 2 ? '#5c9a52' : '#75ad62';
      ctx.lineWidth = 2.2 * scale;
      ctx.beginPath();
      ctx.moveTo(0, 0);
      ctx.quadraticCurveTo(Math.cos(a) * len * .55 + sway * .3, Math.sin(a) * len * .55, Math.cos(a) * len + sway, Math.sin(a) * len);
      ctx.stroke();
      ctx.fillStyle = i % 2 ? '#7fb76a' : '#8fc377';
      ctx.beginPath();
      ctx.ellipse(Math.cos(a) * len * .78 + sway * .6, Math.sin(a) * len * .78, 4.2 * scale, 2.4 * scale, a, 0, TAU);
      ctx.fill();
    }
    if (stage >= 2) {
      ctx.fillStyle = '#e59ab5';
      ctx.beginPath();
      ctx.ellipse(0, 1, 7.5 * scale, 6.5 * scale, 0, 0, TAU);
      ctx.fill();
      ctx.fillStyle = 'rgba(255, 213, 227, .55)';
      ctx.beginPath();
      ctx.ellipse(-2 * scale, -1.5 * scale, 2.4 * scale, 1.6 * scale, -.5, 0, TAU);
      ctx.fill();
    }
  } else if (p.crop === 'wheat') {
    for (let i = 0; i < 7; i++) {
      const ox = (i - 3) * 4.4 * scale;
      const hgt = (18 + (i % 3) * 5) * scale;
      const lean = sway * (1 + i * .1) + (i - 3) * 1.1;
      ctx.strokeStyle = '#b9953f';
      ctx.lineWidth = 1.2;
      ctx.beginPath();
      ctx.moveTo(ox, 0);
      ctx.quadraticCurveTo(ox + lean * .4, -hgt * .55, ox + lean, -hgt);
      ctx.stroke();
      if (stage >= 2) {
        ctx.fillStyle = stage >= 3 ? '#e2bc55' : '#c9a746';
        for (let k = 0; k < 3; k++) {
          ctx.beginPath();
          ctx.ellipse(ox + lean + (k - 1) * 1.8, -hgt + k * 3.2, 1.7, 3.2, .35, 0, TAU);
          ctx.fill();
        }
      }
    }
  } else {
    // sunbloom
    const hgt = 24 * scale;
    ctx.strokeStyle = '#5f9c55';
    ctx.lineWidth = 2 * scale;
    ctx.beginPath();
    ctx.moveTo(0, 0);
    ctx.quadraticCurveTo(sway * .4, -hgt * .55, sway, -hgt);
    ctx.stroke();
    // leaves
    for (const side of [-1, 1]) {
      ctx.fillStyle = '#6eaa5d';
      ctx.beginPath();
      ctx.ellipse(side * 6 * scale, -hgt * .45, 6.5 * scale, 3 * scale, side * .55, 0, TAU);
      ctx.fill();
    }
    if (stage >= 2) {
      const fx = sway, fy = -hgt;
      const open = stage >= 3 ? 1 : .55;
      ctx.fillStyle = '#f2c75b';
      for (let i = 0; i < 8; i++) {
        const a = (i / 8) * TAU + sway * .01;
        ctx.beginPath();
        ctx.ellipse(fx + Math.cos(a) * 6 * open, fy + Math.sin(a) * 6 * open, 4.2 * open, 2.6 * open, a, 0, TAU);
        ctx.fill();
      }
      ctx.fillStyle = '#d98a2f';
      ctx.beginPath();
      ctx.arc(fx, fy, 3.3 * open, 0, TAU);
      ctx.fill();
      ctx.fillStyle = 'rgba(255, 245, 190, .65)';
      ctx.beginPath();
      ctx.arc(fx - 1, fy - 1, 1.1, 0, TAU);
      ctx.fill();
    }
  }
  // ripe sparkle
  if (stage >= 3) {
    const sp = .5 + Math.sin(t * 3 + p.sway) * .5;
    ctx.fillStyle = `rgba(255, 231, 151, ${.35 + sp * .5})`;
    for (const [sx, sy, ss] of [[-18, -20, 2.4], [16, -28, 1.8], [20, -8, 1.4]]) {
      ctx.beginPath();
      ctx.arc(sx + sway * .4, sy, ss, 0, TAU);
      ctx.fill();
    }
  }
  ctx.restore();
}

/* ---------------- trees & rocks ---------------- */
export function drawTree(ctx, node, t, deco = false) {
  const s = node.size || node.s || 1;
  const x = node.x;
  const y = node.y;
  const sway = Math.sin(t * .9 + (node.sway || 0)) * 2.2;
  const shake = node.shake > 0 ? Math.sin(node.shake * 45) * node.shake * 9 : 0;
  ctx.save();
  ctx.translate(x + shake, y);
  // shadow
  ctx.fillStyle = 'rgba(35, 48, 27, .26)';
  ctx.beginPath();
  ctx.ellipse(4 * s, 3 * s, 28 * s, 9 * s, 0, 0, TAU);
  ctx.fill();

  if (node.alive === false) {
    // stump
    ctx.fillStyle = '#6f4c2a';
    rr(ctx, -10 * s, -15 * s, 20 * s, 16 * s, 4);
    ctx.fill();
    ctx.fillStyle = '#c49a61';
    ctx.beginPath();
    ctx.ellipse(0, -15 * s, 10 * s, 4.5 * s, 0, 0, TAU);
    ctx.fill();
    ctx.strokeStyle = '#8b6438';
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.ellipse(0, -15 * s, 5.5 * s, 2.4 * s, 0, 0, TAU);
    ctx.stroke();
    ctx.restore();
    return;
  }

  // trunk
  const trunk = ctx.createLinearGradient(-8 * s, 0, 8 * s, 0);
  trunk.addColorStop(0, '#5e4024');
  trunk.addColorStop(.45, '#8d6237');
  trunk.addColorStop(1, '#5a3d22');
  ctx.fillStyle = trunk;
  ctx.beginPath();
  ctx.moveTo(-8 * s, 2);
  ctx.quadraticCurveTo(-6 * s, -26 * s, -4 * s, -44 * s);
  ctx.lineTo(4 * s, -44 * s);
  ctx.quadraticCurveTo(6 * s, -26 * s, 8 * s, 2);
  ctx.closePath();
  ctx.fill();
  ctx.strokeStyle = 'rgba(54, 36, 18, .4)';
  ctx.lineWidth = .8;
  for (let i = 0; i < 3; i++) {
    ctx.beginPath();
    ctx.moveTo(-3 * s + i * 3 * s, -3);
    ctx.quadraticCurveTo(-4 * s + i * 2 * s, -20 * s, -2 * s + i * 2 * s, -38 * s);
    ctx.stroke();
  }
  // roots
  ctx.strokeStyle = '#6a4928';
  ctx.lineWidth = 2.2 * s;
  ctx.beginPath();
  ctx.moveTo(-7 * s, 0);
  ctx.quadraticCurveTo(-13 * s, 1, -17 * s, 4);
  ctx.moveTo(7 * s, 0);
  ctx.quadraticCurveTo(13 * s, 1, 18 * s, 3);
  ctx.stroke();
  // axe cuts
  if (!deco && node.hp < node.maxHp) {
    ctx.strokeStyle = 'rgba(238, 219, 180, .75)';
    ctx.lineWidth = 1.4;
    for (let i = 0; i < node.maxHp - node.hp; i++) {
      ctx.beginPath();
      ctx.moveTo(2 * s, -12 * s - i * 7 * s);
      ctx.lineTo(8 * s, -8 * s - i * 7 * s);
      ctx.stroke();
    }
  }

  // canopy
  const cy = -55 * s;
  const blobs = [
    [-17, 8, 20, 17], [17, 7, 21, 18], [0, -8, 26, 22], [-9, 19, 19, 15],
    [12, 21, 17, 14], [0, 8, 29, 22],
  ];
  ctx.save();
  ctx.translate(sway * .6, 0);
  for (let i = 0; i < blobs.length; i++) {
    const [bx, by, brx, bry] = blobs[i];
    const g = ctx.createRadialGradient(
      bx * s - brx * .35, cy + by * s - bry * .4, 2,
      bx * s, cy + by * s, brx * s
    );
    const dark = i > 3;
    g.addColorStop(0, dark ? '#5a8c4c' : '#78aa5c');
    g.addColorStop(.72, dark ? '#467a43' : '#5f974e');
    g.addColorStop(1, dark ? '#356237' : '#4a803f');
    ctx.fillStyle = g;
    ctx.beginPath();
    ctx.ellipse(bx * s, cy + by * s, brx * s, bry * s, (hash(i, x) - .5) * .5, 0, TAU);
    ctx.fill();
  }
  // leaf highlights
  ctx.fillStyle = 'rgba(177, 208, 126, .42)';
  for (const [hx, hy, hr] of [[-18, -18, 4.2], [-7, -26, 3.2], [12, -18, 3.6], [2, -5, 2.8], [20, 2, 2.4]]) {
    ctx.beginPath();
    ctx.arc(hx * s + sway * .8, cy + hy * s, hr * s, 0, TAU);
    ctx.fill();
  }
  // tiny fruit / golden leaves
  if (hash(x, y) > .62) {
    ctx.fillStyle = 'rgba(232, 186, 82, .8)';
    for (let i = 0; i < 4; i++) {
      ctx.beginPath();
      ctx.arc((hash(i, x) - .5) * 44 * s, cy + (hash(i, y) - .5) * 32 * s, 1.6 * s, 0, TAU);
      ctx.fill();
    }
  }
  ctx.restore();
  ctx.restore();
}

export function drawRock(ctx, node, t) {
  const x = node.x;
  const y = node.y;
  const isCrystal = node.resource === 'crystal';
  const isIron = node.resource === 'iron';
  const shake = node.shake > 0 ? Math.sin(node.shake * 55) * node.shake * 8 : 0;
  const s = node.size || 1;
  ctx.save();
  ctx.translate(x + shake, y);
  ctx.fillStyle = 'rgba(35, 40, 30, .26)';
  ctx.beginPath();
  ctx.ellipse(3, 2, 25 * s, 8 * s, 0, 0, TAU);
  ctx.fill();

  if (!node.alive) {
    ctx.fillStyle = '#7f8178';
    for (const [rx, ry, rr2] of [[-10, 0, 5], [6, -2, 6], [14, 2, 4], [-2, 3, 3.5]]) {
      ctx.beginPath();
      ctx.ellipse(rx, ry, rr2, rr2 * .65, 0, 0, TAU);
      ctx.fill();
    }
    ctx.restore();
    return;
  }

  const base = isCrystal ? '#6d6296' : isIron ? '#8b8378' : '#92978f';
  const dark = isCrystal ? '#453b6e' : isIron ? '#5d554b' : '#5d645c';
  const light = isCrystal ? '#b4a5e8' : isIron ? '#b9a68c' : '#c3c7bd';

  ctx.beginPath();
  ctx.moveTo(-23 * s, 0);
  ctx.lineTo(-19 * s, -18 * s);
  ctx.lineTo(-7 * s, -30 * s);
  ctx.lineTo(10 * s, -28 * s);
  ctx.lineTo(22 * s, -15 * s);
  ctx.lineTo(19 * s, 0);
  ctx.closePath();
  const g = ctx.createLinearGradient(-20 * s, -30 * s, 20 * s, 2);
  g.addColorStop(0, light);
  g.addColorStop(.5, base);
  g.addColorStop(1, dark);
  ctx.fillStyle = g;
  ctx.fill();
  ctx.strokeStyle = dark;
  ctx.lineWidth = 1.2;
  ctx.stroke();

  // facets
  ctx.strokeStyle = 'rgba(48, 50, 43, .3)';
  ctx.lineWidth = 1;
  ctx.beginPath();
  ctx.moveTo(-7 * s, -30 * s);
  ctx.lineTo(-3 * s, -10 * s);
  ctx.lineTo(7 * s, 0);
  ctx.moveTo(10 * s, -28 * s);
  ctx.lineTo(3 * s, -11 * s);
  ctx.lineTo(-3 * s, -10 * s);
  ctx.moveTo(22 * s, -15 * s);
  ctx.lineTo(3 * s, -11 * s);
  ctx.stroke();

  if (isIron) {
    ctx.strokeStyle = 'rgba(168, 95, 55, .65)';
    ctx.lineWidth = 1.4;
    ctx.beginPath();
    ctx.moveTo(-15 * s, -20 * s);
    ctx.lineTo(-7 * s, -12 * s);
    ctx.lineTo(-10 * s, -4 * s);
    ctx.moveTo(5 * s, -22 * s);
    ctx.lineTo(12 * s, -15 * s);
    ctx.stroke();
    ctx.fillStyle = 'rgba(198, 126, 72, .55)';
    ctx.beginPath();
    ctx.arc(13 * s, -18 * s, 2.4 * s, 0, TAU);
    ctx.fill();
  }
  if (isCrystal) {
    const pulse = .55 + Math.sin(t * 2 + x) * .2;
    for (const [cx, cy2, h, w] of [[-6, -24, 20, 4.2], [6, -26, 24, 4.8], [14, -20, 16, 3.4]]) {
      ctx.beginPath();
      ctx.moveTo(cx * s, (cy2 - h) * s);
      ctx.lineTo((cx + w) * s, (cy2 - h * .45) * s);
      ctx.lineTo((cx + w * .5) * s, (cy2 + 2) * s);
      ctx.lineTo((cx - w * .5) * s, (cy2 + 2) * s);
      ctx.lineTo((cx - w) * s, (cy2 - h * .45) * s);
      ctx.closePath();
      ctx.fillStyle = `rgba(174, 153, 235, ${pulse + .22})`;
      ctx.fill();
      ctx.strokeStyle = '#5f4c9f';
      ctx.lineWidth = .9;
      ctx.stroke();
      ctx.strokeStyle = 'rgba(237, 227, 255, .65)';
      ctx.beginPath();
      ctx.moveTo(cx * s, (cy2 - h) * s);
      ctx.lineTo((cx - w * .4) * s, (cy2 - h * .35) * s);
      ctx.stroke();
    }
  }
  // cracks by damage
  const dmg = node.maxHp - node.hp;
  if (dmg > 0) {
    ctx.strokeStyle = 'rgba(45, 45, 38, .5)';
    ctx.lineWidth = 1.2;
    for (let i = 0; i < dmg; i++) {
      ctx.beginPath();
      ctx.moveTo((-6 + i * 6) * s, -22 * s);
      ctx.lineTo((-2 + i * 5) * s, -14 * s);
      ctx.lineTo((-5 + i * 4) * s, -7 * s);
      ctx.stroke();
    }
  }
  ctx.restore();
}

/* ---------------- small props ---------------- */
export function drawBush(ctx, b, t) {
  const s = b.s || 1;
  const sway = Math.sin(t * 1.3 + b.x) * 1.1;
  ctx.save();
  ctx.translate(b.x, b.y);
  ctx.fillStyle = 'rgba(32, 46, 26, .22)';
  ctx.beginPath();
  ctx.ellipse(2, 2, 20 * s, 6 * s, 0, 0, TAU);
  ctx.fill();
  for (const [bx, by, br, col] of [[-9, -8, 12, '#4c7a43'], [8, -9, 13, '#548448'], [0, -15, 14, '#5f914f'], [-3, -4, 12, '#46723e']]) {
    ctx.fillStyle = col;
    ctx.beginPath();
    ctx.ellipse(bx * s + sway * .4, by * s, br * s, br * .82 * s, 0, 0, TAU);
    ctx.fill();
  }
  ctx.fillStyle = 'rgba(163, 198, 116, .4)';
  for (let i = 0; i < 5; i++) {
    ctx.beginPath();
    ctx.arc((hash(i, b.x) - .5) * 22 * s, -11 * s + (hash(i, b.y) - .5) * 12 * s, 1.7 * s, 0, TAU);
    ctx.fill();
  }
  if (hash(b.x, b.y) > .55) {
    ctx.fillStyle = '#d77c75';
    for (let i = 0; i < 3; i++) {
      ctx.beginPath();
      ctx.arc((hash(i + 9, b.x) - .5) * 22 * s, -9 * s + (hash(i + 4, b.y) - .5) * 12 * s, 1.7 * s, 0, TAU);
      ctx.fill();
    }
  }
  ctx.restore();
}

export function drawHay(ctx, o) {
  const s = o.s || 1;
  ctx.save();
  ctx.translate(o.x, o.y);
  ctx.fillStyle = 'rgba(40, 34, 18, .22)';
  ctx.beginPath();
  ctx.ellipse(2, 2, 17 * s, 6 * s, 0, 0, TAU);
  ctx.fill();
  const g = ctx.createLinearGradient(0, -22 * s, 0, 0);
  g.addColorStop(0, '#d7b45f');
  g.addColorStop(1, '#a8813b');
  ctx.fillStyle = g;
  rr(ctx, -16 * s, -22 * s, 32 * s, 22 * s, 6 * s);
  ctx.fill();
  ctx.strokeStyle = 'rgba(132, 95, 39, .5)';
  ctx.lineWidth = 1;
  for (let i = 0; i < 6; i++) {
    ctx.beginPath();
    ctx.moveTo(-14 * s, -19 * s + i * 3.2 * s);
    ctx.lineTo(14 * s, -18 * s + i * 3.2 * s);
    ctx.stroke();
  }
  ctx.strokeStyle = '#7d5c2d';
  ctx.lineWidth = 2;
  ctx.beginPath();
  ctx.moveTo(-16 * s, -15 * s);
  ctx.lineTo(16 * s, -15 * s);
  ctx.moveTo(-16 * s, -7 * s);
  ctx.lineTo(16 * s, -7 * s);
  ctx.stroke();
  ctx.restore();
}

export function drawCrate(ctx, o) {
  const s = o.s || 1;
  ctx.save();
  ctx.translate(o.x, o.y);
  ctx.fillStyle = 'rgba(38, 30, 18, .22)';
  ctx.beginPath();
  ctx.ellipse(2, 2, 16 * s, 5 * s, 0, 0, TAU);
  ctx.fill();
  ctx.fillStyle = '#a87b49';
  rr(ctx, -15 * s, -25 * s, 30 * s, 25 * s, 2);
  ctx.fill();
  ctx.strokeStyle = '#76522c';
  ctx.lineWidth = 1.4;
  rr(ctx, -15 * s, -25 * s, 30 * s, 25 * s, 2);
  ctx.stroke();
  ctx.strokeStyle = 'rgba(111, 76, 38, .55)';
  ctx.lineWidth = 1;
  ctx.beginPath();
  ctx.moveTo(-15 * s, -12 * s);
  ctx.lineTo(15 * s, -12 * s);
  ctx.moveTo(-2 * s, -25 * s);
  ctx.lineTo(-2 * s, 0);
  ctx.stroke();
  ctx.fillStyle = 'rgba(232, 200, 145, .35)';
  ctx.fillRect(-15 * s, -25 * s, 30 * s, 2);
  ctx.restore();
}

export function drawBarrel(ctx, o) {
  const s = o.s || 1;
  ctx.save();
  ctx.translate(o.x, o.y);
  ctx.fillStyle = 'rgba(38, 30, 18, .22)';
  ctx.beginPath();
  ctx.ellipse(2, 2, 13 * s, 5 * s, 0, 0, TAU);
  ctx.fill();
  const g = ctx.createLinearGradient(-12 * s, 0, 12 * s, 0);
  g.addColorStop(0, '#74502e');
  g.addColorStop(.45, '#a57644');
  g.addColorStop(1, '#6c4928');
  ctx.fillStyle = g;
  rr(ctx, -12 * s, -26 * s, 24 * s, 26 * s, 7 * s);
  ctx.fill();
  ctx.fillStyle = '#8a6137';
  ctx.beginPath();
  ctx.ellipse(0, -26 * s, 12 * s, 4.2 * s, 0, 0, TAU);
  ctx.fill();
  ctx.strokeStyle = '#5b3d20';
  ctx.lineWidth = 1.2;
  ctx.beginPath();
  ctx.ellipse(0, -26 * s, 12 * s, 4.2 * s, 0, 0, TAU);
  ctx.stroke();
  ctx.strokeStyle = '#5a4e3c';
  ctx.lineWidth = 2;
  for (const yy of [-20, -12, -4]) {
    ctx.beginPath();
    ctx.ellipse(0, yy * s, 12 * s, 3 * s, 0, 0, Math.PI);
    ctx.stroke();
  }
  ctx.restore();
}

export function drawStump(ctx, o) {
  const s = o.s || 1;
  ctx.save();
  ctx.translate(o.x, o.y);
  ctx.fillStyle = 'rgba(40, 32, 18, .2)';
  ctx.beginPath();
  ctx.ellipse(2, 2, 12 * s, 4 * s, 0, 0, TAU);
  ctx.fill();
  ctx.fillStyle = '#6f4c2a';
  rr(ctx, -9 * s, -13 * s, 18 * s, 14 * s, 3);
  ctx.fill();
  ctx.fillStyle = '#c59a61';
  ctx.beginPath();
  ctx.ellipse(0, -13 * s, 9 * s, 4 * s, 0, 0, TAU);
  ctx.fill();
  ctx.strokeStyle = '#8b6438';
  ctx.lineWidth = 1;
  ctx.beginPath();
  ctx.ellipse(0, -13 * s, 4.5 * s, 2 * s, 0, 0, TAU);
  ctx.stroke();
  ctx.restore();
}

export function drawBoulder(ctx, o) {
  const s = o.s || 1;
  ctx.save();
  ctx.translate(o.x, o.y);
  ctx.fillStyle = 'rgba(35, 40, 30, .22)';
  ctx.beginPath();
  ctx.ellipse(2, 2, 20 * s, 6 * s, 0, 0, TAU);
  ctx.fill();
  ctx.beginPath();
  ctx.moveTo(-18 * s, 0);
  ctx.lineTo(-14 * s, -14 * s);
  ctx.lineTo(-3 * s, -22 * s);
  ctx.lineTo(12 * s, -18 * s);
  ctx.lineTo(18 * s, -6 * s);
  ctx.lineTo(13 * s, 0);
  ctx.closePath();
  const g = ctx.createLinearGradient(-15 * s, -20 * s, 14 * s, 0);
  g.addColorStop(0, '#aab0a6');
  g.addColorStop(1, '#71786f');
  ctx.fillStyle = g;
  ctx.fill();
  ctx.strokeStyle = '#626960';
  ctx.lineWidth = 1;
  ctx.stroke();
  ctx.strokeStyle = 'rgba(70, 78, 68, .35)';
  ctx.beginPath();
  ctx.moveTo(-4 * s, -21 * s);
  ctx.lineTo(-1 * s, -8 * s);
  ctx.lineTo(8 * s, 0);
  ctx.stroke();
  ctx.restore();
}

export function drawMushrooms(ctx, o) {
  const s = o.s || 1;
  ctx.save();
  ctx.translate(o.x, o.y);
  for (const [mx, my, ms, col] of [[-7, 0, 1, '#b85c4d'], [4, -2, .8, '#c47a58'], [11, 1, .7, '#a94f45']]) {
    ctx.strokeStyle = '#e3d6b6';
    ctx.lineWidth = 1.4;
    ctx.beginPath();
    ctx.moveTo(mx * s, my * s);
    ctx.lineTo(mx * s, (my - 6 * ms) * s);
    ctx.stroke();
    ctx.fillStyle = col;
    ctx.beginPath();
    ctx.ellipse(mx * s, (my - 6 * ms) * s, 4.6 * ms * s, 2.6 * ms * s, 0, Math.PI, TAU);
    ctx.fill();
    ctx.fillStyle = 'rgba(255, 234, 214, .6)';
    ctx.beginPath();
    ctx.arc((mx - 1) * s, (my - 7 * ms) * s, .8 * s, 0, TAU);
    ctx.fill();
  }
  ctx.restore();
}

export function drawReeds(ctx, o) {
  const s = o.s || 1;
  ctx.save();
  ctx.translate(o.x, o.y);
  for (let i = 0; i < 9; i++) {
    const x = (hash(i, o.x) - .5) * 22 * s;
    const h = (10 + hash(i, o.y) * 18) * s;
    ctx.strokeStyle = i % 3 ? '#5e7c44' : '#78904f';
    ctx.lineWidth = 1.2;
    ctx.beginPath();
    ctx.moveTo(x, 2);
    ctx.quadraticCurveTo(x + 3, -h * .6, x + (hash(i + 2, o.x) - .5) * 8, -h);
    ctx.stroke();
    if (i % 4 === 0) {
      ctx.fillStyle = '#8a6337';
      ctx.beginPath();
      ctx.ellipse(x + 1, -h, 1.5, 3.4, .15, 0, TAU);
      ctx.fill();
    }
  }
  ctx.restore();
}

export function drawLily(ctx, o) {
  const s = o.s || 1;
  ctx.save();
  ctx.translate(o.x, o.y);
  ctx.fillStyle = 'rgba(54, 92, 57, .8)';
  ctx.beginPath();
  ctx.ellipse(0, 0, 10 * s, 5.5 * s, .2, .4, TAU);
  ctx.closePath();
  ctx.fill();
  ctx.strokeStyle = 'rgba(35, 70, 40, .5)';
  ctx.lineWidth = .8;
  ctx.stroke();
  ctx.restore();
}

export function drawDecor(ctx, d, t) {
  switch (d.type) {
    case 'hay': drawHay(ctx, d); break;
    case 'crate': drawCrate(ctx, d); break;
    case 'barrel': drawBarrel(ctx, d); break;
    case 'stump': drawStump(ctx, d); break;
    case 'boulder': drawBoulder(ctx, d); break;
    case 'mushrooms': drawMushrooms(ctx, d); break;
    case 'reeds': drawReeds(ctx, d); break;
    case 'lily': drawLily(ctx, d); break;
  }
}

/* ---------------- interaction ring ---------------- */
export function drawTargetRing(ctx, x, y, r, t, color = 'rgba(240, 205, 122,') {
  const pulse = .5 + Math.sin(t * 3.2) * .5;
  ctx.save();
  ctx.strokeStyle = `${color} ${.45 + pulse * .35})`;
  ctx.lineWidth = 2;
  ctx.beginPath();
  ctx.ellipse(x, y, r, r * .4, 0, 0, TAU);
  ctx.stroke();
  ctx.strokeStyle = `${color} ${.15 + pulse * .15})`;
  ctx.lineWidth = 1;
  ctx.beginPath();
  ctx.ellipse(x, y, r + 4, (r + 4) * .4, 0, 0, TAU);
  ctx.stroke();
  ctx.restore();
}

/* ============================================================
   IRONROOT & IVY — buildings, shop & landmarks
   ============================================================ */
import { TAU, rr, hash, SHOP } from './data.js';
import { drawWeapon } from './art.js';

function shadow(ctx, x, y, rx, ry, a = .25) {
  ctx.fillStyle = `rgba(32, 40, 26, ${a})`;
  ctx.beginPath();
  ctx.ellipse(x + 4, y + 3, rx, ry, 0, 0, TAU);
  ctx.fill();
}

/* ---------------- barn ---------------- */
export function drawBarn(ctx, b) {
  const { x, y, w, h } = b;
  const base = y + h;
  ctx.save();
  shadow(ctx, x + w / 2, base, w * .55, 15, .22);

  // body
  const body = ctx.createLinearGradient(x, y, x + w, y + h);
  body.addColorStop(0, '#b34e38');
  body.addColorStop(.55, '#9a3f2e');
  body.addColorStop(1, '#7c3327');
  ctx.fillStyle = body;
  rr(ctx, x, y + 56, w, h - 56, 3);
  ctx.fill();
  // plank lines
  ctx.strokeStyle = 'rgba(91, 35, 25, .3)';
  ctx.lineWidth = 1;
  for (let px = x + 10; px < x + w; px += 14) {
    ctx.beginPath();
    ctx.moveTo(px, y + 58);
    ctx.lineTo(px, base - 2);
    ctx.stroke();
  }
  // roof
  ctx.beginPath();
  ctx.moveTo(x - 12, y + 62);
  ctx.lineTo(x + w * .17, y + 10);
  ctx.lineTo(x + w * .5, y + 34);
  ctx.lineTo(x + w * .83, y + 10);
  ctx.lineTo(x + w + 12, y + 62);
  ctx.closePath();
  const roof = ctx.createLinearGradient(0, y + 8, 0, y + 64);
  roof.addColorStop(0, '#5b3c30');
  roof.addColorStop(1, '#3e2a22');
  ctx.fillStyle = roof;
  ctx.fill();
  ctx.strokeStyle = 'rgba(35, 23, 18, .5)';
  ctx.lineWidth = 1.2;
  ctx.stroke();
  // roof shingles
  ctx.strokeStyle = 'rgba(142, 103, 78, .22)';
  ctx.lineWidth = 1;
  for (let ry = y + 20; ry < y + 60; ry += 7) {
    ctx.beginPath();
    ctx.moveTo(x - 4 + (ry - y) * .3, ry);
    ctx.lineTo(x + w + 4 - (ry - y) * .3, ry);
    ctx.stroke();
  }
  // white trim
  ctx.strokeStyle = '#e9dcc0';
  ctx.lineWidth = 3;
  ctx.beginPath();
  ctx.moveTo(x, y + 57);
  ctx.lineTo(x + w, y + 57);
  ctx.stroke();
  ctx.lineWidth = 2;
  ctx.strokeRect(x + 3, y + 60, w - 6, h - 62);

  // big doors
  const dx = x + w * .31, dw = w * .38, dy = y + 92, dh = h - 94;
  ctx.fillStyle = '#6e2f24';
  rr(ctx, dx, dy, dw, dh, 2);
  ctx.fill();
  ctx.strokeStyle = '#e4d5b5';
  ctx.lineWidth = 2;
  ctx.strokeRect(dx + 2, dy + 2, dw - 4, dh - 4);
  ctx.beginPath();
  ctx.moveTo(dx + dw / 2, dy + 2);
  ctx.lineTo(dx + dw / 2, dy + dh - 2);
  ctx.stroke();
  // door cross braces
  ctx.lineWidth = 2.4;
  ctx.beginPath();
  ctx.moveTo(dx + 4, dy + 6);
  ctx.lineTo(dx + dw / 2 - 4, dy + dh - 8);
  ctx.moveTo(dx + dw - 4, dy + 6);
  ctx.lineTo(dx + dw / 2 + 4, dy + dh - 8);
  ctx.stroke();
  // handles
  ctx.fillStyle = '#d9b45e';
  ctx.beginPath();
  ctx.arc(dx + dw / 2 - 8, dy + dh * .58, 2.4, 0, TAU);
  ctx.arc(dx + dw / 2 + 8, dy + dh * .58, 2.4, 0, TAU);
  ctx.fill();

  // hayloft window
  ctx.fillStyle = '#3d2a20';
  ctx.beginPath();
  ctx.moveTo(x + w / 2 - 16, y + 56);
  ctx.lineTo(x + w / 2 - 16, y + 82);
  ctx.lineTo(x + w / 2 + 16, y + 82);
  ctx.lineTo(x + w / 2 + 16, y + 56);
  ctx.closePath();
  ctx.fill();
  ctx.strokeStyle = '#e4d5b5';
  ctx.lineWidth = 2;
  ctx.stroke();
  ctx.strokeStyle = '#c9b48d';
  ctx.lineWidth = 1.4;
  ctx.beginPath();
  ctx.moveTo(x + w / 2, y + 58);
  ctx.lineTo(x + w / 2, y + 80);
  ctx.moveTo(x + w / 2 - 14, y + 69);
  ctx.lineTo(x + w / 2 + 14, y + 69);
  ctx.stroke();

  // side window
  ctx.fillStyle = '#f0d99e';
  rr(ctx, x + w - 40, y + 100, 22, 18, 2);
  ctx.fill();
  ctx.strokeStyle = '#5a3b2c';
  ctx.lineWidth = 1.6;
  ctx.strokeRect(x + w - 40, y + 100, 22, 18);
  ctx.beginPath();
  ctx.moveTo(x + w - 29, y + 100);
  ctx.lineTo(x + w - 29, y + 118);
  ctx.stroke();

  // weather vane
  ctx.strokeStyle = '#4a3a2c';
  ctx.lineWidth = 1.6;
  ctx.beginPath();
  ctx.moveTo(x + w * .5, y + 32);
  ctx.lineTo(x + w * .5, y - 8);
  ctx.stroke();
  ctx.fillStyle = '#c9a24a';
  ctx.beginPath();
  ctx.moveTo(x + w * .5, y - 12);
  ctx.lineTo(x + w * .5 + 14, y - 7);
  ctx.lineTo(x + w * .5, y - 2);
  ctx.closePath();
  ctx.fill();
  ctx.beginPath();
  ctx.arc(x + w * .5 - 5, y + 1, 2, 0, TAU);
  ctx.fill();

  // ivy on corner
  for (let i = 0; i < 7; i++) {
    ctx.fillStyle = i % 2 ? '#4f7f45' : '#629454';
    ctx.beginPath();
    ctx.ellipse(x + 8 + Math.sin(i) * 4, y + 150 - i * 12, 3.4, 2.2, i, 0, TAU);
    ctx.fill();
  }
  ctx.restore();
}

/* ---------------- shop ---------------- */
export function drawShopBack(ctx, t) {
  const { x, y, w, h } = SHOP.wall;
  const base = y + h;
  ctx.save();
  shadow(ctx, x + w / 2, base + 2, w * .52, 18, .24);

  // posts
  ctx.fillStyle = '#6f4c2c';
  rr(ctx, x + 2, y + 26, 12, h - 24, 2);
  ctx.fill();
  rr(ctx, x + w - 14, y + 26, 12, h - 24, 2);
  ctx.fill();
  ctx.fillStyle = 'rgba(217, 180, 118, .28)';
  ctx.fillRect(x + 3, y + 28, 3, h - 28);
  ctx.fillRect(x + w - 13, y + 28, 3, h - 28);

  // wall planks
  const wall = ctx.createLinearGradient(0, y + 28, 0, base);
  wall.addColorStop(0, '#a47a4b');
  wall.addColorStop(1, '#8b6238');
  ctx.fillStyle = wall;
  rr(ctx, x + 12, y + 28, w - 24, h - 28, 2);
  ctx.fill();
  ctx.strokeStyle = 'rgba(86, 56, 27, .28)';
  ctx.lineWidth = 1;
  for (let px = x + 26; px < x + w - 14; px += 17) {
    ctx.beginPath();
    ctx.moveTo(px, y + 30);
    ctx.lineTo(px, base);
    ctx.stroke();
  }

  // awning
  const ax = x - 22, aw = w + 44, ay = y - 42, ah = 48;
  ctx.save();
  ctx.beginPath();
  ctx.rect(ax, ay, aw, ah + 9);
  ctx.clip();
  for (let i = 0; i < 11; i++) {
    ctx.fillStyle = i % 2 ? '#f0dfba' : '#b65a3f';
    ctx.fillRect(ax + i * (aw / 11), ay, aw / 11 + 1, ah + 8);
  }
  ctx.restore();
  // scalloped hem
  for (let i = 0; i < 11; i++) {
    ctx.fillStyle = i % 2 ? '#f0dfba' : '#b65a3f';
    ctx.beginPath();
    ctx.arc(ax + (i + .5) * (aw / 11), ay + ah + 4, aw / 22, 0, Math.PI);
    ctx.fill();
  }
  ctx.strokeStyle = 'rgba(86, 56, 27, .35)';
  ctx.lineWidth = 2;
  ctx.beginPath();
  ctx.moveTo(ax, ay);
  ctx.lineTo(ax + aw, ay);
  ctx.stroke();
  // awning shadow
  const sh = ctx.createLinearGradient(0, ay + ah, 0, ay + ah + 18);
  sh.addColorStop(0, 'rgba(54, 34, 18, .28)');
  sh.addColorStop(1, 'rgba(54, 34, 18, 0)');
  ctx.fillStyle = sh;
  ctx.fillRect(ax, ay + ah + 4, aw, 18);

  // shelves left & right
  for (const sx of [x + 26, x + w - 100]) {
    ctx.fillStyle = '#6b4727';
    ctx.fillRect(sx, y + 92, 72, 5);
    ctx.fillStyle = 'rgba(219, 183, 123, .25)';
    ctx.fillRect(sx, y + 92, 72, 1.5);
    // jars
    for (let i = 0; i < 4; i++) {
      const jx = sx + 7 + i * 17;
      const col = ['#7ca06b', '#c98b56', '#8b79b5', '#d5b260'][i];
      ctx.fillStyle = col;
      rr(ctx, jx, y + 75, 10, 17, 3);
      ctx.fill();
      ctx.fillStyle = 'rgba(255, 255, 255, .3)';
      ctx.fillRect(jx + 2, y + 78, 2, 10);
      ctx.fillStyle = '#6a4a2a';
      ctx.fillRect(jx, y + 72, 10, 3);
    }
  }

  // hanging sign
  const sx = x + 111, sw = 228, sy = y + 54;
  ctx.strokeStyle = '#5c3d20';
  ctx.lineWidth = 1.4;
  ctx.beginPath();
  ctx.moveTo(sx + 34, y + 30);
  ctx.lineTo(sx + 34, sy);
  ctx.moveTo(sx + sw - 34, y + 30);
  ctx.lineTo(sx + sw - 34, sy);
  ctx.stroke();
  ctx.fillStyle = 'rgba(45, 30, 14, .25)';
  rr(ctx, sx + 4, sy + 5, sw, 58, 5);
  ctx.fill();
  const sg = ctx.createLinearGradient(sx, sy, sx, sy + 58);
  sg.addColorStop(0, '#3c5940');
  sg.addColorStop(1, '#2b4433');
  ctx.fillStyle = sg;
  rr(ctx, sx, sy, sw, 58, 5);
  ctx.fill();
  ctx.strokeStyle = '#c9a45a';
  ctx.lineWidth = 1.4;
  rr(ctx, sx + 3, sy + 3, sw - 6, 52, 3);
  ctx.stroke();
  ctx.textAlign = 'center';
  ctx.fillStyle = '#f0dcab';
  ctx.font = '700 17px "Iowan Old Style", Georgia, serif';
  ctx.fillText('IRONROOT', sx + sw / 2, sy + 26);
  ctx.fillStyle = '#d9b469';
  ctx.font = 'italic 11px "Iowan Old Style", Georgia, serif';
  ctx.fillText('& IVY', sx + sw / 2, sy + 42);
  ctx.strokeStyle = 'rgba(217, 180, 105, .6)';
  ctx.lineWidth = .8;
  ctx.beginPath();
  ctx.moveTo(sx + 72, sy + 48);
  ctx.lineTo(sx + sw - 72, sy + 48);
  ctx.stroke();
  // ivy on sign
  for (let i = 0; i < 5; i++) {
    ctx.fillStyle = i % 2 ? '#5d8a4d' : '#4c7742';
    ctx.beginPath();
    ctx.ellipse(sx + 10 + Math.sin(i * 1.7) * 3, sy + 8 + i * 10, 3.2, 2, .7, 0, TAU);
    ctx.fill();
  }

  // hanging lanterns
  for (const lx of [x + 52, x + w - 52]) {
    ctx.strokeStyle = '#4a3520';
    ctx.lineWidth = 1.2;
    ctx.beginPath();
    ctx.moveTo(lx, y + 18);
    ctx.lineTo(lx, y + 54);
    ctx.stroke();
    ctx.fillStyle = '#3d3126';
    rr(ctx, lx - 6, y + 54, 12, 15, 2);
    ctx.fill();
    ctx.fillStyle = `rgba(248, 201, 105, ${.65 + Math.sin(t * 2 + lx) * .12})`;
    rr(ctx, lx - 4, y + 57, 8, 9, 1.5);
    ctx.fill();
    ctx.strokeStyle = '#6c512c';
    ctx.lineWidth = 1;
    ctx.strokeRect(lx - 6, y + 54, 12, 15);
  }

  // ivy on posts
  for (let i = 0; i < 9; i++) {
    ctx.fillStyle = i % 2 ? '#5c8a4b' : '#48743e';
    const side = i < 5 ? x + 8 : x + w - 8;
    ctx.beginPath();
    ctx.ellipse(side + (i % 5) * 1.2, y + 40 + i * 10, 3.4, 2.1, i * .7, 0, TAU);
    ctx.fill();
  }
  ctx.restore();
}

export function drawCounter(ctx) {
  const { x, y, w, h } = SHOP.counter;
  const base = y + h;
  ctx.save();
  shadow(ctx, x + w / 2, base, w * .55, 9, .2);
  // front
  const g = ctx.createLinearGradient(0, y, 0, base);
  g.addColorStop(0, '#a87a46');
  g.addColorStop(1, '#7e562e');
  ctx.fillStyle = g;
  rr(ctx, x, y + 7, w, h - 7, 3);
  ctx.fill();
  // top
  ctx.fillStyle = '#c2965b';
  rr(ctx, x - 5, y, w + 10, 11, 3);
  ctx.fill();
  ctx.strokeStyle = 'rgba(86, 56, 27, .5)';
  ctx.lineWidth = 1;
  rr(ctx, x - 5, y, w + 10, 11, 3);
  ctx.stroke();
  // panels
  ctx.strokeStyle = 'rgba(84, 54, 26, .45)';
  for (let i = 0; i < 3; i++) {
    rr(ctx, x + 10 + i * 59, y + 24, 48, h - 31, 2);
    ctx.stroke();
  }
  // bell
  ctx.fillStyle = '#c8a14a';
  ctx.beginPath();
  ctx.moveTo(x + w * .28 - 5, y + 1);
  ctx.quadraticCurveTo(x + w * .28 - 5, y - 7, x + w * .28, y - 7);
  ctx.quadraticCurveTo(x + w * .28 + 5, y - 7, x + w * .28 + 5, y + 1);
  ctx.closePath();
  ctx.fill();
  ctx.fillStyle = '#8e6924';
  ctx.fillRect(x + w * .28 - 5, y + 1, 10, 1.5);
  // coins
  ctx.fillStyle = '#e2b34e';
  for (let i = 0; i < 3; i++) {
    ctx.beginPath();
    ctx.ellipse(x + w * .68 + i * 2, y - 1 - i * 2.5, 4, 1.8, 0, 0, TAU);
    ctx.fill();
    ctx.strokeStyle = '#a8781f';
    ctx.lineWidth = .6;
    ctx.stroke();
  }
  // mug
  ctx.fillStyle = '#8b6339';
  rr(ctx, x + w * .52, y - 7, 8, 8, 2);
  ctx.fill();
  ctx.strokeStyle = '#8b6339';
  ctx.lineWidth = 1.4;
  ctx.beginPath();
  ctx.arc(x + w * .52 + 9, y - 3, 3, -.9, .9);
  ctx.stroke();
  ctx.restore();
}

/* ---------------- forge ---------------- */
export function drawForge(ctx, t) {
  const { x, y, w, h } = SHOP.forge;
  const base = y + h;
  ctx.save();
  shadow(ctx, x + w / 2, base, 38, 10, .22);
  // chimney
  ctx.fillStyle = '#6a655c';
  rr(ctx, x + 12, y - 42, 20, 36, 2);
  ctx.fill();
  ctx.strokeStyle = '#4d4a43';
  ctx.lineWidth = 1;
  for (let i = 0; i < 5; i++) {
    ctx.beginPath();
    ctx.moveTo(x + 13, y - 38 + i * 7);
    ctx.lineTo(x + 31, y - 38 + i * 7);
    ctx.stroke();
  }
  // smoke
  for (let i = 0; i < 3; i++) {
    const sy = y - 46 - i * 11 + Math.sin(t * .8 + i) * 3;
    ctx.fillStyle = `rgba(214, 210, 195, ${.16 - i * .04})`;
    ctx.beginPath();
    ctx.arc(x + 22 + Math.sin(t + i) * 5, sy, 5 + i * 2, 0, TAU);
    ctx.fill();
  }
  // furnace body
  const body = ctx.createLinearGradient(x, y, x + w, y + h);
  body.addColorStop(0, '#8f897d');
  body.addColorStop(1, '#6b665d');
  ctx.fillStyle = body;
  rr(ctx, x + 4, y - 8, 48, h + 8, 5);
  ctx.fill();
  ctx.strokeStyle = '#514d46';
  ctx.lineWidth = 1.2;
  rr(ctx, x + 4, y - 8, 48, h + 8, 5);
  ctx.stroke();
  // stone lines
  ctx.strokeStyle = 'rgba(63, 60, 53, .35)';
  for (let i = 0; i < 4; i++) {
    ctx.beginPath();
    ctx.moveTo(x + 5, y + 3 + i * 12);
    ctx.lineTo(x + 51, y + 3 + i * 12);
    ctx.stroke();
  }
  // fire mouth
  const flick = .7 + Math.sin(t * 7) * .15 + Math.sin(t * 11) * .1;
  const fg = ctx.createRadialGradient(x + 28, y + 36, 1, x + 28, y + 36, 24);
  fg.addColorStop(0, `rgba(255, 236, 167, ${flick})`);
  fg.addColorStop(.45, `rgba(246, 158, 56, ${flick * .9})`);
  fg.addColorStop(1, 'rgba(163, 52, 21, 0)');
  ctx.fillStyle = fg;
  ctx.beginPath();
  ctx.arc(x + 28, y + 38, 26, 0, TAU);
  ctx.fill();
  ctx.fillStyle = '#2e2017';
  ctx.beginPath();
  ctx.moveTo(x + 16, y + 48);
  ctx.quadraticCurveTo(x + 17, y + 22, x + 28, y + 20);
  ctx.quadraticCurveTo(x + 39, y + 22, x + 40, y + 48);
  ctx.closePath();
  ctx.fill();
  ctx.fillStyle = `rgba(248, 169, 64, ${flick})`;
  ctx.beginPath();
  ctx.moveTo(x + 21, y + 48);
  ctx.quadraticCurveTo(x + 22, y + 32, x + 28, y + 29);
  ctx.quadraticCurveTo(x + 34, y + 33, x + 35, y + 48);
  ctx.closePath();
  ctx.fill();
  // anvil
  ctx.fillStyle = '#4e5257';
  rr(ctx, x + 55, y + 38, 26, 10, 2);
  ctx.fill();
  ctx.beginPath();
  ctx.moveTo(x + 55, y + 38);
  ctx.lineTo(x + 62, y + 30);
  ctx.lineTo(x + 80, y + 30);
  ctx.lineTo(x + 81, y + 38);
  ctx.closePath();
  ctx.fill();
  ctx.fillStyle = '#383b3e';
  ctx.fillRect(x + 62, y + 46, 8, 12);
  ctx.fillRect(x + 57, y + 55, 18, 5);
  // hammer leaning
  ctx.strokeStyle = '#7b5430';
  ctx.lineWidth = 2.2;
  ctx.beginPath();
  ctx.moveTo(x + 72, y + 60);
  ctx.lineTo(x + 84, y + 36);
  ctx.stroke();
  ctx.fillStyle = '#7d868c';
  rr(ctx, x + 79, y + 30, 10, 7, 1.5);
  ctx.fill();
  // bucket
  ctx.fillStyle = '#7a5a36';
  rr(ctx, x + 4, y + 50, 13, 12, 2);
  ctx.fill();
  ctx.fillStyle = '#5b8b95';
  ctx.beginPath();
  ctx.ellipse(x + 10.5, y + 50, 6, 2, 0, 0, TAU);
  ctx.fill();
  // sparks
  for (let i = 0; i < 4; i++) {
    const a = t * 3 + i * 1.7;
    ctx.fillStyle = `rgba(255, 196, 92, ${.3 + Math.sin(a * 2) * .2})`;
    ctx.beginPath();
    ctx.arc(x + 28 + Math.cos(a) * (12 + i * 2), y + 34 + Math.sin(a * 1.3) * 14, 1.2, 0, TAU);
    ctx.fill();
  }
  ctx.restore();
}

/* ---------------- ledger desk ---------------- */
export function drawLedger(ctx, t) {
  const { x, y, w, h } = SHOP.ledger;
  const base = y + h;
  ctx.save();
  shadow(ctx, x + w / 2, base, 30, 8, .2);
  // desk
  ctx.fillStyle = '#8a6038';
  rr(ctx, x, y + 12, w, h - 12, 3);
  ctx.fill();
  ctx.fillStyle = '#b0834d';
  rr(ctx, x - 3, y + 8, w + 6, 9, 2);
  ctx.fill();
  ctx.strokeStyle = '#6a4624';
  ctx.lineWidth = 1.2;
  ctx.strokeRect(x + 5, y + 24, w - 10, h - 27);
  // book
  ctx.fillStyle = '#e8dcc0';
  ctx.beginPath();
  ctx.moveTo(x + 12, y + 7);
  ctx.lineTo(x + 30, y + 3);
  ctx.lineTo(x + 48, y + 7);
  ctx.lineTo(x + 48, y + 14);
  ctx.lineTo(x + 30, y + 11);
  ctx.lineTo(x + 12, y + 14);
  ctx.closePath();
  ctx.fill();
  ctx.strokeStyle = '#b7a480';
  ctx.lineWidth = .8;
  ctx.beginPath();
  ctx.moveTo(x + 30, y + 4);
  ctx.lineTo(x + 30, y + 11);
  ctx.stroke();
  ctx.strokeStyle = 'rgba(90, 70, 40, .45)';
  for (let i = 0; i < 3; i++) {
    ctx.beginPath();
    ctx.moveTo(x + 15, y + 7 + i * 2);
    ctx.lineTo(x + 27, y + 6 + i * 2);
    ctx.moveTo(x + 33, y + 6 + i * 2);
    ctx.lineTo(x + 45, y + 7 + i * 2);
    ctx.stroke();
  }
  // candle
  ctx.fillStyle = '#f0e3c2';
  rr(ctx, x + 50, y - 8, 6, 15, 2);
  ctx.fill();
  ctx.fillStyle = `rgba(255, 205, 105, ${.8 + Math.sin(t * 6) * .1})`;
  ctx.beginPath();
  ctx.ellipse(x + 53, y - 12, 2.4, 4, 0, 0, TAU);
  ctx.fill();
  const glow = ctx.createRadialGradient(x + 53, y - 12, 0, x + 53, y - 12, 30);
  glow.addColorStop(0, 'rgba(255, 205, 105, .28)');
  glow.addColorStop(1, 'rgba(255, 205, 105, 0)');
  ctx.fillStyle = glow;
  ctx.beginPath();
  ctx.arc(x + 53, y - 12, 30, 0, TAU);
  ctx.fill();
  // ink pot & quill
  ctx.fillStyle = '#3d4650';
  ctx.beginPath();
  ctx.ellipse(x + 40, y + 4, 4.4, 2.2, 0, 0, TAU);
  ctx.fill();
  ctx.strokeStyle = '#e5dbc2';
  ctx.lineWidth = 1.2;
  ctx.beginPath();
  ctx.moveTo(x + 40, y + 3);
  ctx.quadraticCurveTo(x + 44, y - 10, x + 51, y - 18);
  ctx.stroke();
  ctx.fillStyle = '#e5dbc2';
  ctx.beginPath();
  ctx.ellipse(x + 51, y - 18, 2.4, 4.5, -.5, 0, TAU);
  ctx.fill();
  ctx.restore();
}

/* ---------------- display pedestals ---------------- */
export function drawPedestal(ctx, ped, index, t) {
  const x = ped.x, y = ped.y;
  ctx.save();
  shadow(ctx, x, y + 10, 24, 8, .2);

  // base
  const g = ctx.createLinearGradient(x - 20, y, x + 20, y + 12);
  g.addColorStop(0, '#9a9588');
  g.addColorStop(1, '#6d6a61');
  ctx.fillStyle = g;
  rr(ctx, x - 21, y - 2, 42, 16, 4);
  ctx.fill();
  ctx.strokeStyle = 'rgba(70, 68, 60, .5)';
  ctx.lineWidth = 1;
  rr(ctx, x - 21, y - 2, 42, 16, 4);
  ctx.stroke();
  // wood top
  ctx.fillStyle = '#a87a46';
  rr(ctx, x - 24, y - 10, 48, 10, 3);
  ctx.fill();
  ctx.fillStyle = '#c49a62';
  rr(ctx, x - 24, y - 10, 48, 3, 2);
  ctx.fill();
  // cushion
  ctx.fillStyle = ped.weapon ? '#a34b3e' : '#5d6f54';
  rr(ctx, x - 18, y - 15, 36, 7, 3);
  ctx.fill();
  ctx.fillStyle = 'rgba(255, 255, 255, .16)';
  rr(ctx, x - 16, y - 14, 32, 2, 1);
  ctx.fill();

  if (!ped.unlocked) {
    // dust cloth
    ctx.fillStyle = '#d8c9a8';
    ctx.beginPath();
    ctx.moveTo(x - 22, y - 12);
    ctx.quadraticCurveTo(x - 8, y - 34, x + 4, y - 30);
    ctx.quadraticCurveTo(x + 17, y - 26, x + 22, y - 10);
    ctx.lineTo(x + 16, y + 1);
    ctx.lineTo(x - 16, y + 1);
    ctx.closePath();
    ctx.fill();
    ctx.strokeStyle = 'rgba(150, 130, 96, .5)';
    ctx.lineWidth = 1;
    ctx.stroke();
    // rope
    ctx.strokeStyle = '#8a6538';
    ctx.lineWidth = 2.4;
    ctx.beginPath();
    ctx.moveTo(x - 19, y - 8);
    ctx.quadraticCurveTo(x, y - 2, x + 19, y - 8);
    ctx.stroke();
    // lock
    ctx.fillStyle = '#b08b3f';
    rr(ctx, x - 5, y - 7, 10, 8, 1.5);
    ctx.fill();
    ctx.strokeStyle = '#7d5e22';
    ctx.lineWidth = 1.2;
    ctx.beginPath();
    ctx.arc(x, y - 8, 3, Math.PI, 0);
    ctx.stroke();
    // sign
    ctx.fillStyle = '#4f4130';
    ctx.font = '700 6px "Avenir Next", sans-serif';
    ctx.textAlign = 'center';
    ctx.fillText('LEDGER', x, y + 24);
  } else if (ped.weapon) {
    const float = Math.sin(t * 2 + index) * 2.5;
    // glow
    const glow = ctx.createRadialGradient(x, y - 38, 2, x, y - 38, 32);
    glow.addColorStop(0, 'rgba(238, 198, 104, .2)');
    glow.addColorStop(1, 'rgba(238, 198, 104, 0)');
    ctx.fillStyle = glow;
    ctx.beginPath();
    ctx.arc(x, y - 38, 32, 0, TAU);
    ctx.fill();
    drawWeapon(ctx, ped.weapon, x, y - 37 + float, 1.06, Math.sin(t * .7 + index) * .05, { glow: true });
    // sparkles
    for (let i = 0; i < 2; i++) {
      const a = t * 1.4 + i * 2.4 + index;
      ctx.fillStyle = `rgba(255, 231, 158, ${.35 + Math.sin(a * 2) * .25})`;
      ctx.beginPath();
      ctx.arc(x + Math.cos(a) * 19, y - 38 + Math.sin(a * 1.3) * 17, 1.4, 0, TAU);
      ctx.fill();
    }
  } else {
    // empty marker
    ctx.strokeStyle = 'rgba(240, 205, 122, .55)';
    ctx.lineWidth = 1.3;
    ctx.setLineDash([4, 4]);
    ctx.beginPath();
    ctx.arc(x, y - 36, 14, 0, TAU);
    ctx.stroke();
    ctx.setLineDash([]);
    ctx.strokeStyle = 'rgba(240, 205, 122, .75)';
    ctx.lineWidth = 1.6;
    ctx.beginPath();
    ctx.moveTo(x - 6, y - 36);
    ctx.lineTo(x + 6, y - 36);
    ctx.moveTo(x, y - 42);
    ctx.lineTo(x, y - 30);
    ctx.stroke();
  }

  // price tag
  if (ped.unlocked && ped.weapon) {
    const tx = x + 24, ty = y - 22;
    ctx.strokeStyle = '#6c4b28';
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(x + 15, y - 12);
    ctx.lineTo(tx, ty);
    ctx.stroke();
    ctx.fillStyle = 'rgba(45, 32, 16, .2)';
    rr(ctx, tx + 1, ty - 2, 30, 15, 2);
    ctx.fill();
    ctx.fillStyle = '#efe0bd';
    rr(ctx, tx, ty - 3, 30, 15, 2);
    ctx.fill();
    ctx.strokeStyle = '#b49a68';
    ctx.lineWidth = .8;
    rr(ctx, tx, ty - 3, 30, 15, 2);
    ctx.stroke();
    ctx.fillStyle = '#7a5a22';
    ctx.font = '700 8px "Avenir Next", sans-serif';
    ctx.textAlign = 'center';
    ctx.fillText(`${Math.round(ped.price)}g`, tx + 15, ty + 7);
  }
  // stock pips
  if (ped.unlocked && ped.weapon && ped.qty > 0) {
    for (let i = 0; i < 3; i++) {
      ctx.fillStyle = i < ped.qty ? 'rgba(240, 205, 122, .9)' : 'rgba(240, 205, 122, .2)';
      ctx.beginPath();
      ctx.arc(x - 8 + i * 8, y + 17, 1.6, 0, TAU);
      ctx.fill();
    }
  }
  ctx.restore();
}

/* ---------------- well ---------------- */
export function drawWell(ctx, w, t) {
  const { x, y } = w;
  ctx.save();
  shadow(ctx, x, y + 34, 44, 12, .22);
  // stone ring
  ctx.fillStyle = '#8d8a7c';
  ctx.beginPath();
  ctx.ellipse(x, y + 26, 36, 16, 0, 0, TAU);
  ctx.fill();
  ctx.fillStyle = '#a5a190';
  ctx.beginPath();
  ctx.ellipse(x, y + 22, 36, 16, 0, 0, TAU);
  ctx.fill();
  ctx.strokeStyle = '#6f6d61';
  ctx.lineWidth = 1.2;
  for (let i = 0; i < 10; i++) {
    const a = (i / 10) * TAU;
    ctx.beginPath();
    ctx.moveTo(x + Math.cos(a) * 32, y + 22 + Math.sin(a) * 13);
    ctx.lineTo(x + Math.cos(a) * 36, y + 26 + Math.sin(a) * 16);
    ctx.stroke();
  }
  // water
  ctx.fillStyle = '#3c6875';
  ctx.beginPath();
  ctx.ellipse(x, y + 21, 27, 11, 0, 0, TAU);
  ctx.fill();
  ctx.fillStyle = 'rgba(148, 205, 211, .3)';
  ctx.beginPath();
  ctx.ellipse(x - 8, y + 19, 9, 3, -.2, 0, TAU);
  ctx.fill();
  // posts
  ctx.fillStyle = '#7a5430';
  ctx.fillRect(x - 27, y - 42, 6, 60);
  ctx.fillRect(x + 21, y - 42, 6, 60);
  // roof
  ctx.beginPath();
  ctx.moveTo(x - 38, y - 42);
  ctx.lineTo(x, y - 64);
  ctx.lineTo(x + 38, y - 42);
  ctx.closePath();
  ctx.fillStyle = '#6b4530';
  ctx.fill();
  ctx.strokeStyle = '#4f3324';
  ctx.lineWidth = 1.2;
  ctx.stroke();
  // crossbar & rope
  ctx.strokeStyle = '#5d4024';
  ctx.lineWidth = 2.4;
  ctx.beginPath();
  ctx.moveTo(x - 24, y - 36);
  ctx.lineTo(x + 24, y - 36);
  ctx.stroke();
  ctx.strokeStyle = '#c8b48b';
  ctx.lineWidth = 1;
  const swing = Math.sin(t * .7) * 3;
  ctx.beginPath();
  ctx.moveTo(x, y - 36);
  ctx.lineTo(x + swing, y + 2);
  ctx.stroke();
  // bucket
  ctx.fillStyle = '#8d6738';
  rr(ctx, x + swing - 5, y - 2, 10, 9, 2);
  ctx.fill();
  ctx.strokeStyle = '#5f4323';
  ctx.lineWidth = 1;
  ctx.strokeRect(x + swing - 5, y - 2, 10, 9);
  ctx.restore();
}

/* ---------------- windmill ---------------- */
export function drawWindmill(ctx, w, t) {
  const { x, y } = w;
  ctx.save();
  shadow(ctx, x, y + 40, 38, 12, .22);
  // tower
  const g = ctx.createLinearGradient(x - 30, 0, x + 30, 0);
  g.addColorStop(0, '#8f846d');
  g.addColorStop(.5, '#b1a58a');
  g.addColorStop(1, '#7d735f');
  ctx.fillStyle = g;
  ctx.beginPath();
  ctx.moveTo(x - 26, y + 36);
  ctx.lineTo(x - 18, y - 52);
  ctx.lineTo(x + 18, y - 52);
  ctx.lineTo(x + 26, y + 36);
  ctx.closePath();
  ctx.fill();
  ctx.strokeStyle = '#6a6252';
  ctx.lineWidth = 1.2;
  ctx.stroke();
  // stone lines
  ctx.strokeStyle = 'rgba(90, 84, 70, .3)';
  for (let i = 0; i < 6; i++) {
    ctx.beginPath();
    ctx.moveTo(x - 24 + i * .6, y + 26 - i * 13);
    ctx.lineTo(x + 24 - i * .6, y + 26 - i * 13);
    ctx.stroke();
  }
  // door
  ctx.fillStyle = '#5c4024';
  ctx.beginPath();
  ctx.moveTo(x - 8, y + 36);
  ctx.lineTo(x - 8, y + 18);
  ctx.quadraticCurveTo(x, y + 10, x + 8, y + 18);
  ctx.lineTo(x + 8, y + 36);
  ctx.closePath();
  ctx.fill();
  // window
  ctx.fillStyle = '#efd598';
  ctx.beginPath();
  ctx.arc(x, y - 22, 5.5, 0, TAU);
  ctx.fill();
  ctx.strokeStyle = '#5f4a2e';
  ctx.lineWidth = 1.4;
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(x - 5.5, y - 22);
  ctx.lineTo(x + 5.5, y - 22);
  ctx.moveTo(x, y - 27.5);
  ctx.lineTo(x, y - 16.5);
  ctx.stroke();
  // cap
  ctx.fillStyle = '#5e4430';
  ctx.beginPath();
  ctx.arc(x, y - 52, 20, Math.PI, 0);
  ctx.fill();
  ctx.fillStyle = '#7c5c3f';
  ctx.beginPath();
  ctx.arc(x, y - 52, 16, Math.PI, 0);
  ctx.fill();
  // blades
  const hub = { x, y: y - 56 };
  const a0 = t * .55;
  ctx.translate(hub.x, hub.y);
  ctx.rotate(a0);
  for (let i = 0; i < 4; i++) {
    ctx.rotate(Math.PI / 2);
    ctx.fillStyle = 'rgba(72, 55, 35, .3)';
    ctx.fillRect(2, -2.5, 44, 5);
    ctx.fillStyle = '#d9c9a6';
    ctx.beginPath();
    ctx.moveTo(5, -2);
    ctx.lineTo(44, -7);
    ctx.lineTo(48, 0);
    ctx.lineTo(44, 7);
    ctx.lineTo(5, 2);
    ctx.closePath();
    ctx.fill();
    ctx.strokeStyle = '#8e7a56';
    ctx.lineWidth = .9;
    ctx.stroke();
    ctx.strokeStyle = 'rgba(120, 100, 70, .55)';
    ctx.beginPath();
    ctx.moveTo(8, -1);
    ctx.lineTo(42, -4);
    ctx.moveTo(8, 1);
    ctx.lineTo(42, 4);
    ctx.stroke();
  }
  ctx.rotate(-a0);
  ctx.fillStyle = '#5b432b';
  ctx.beginPath();
  ctx.arc(0, 0, 5, 0, TAU);
  ctx.fill();
  ctx.restore();
}

/* ---------------- cave / quarry mouth ---------------- */
export function drawCave(ctx, c, t) {
  const { x, y } = c;
  ctx.save();
  shadow(ctx, x, y + 54, 82, 22, .28);
  // rocks
  const blobs = [
    [-72, 20, 34, 30], [-46, -8, 36, 40], [-8, -28, 44, 42], [38, -12, 34, 36],
    [70, 18, 32, 28], [18, 30, 40, 30], [-38, 34, 38, 26],
  ];
  for (const [bx, by, rx, ry] of blobs) {
    const g = ctx.createLinearGradient(x + bx - rx, y + by - ry, x + bx + rx, y + by + ry);
    g.addColorStop(0, '#9a978c');
    g.addColorStop(1, '#66645c');
    ctx.fillStyle = g;
    ctx.beginPath();
    ctx.ellipse(x + bx, y + by, rx, ry, 0, 0, TAU);
    ctx.fill();
    ctx.strokeStyle = 'rgba(74, 72, 65, .45)';
    ctx.lineWidth = 1;
    ctx.stroke();
  }
  // opening
  const hole = ctx.createRadialGradient(x, y + 6, 6, x, y + 16, 58);
  hole.addColorStop(0, '#181c1c');
  hole.addColorStop(.7, '#242a28');
  hole.addColorStop(1, '#3b3f38');
  ctx.fillStyle = hole;
  ctx.beginPath();
  ctx.ellipse(x, y + 12, 42, 34, 0, Math.PI, TAU);
  ctx.lineTo(x + 42, y + 46);
  ctx.lineTo(x - 42, y + 46);
  ctx.closePath();
  ctx.fill();
  // crystals in the dark
  for (const [cx, cy, s] of [[-16, 22, 1], [8, 28, .8], [24, 18, .7]]) {
    ctx.fillStyle = `rgba(152, 131, 219, ${.5 + Math.sin(t * 1.6 + cx) * .2})`;
    ctx.beginPath();
    ctx.moveTo(x + cx, y + cy - 12 * s);
    ctx.lineTo(x + cx + 4 * s, y + cy);
    ctx.lineTo(x + cx - 4 * s, y + cy);
    ctx.closePath();
    ctx.fill();
  }
  // wooden supports
  ctx.strokeStyle = '#6d4b2a';
  ctx.lineWidth = 5;
  ctx.beginPath();
  ctx.moveTo(x - 48, y + 46);
  ctx.lineTo(x - 48, y - 10);
  ctx.lineTo(x + 48, y - 10);
  ctx.lineTo(x + 48, y + 46);
  ctx.stroke();
  ctx.strokeStyle = 'rgba(213, 172, 109, .25)';
  ctx.lineWidth = 1.4;
  ctx.beginPath();
  ctx.moveTo(x - 46, y + 46);
  ctx.lineTo(x - 46, y - 8);
  ctx.lineTo(x + 46, y - 8);
  ctx.stroke();
  // warning sign
  ctx.fillStyle = '#8a6235';
  ctx.fillRect(x - 70, y + 26, 3, 22);
  ctx.fillStyle = '#d9c29a';
  rr(ctx, x - 86, y + 14, 34, 14, 2);
  ctx.fill();
  ctx.strokeStyle = '#9d8058';
  ctx.lineWidth = .8;
  rr(ctx, x - 86, y + 14, 34, 14, 2);
  ctx.stroke();
  ctx.fillStyle = '#6e4d2a';
  ctx.font = '700 6px "Avenir Next", sans-serif';
  ctx.textAlign = 'center';
  ctx.fillText('OLD QUARRY', x - 69, y + 23);
  // vines
  for (let i = 0; i < 6; i++) {
    ctx.fillStyle = i % 2 ? '#527c45' : '#426b3a';
    ctx.beginPath();
    ctx.ellipse(x - 58 + i * 2, y + 38 - i * 11, 3.4, 2, i, 0, TAU);
    ctx.fill();
  }
  ctx.restore();
}

/* ---------------- lantern posts ---------------- */
export function drawLantern(ctx, l, t) {
  const { x, y, h } = l;
  const glow = .55 + Math.sin(t * 2.2 + x) * .12;
  ctx.save();
  shadow(ctx, x, y, 9, 3.5, .2);
  ctx.fillStyle = '#5e4327';
  ctx.fillRect(x - 2.2, y - h, 4.4, h);
  ctx.fillStyle = 'rgba(219, 180, 113, .3)';
  ctx.fillRect(x - 2.2, y - h, 1.4, h);
  // arm
  ctx.strokeStyle = '#5e4327';
  ctx.lineWidth = 2.6;
  ctx.beginPath();
  ctx.moveTo(x, y - h + 4);
  ctx.lineTo(x + 10, y - h + 4);
  ctx.stroke();
  // lantern
  const lx = x + 10, ly = y - h + 14;
  ctx.fillStyle = '#3c3125';
  rr(ctx, lx - 6, ly - 4, 12, 16, 2);
  ctx.fill();
  const g = ctx.createRadialGradient(lx, ly + 4, 1, lx, ly + 4, 15);
  g.addColorStop(0, `rgba(255, 226, 142, ${glow})`);
  g.addColorStop(1, 'rgba(255, 200, 90, 0)');
  ctx.fillStyle = g;
  ctx.beginPath();
  ctx.arc(lx, ly + 4, 15, 0, TAU);
  ctx.fill();
  ctx.fillStyle = `rgba(250, 207, 116, ${.7 + Math.sin(t * 3 + x) * .1})`;
  rr(ctx, lx - 4, ly - 1, 8, 10, 1.5);
  ctx.fill();
  ctx.strokeStyle = '#6c512c';
  ctx.lineWidth = 1;
  ctx.strokeRect(lx - 6, ly - 4, 12, 16);
  // cap
  ctx.fillStyle = '#4d3a24';
  ctx.beginPath();
  ctx.moveTo(lx - 8, ly - 4);
  ctx.lineTo(lx, ly - 10);
  ctx.lineTo(lx + 8, ly - 4);
  ctx.closePath();
  ctx.fill();
  ctx.restore();
}

/* ============================================================
   IRONROOT & IVY — people
   ============================================================ */
import { TAU, rr, clamp } from './data.js';

export function drawPlayer(ctx, p, t, tool) {
  const walk = p.moving ? Math.sin(p.walkTime * 11) : 0;
  const bob = p.moving ? Math.abs(Math.sin(p.walkTime * 11)) * 2.2 : Math.sin(t * 2) * .7;
  const face = Math.cos(p.facing) < 0 ? -1 : 1;
  const lean = clamp(Math.cos(p.facing), -1, 1) * 1.4;
  ctx.save();
  ctx.translate(p.x, p.y);

  // shadow
  ctx.fillStyle = 'rgba(28, 42, 25, .3)';
  ctx.beginPath();
  ctx.ellipse(1, 2, 15, 5.5, 0, 0, TAU);
  ctx.fill();

  // legs
  ctx.save();
  ctx.translate(0, -bob);
  for (const side of [-1, 1]) {
    const swing = walk * side * 3.4;
    ctx.strokeStyle = '#3f5b45';
    ctx.lineWidth = 5.4;
    ctx.lineCap = 'round';
    ctx.beginPath();
    ctx.moveTo(side * 4.4, -14);
    ctx.lineTo(side * 4.8 + swing, -2);
    ctx.stroke();
    ctx.fillStyle = '#5c3e27';
    ctx.beginPath();
    ctx.ellipse(side * 4.8 + swing, -1, 4.3, 2.3, 0, 0, TAU);
    ctx.fill();
  }
  // body / overalls
  ctx.fillStyle = '#4d7154';
  rr(ctx, -9 + lean * .3, -31, 18, 19, 7);
  ctx.fill();
  ctx.fillStyle = '#5f8762';
  rr(ctx, -8 + lean * .3, -31, 16, 5, 3);
  ctx.fill();
  // shirt
  ctx.fillStyle = '#e9d9b4';
  rr(ctx, -9.5, -34, 19, 8, 4);
  ctx.fill();
  // apron pocket
  ctx.fillStyle = '#426149';
  rr(ctx, -6, -24, 12, 8, 2);
  ctx.fill();
  ctx.strokeStyle = 'rgba(230, 212, 170, .4)';
  ctx.lineWidth = .8;
  rr(ctx, -6, -24, 12, 8, 2);
  ctx.stroke();
  // satchel strap
  ctx.strokeStyle = '#8a5f34';
  ctx.lineWidth = 3;
  ctx.beginPath();
  ctx.moveTo(-8, -33);
  ctx.lineTo(7, -17);
  ctx.stroke();
  ctx.fillStyle = '#a07444';
  rr(ctx, 5, -19, 8, 8, 2);
  ctx.fill();
  ctx.strokeStyle = '#6f4b28';
  ctx.lineWidth = .8;
  rr(ctx, 5, -19, 8, 8, 2);
  ctx.stroke();

  // arms
  for (const side of [-1, 1]) {
    const swing = walk * side * 2.6;
    ctx.strokeStyle = '#e6d4ad';
    ctx.lineWidth = 3.8;
    ctx.lineCap = 'round';
    ctx.beginPath();
    ctx.moveTo(side * 8.2, -31);
    ctx.lineTo(side * 10.5 + swing, -21);
    ctx.stroke();
    ctx.fillStyle = '#d9a67b';
    ctx.beginPath();
    ctx.arc(side * 10.5 + swing, -20, 2.3, 0, TAU);
    ctx.fill();
  }

  // head
  const hx = lean * .8;
  ctx.fillStyle = '#d9a67b';
  ctx.beginPath();
  ctx.arc(hx, -41, 7.4, 0, TAU);
  ctx.fill();
  // ear
  ctx.fillStyle = '#c98f66';
  ctx.beginPath();
  ctx.arc(hx - face * 6.6, -41, 2, 0, TAU);
  ctx.fill();
  // hair
  ctx.fillStyle = '#6b4328';
  ctx.beginPath();
  ctx.arc(hx, -43.5, 7.2, Math.PI * .92, Math.PI * 2.08);
  ctx.fill();
  // eyes
  ctx.fillStyle = '#3c2b1e';
  const eyeShift = clamp(Math.cos(p.facing), -.9, .9) * 1.7;
  ctx.beginPath();
  ctx.arc(hx - 2.5 + eyeShift, -40.5, 1.05, 0, TAU);
  ctx.arc(hx + 2.5 + eyeShift, -40.5, 1.05, 0, TAU);
  ctx.fill();
  // smile
  ctx.strokeStyle = 'rgba(110, 65, 40, .7)';
  ctx.lineWidth = .9;
  ctx.beginPath();
  ctx.arc(hx + eyeShift * .6, -37.4, 2.4, .15, Math.PI - .15);
  ctx.stroke();
  // cheeks
  ctx.fillStyle = 'rgba(214, 120, 96, .22)';
  ctx.beginPath();
  ctx.arc(hx - 5, -38.6, 1.8, 0, TAU);
  ctx.arc(hx + 5, -38.6, 1.8, 0, TAU);
  ctx.fill();

  // straw hat
  ctx.fillStyle = '#d6b26a';
  ctx.beginPath();
  ctx.ellipse(hx, -46, 14.5, 4.2, 0, 0, TAU);
  ctx.fill();
  ctx.fillStyle = '#c39c52';
  ctx.beginPath();
  ctx.ellipse(hx, -45.6, 14.2, 3.6, 0, 0, Math.PI);
  ctx.fill();
  ctx.fillStyle = '#dcba74';
  ctx.beginPath();
  ctx.ellipse(hx, -49.5, 7.4, 5, 0, 0, TAU);
  ctx.fill();
  ctx.fillStyle = '#8a5a32';
  rr(ctx, hx - 7.4, -47.8, 14.8, 2.6, 1);
  ctx.fill();
  ctx.fillStyle = 'rgba(255, 240, 201, .35)';
  ctx.beginPath();
  ctx.ellipse(hx - 2, -51, 3.4, 1.5, -.4, 0, TAU);
  ctx.fill();

  // held tool
  if (tool) {
    ctx.save();
    ctx.translate(10.5, -21);
    ctx.rotate(.18);
    drawTool(ctx, tool, face);
    ctx.restore();
  }
  ctx.restore();
  ctx.restore();
}

function drawTool(ctx, tool, face) {
  ctx.save();
  ctx.scale(face, 1);
  if (tool === 'axe' || tool === 'pick') {
    ctx.strokeStyle = '#8b5e33';
    ctx.lineWidth = 2.2;
    ctx.beginPath();
    ctx.moveTo(0, 4);
    ctx.lineTo(2, -17);
    ctx.stroke();
    ctx.fillStyle = '#aab7c0';
    if (tool === 'axe') {
      ctx.beginPath();
      ctx.moveTo(1, -19);
      ctx.quadraticCurveTo(10, -22, 12, -15);
      ctx.quadraticCurveTo(9, -11, 2, -12);
      ctx.closePath();
      ctx.fill();
      ctx.strokeStyle = '#5f6d78';
      ctx.lineWidth = .8;
      ctx.stroke();
    } else {
      ctx.beginPath();
      ctx.moveTo(-5, -15);
      ctx.quadraticCurveTo(1, -21, 10, -18);
      ctx.quadraticCurveTo(3, -13, -5, -15);
      ctx.closePath();
      ctx.fill();
      ctx.strokeStyle = '#5f6d78';
      ctx.lineWidth = .8;
      ctx.stroke();
    }
  } else if (tool === 'hoe') {
    ctx.strokeStyle = '#8b5e33';
    ctx.lineWidth = 2.2;
    ctx.beginPath();
    ctx.moveTo(0, 4);
    ctx.lineTo(2, -17);
    ctx.stroke();
    ctx.fillStyle = '#aab7c0';
    ctx.beginPath();
    ctx.moveTo(1, -17);
    ctx.lineTo(9, -20);
    ctx.lineTo(10, -16);
    ctx.lineTo(2, -14);
    ctx.closePath();
    ctx.fill();
  } else if (tool === 'hammer') {
    ctx.strokeStyle = '#8b5e33';
    ctx.lineWidth = 2.2;
    ctx.beginPath();
    ctx.moveTo(0, 4);
    ctx.lineTo(2, -14);
    ctx.stroke();
    ctx.fillStyle = '#8b99a5';
    rr(ctx, -2, -19, 10, 6, 1.5);
    ctx.fill();
  }
  ctx.restore();
}

export function drawCustomer(ctx, c, t) {
  const walk = c.moving ? Math.sin(c.walkTime * 9) : 0;
  const bob = c.moving ? Math.abs(Math.sin(c.walkTime * 9)) * 2 : Math.sin(t * 1.8 + c.seed) * .5;
  const face = c.dir < 0 ? -1 : 1;
  const type = c.type;
  ctx.save();
  ctx.translate(c.x, c.y);
  // shadow
  ctx.fillStyle = 'rgba(28, 40, 24, .28)';
  ctx.beginPath();
  ctx.ellipse(1, 2, 13, 4.8, 0, 0, TAU);
  ctx.fill();

  ctx.save();
  ctx.translate(0, -bob);
  // legs
  for (const side of [-1, 1]) {
    const swing = walk * side * 3;
    ctx.strokeStyle = '#4b4237';
    ctx.lineWidth = 4.6;
    ctx.lineCap = 'round';
    ctx.beginPath();
    ctx.moveTo(side * 4, -13);
    ctx.lineTo(side * 4.5 + swing, -1);
    ctx.stroke();
    ctx.fillStyle = '#3f3326';
    ctx.beginPath();
    ctx.ellipse(side * 4.5 + swing, 0, 3.6, 2, 0, 0, TAU);
    ctx.fill();
  }
  // cloak / body
  const g = ctx.createLinearGradient(-9, -34, 9, -12);
  g.addColorStop(0, type.cloak);
  g.addColorStop(1, shade(type.cloak, -.22));
  ctx.fillStyle = g;
  ctx.beginPath();
  ctx.moveTo(-8.5, -32);
  ctx.quadraticCurveTo(-11, -20, -10, -11);
  ctx.lineTo(10, -11);
  ctx.quadraticCurveTo(11, -20, 8.5, -32);
  ctx.closePath();
  ctx.fill();
  // trim
  ctx.strokeStyle = type.trim;
  ctx.lineWidth = 1.2;
  ctx.beginPath();
  ctx.moveTo(-9, -13);
  ctx.lineTo(9, -13);
  ctx.stroke();
  // belt
  ctx.fillStyle = '#6f5230';
  rr(ctx, -9, -22, 18, 3, 1);
  ctx.fill();
  ctx.fillStyle = '#d8b15c';
  rr(ctx, -1.5, -22.5, 3, 4, 1);
  ctx.fill();

  // arms
  for (const side of [-1, 1]) {
    const swing = walk * side * 2.2;
    ctx.strokeStyle = shade(type.cloak, .08);
    ctx.lineWidth = 3.4;
    ctx.lineCap = 'round';
    ctx.beginPath();
    ctx.moveTo(side * 7.5, -29);
    ctx.lineTo(side * 9.5 + swing, -19);
    ctx.stroke();
    ctx.fillStyle = type.skin;
    ctx.beginPath();
    ctx.arc(side * 9.5 + swing, -18.5, 2, 0, TAU);
    ctx.fill();
  }

  // head
  ctx.fillStyle = type.skin;
  ctx.beginPath();
  ctx.arc(0, -38, 6.6, 0, TAU);
  ctx.fill();
  // eyes
  ctx.fillStyle = '#3a2a1e';
  const es = face * 1.2;
  ctx.beginPath();
  ctx.arc(-2.2 + es, -38, .9, 0, TAU);
  ctx.arc(2.2 + es, -38, .9, 0, TAU);
  ctx.fill();
  // nose
  ctx.fillStyle = shade(type.skin, -.08);
  ctx.beginPath();
  ctx.arc(face * 1.2, -36.6, .9, 0, TAU);
  ctx.fill();

  // hats / hair
  if (type.hat === 'hood') {
    ctx.fillStyle = shade(type.cloak, -.12);
    ctx.beginPath();
    ctx.arc(0, -39, 7.7, Math.PI * .88, Math.PI * 2.12);
    ctx.lineTo(6.5, -32);
    ctx.lineTo(-6.5, -32);
    ctx.closePath();
    ctx.fill();
    ctx.strokeStyle = type.trim;
    ctx.lineWidth = .8;
    ctx.beginPath();
    ctx.arc(0, -39, 7.4, Math.PI * 1.02, Math.PI * 1.98);
    ctx.stroke();
  } else if (type.hat === 'helm') {
    ctx.fillStyle = '#9aa5b0';
    ctx.beginPath();
    ctx.arc(0, -39.5, 7.6, Math.PI, 0);
    ctx.lineTo(7.6, -36);
    ctx.lineTo(3, -36);
    ctx.lineTo(3, -33);
    ctx.lineTo(-3, -33);
    ctx.lineTo(-3, -36);
    ctx.lineTo(-7.6, -36);
    ctx.closePath();
    ctx.fill();
    ctx.strokeStyle = '#5d6872';
    ctx.lineWidth = .9;
    ctx.stroke();
    ctx.fillStyle = '#c9d2da';
    ctx.fillRect(-1, -44, 2, 9);
    ctx.fillStyle = '#b85c3e';
    ctx.beginPath();
    ctx.ellipse(0, -46, 2, 3.2, 0, 0, TAU);
    ctx.fill();
  } else if (type.hat === 'wizard') {
    ctx.fillStyle = shade(type.cloak, -.1);
    ctx.beginPath();
    ctx.moveTo(-8.5, -43);
    ctx.lineTo(0, -59);
    ctx.lineTo(8.5, -43);
    ctx.closePath();
    ctx.fill();
    ctx.fillStyle = type.trim;
    ctx.beginPath();
    ctx.ellipse(0, -43, 9, 2.4, 0, 0, TAU);
    ctx.fill();
    ctx.fillStyle = '#f2d67f';
    ctx.beginPath();
    ctx.arc(2.5, -51, 1.2, 0, TAU);
    ctx.fill();
  } else if (type.hat === 'straw') {
    ctx.fillStyle = '#d3ae68';
    ctx.beginPath();
    ctx.ellipse(0, -44, 12.5, 3.4, 0, 0, TAU);
    ctx.fill();
    ctx.fillStyle = '#c19a50';
    ctx.beginPath();
    ctx.ellipse(0, -46.5, 6, 4, 0, 0, TAU);
    ctx.fill();
    ctx.fillStyle = '#8b5f32';
    ctx.fillRect(-6, -45.5, 12, 1.6);
  } else {
    ctx.fillStyle = '#4f4132';
    ctx.beginPath();
    ctx.arc(0, -41, 6.9, Math.PI, TAU);
    ctx.fill();
    ctx.fillStyle = '#6a5842';
    ctx.beginPath();
    ctx.ellipse(0, -44, 8, 2.2, 0, 0, TAU);
    ctx.fill();
  }

  // accessories
  if (type.id === 'ranger') {
    ctx.strokeStyle = '#7a5430';
    ctx.lineWidth = 1.6;
    ctx.beginPath();
    ctx.moveTo(-6, -30);
    ctx.lineTo(-11, -21);
    ctx.stroke();
    ctx.strokeStyle = '#b9a26a';
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(-7, -29);
    ctx.lineTo(-12, -20);
    ctx.stroke();
  }
  if (type.id === 'knight') {
    ctx.fillStyle = '#d8b15c';
    ctx.beginPath();
    ctx.arc(6.5, -28, 2.2, 0, TAU);
    ctx.fill();
  }
  if (type.id === 'mage') {
    ctx.strokeStyle = '#8a6437';
    ctx.lineWidth = 1.6;
    ctx.beginPath();
    ctx.moveTo(-9, -4);
    ctx.lineTo(-11, -38);
    ctx.stroke();
    ctx.fillStyle = `rgba(179, 154, 235, ${.65 + Math.sin(t * 2 + c.seed) * .2})`;
    ctx.beginPath();
    ctx.arc(-11, -41, 3.4, 0, TAU);
    ctx.fill();
  }
  if (type.id === 'collector') {
    ctx.strokeStyle = '#c9a45a';
    ctx.lineWidth = .9;
    ctx.beginPath();
    ctx.arc(2.2, -38, 2.2, 0, TAU);
    ctx.stroke();
    ctx.beginPath();
    ctx.moveTo(3.4, -36.5);
    ctx.lineTo(6, -34.5);
    ctx.stroke();
  }
  ctx.restore();
  ctx.restore();
}

function shade(hex, amt) {
  const h = hex.replace('#', '');
  const n = parseInt(h, 16);
  let r = (n >> 16) & 255, g = (n >> 8) & 255, b = n & 255;
  r = clamp(Math.round(r + 255 * amt), 0, 255);
  g = clamp(Math.round(g + 255 * amt), 0, 255);
  b = clamp(Math.round(b + 255 * amt), 0, 255);
  return `rgb(${r},${g},${b})`;
}

export function drawBubble(ctx, c, text, t) {
  if (!text) return;
  const x = c.x;
  const y = c.y - 78;
  ctx.save();
  ctx.font = '600 10.5px "Avenir Next", "Segoe UI", sans-serif';
  const words = text.split(' ');
  const lines = [];
  let line = '';
  for (const word of words) {
    const test = line ? line + ' ' + word : word;
    if (ctx.measureText(test).width > 120 && line) {
      lines.push(line);
      line = word;
    } else line = test;
  }
  if (line) lines.push(line);
  const w = Math.max(...lines.map((l) => ctx.measureText(l).width)) + 18;
  const h = lines.length * 13 + 12;
  const bob = Math.sin(t * 2 + c.seed) * 1.2;
  ctx.translate(x, y + bob);
  ctx.fillStyle = 'rgba(30, 40, 28, .2)';
  rr(ctx, -w / 2 + 2, -h + 3, w, h, 8);
  ctx.fill();
  ctx.fillStyle = '#fbf3df';
  rr(ctx, -w / 2, -h, w, h, 8);
  ctx.fill();
  ctx.strokeStyle = '#c6b184';
  ctx.lineWidth = 1;
  rr(ctx, -w / 2, -h, w, h, 8);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(-5, 0);
  ctx.lineTo(0, 6);
  ctx.lineTo(5, 0);
  ctx.closePath();
  ctx.fillStyle = '#fbf3df';
  ctx.fill();
  ctx.strokeStyle = '#c6b184';
  ctx.beginPath();
  ctx.moveTo(-5, 0);
  ctx.lineTo(0, 6);
  ctx.lineTo(5, 0);
  ctx.stroke();
  ctx.fillStyle = '#3c3a2d';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  lines.forEach((l, i) => ctx.fillText(l, 0, -h + 13 + i * 13));
  ctx.restore();
}

/* ============================================================
   IRONROOT & IVY — procedural audio
   ============================================================ */
export function createAudio() {
  let ctx = null;
  let master = null;
  let musicGain = null;
  let enabled = true;
  let timer = null;
  let drone = null;

  function init() {
    if (ctx) {
      if (ctx.state === 'suspended') ctx.resume();
      return;
    }
    const AC = window.AudioContext || window.webkitAudioContext;
    if (!AC) return;
    ctx = new AC();
    master = ctx.createGain();
    master.gain.value = enabled ? .9 : 0;
    master.connect(ctx.destination);
    musicGain = ctx.createGain();
    musicGain.gain.value = .16;
    musicGain.connect(master);
    startMusic();
  }

  function tone(freq, dur, opts = {}) {
    if (!ctx) return;
    const {
      type = 'sine', vol = .08, attack = .008, release = dur,
      slide = 0, delay = 0, dest = master,
    } = opts;
    const t0 = ctx.currentTime + delay;
    const osc = ctx.createOscillator();
    const gain = ctx.createGain();
    osc.type = type;
    osc.frequency.setValueAtTime(freq, t0);
    if (slide) osc.frequency.exponentialRampToValueAtTime(Math.max(30, freq + slide), t0 + dur);
    gain.gain.setValueAtTime(0.0001, t0);
    gain.gain.exponentialRampToValueAtTime(vol, t0 + attack);
    gain.gain.exponentialRampToValueAtTime(0.0001, t0 + Math.max(attack + .01, release));
    osc.connect(gain);
    gain.connect(dest);
    osc.start(t0);
    osc.stop(t0 + dur + .05);
  }

  function noise(dur, opts = {}) {
    if (!ctx) return;
    const { vol = .06, freq = 900, q = 1, delay = 0 } = opts;
    const t0 = ctx.currentTime + delay;
    const len = Math.max(1, Math.floor(ctx.sampleRate * dur));
    const buf = ctx.createBuffer(1, len, ctx.sampleRate);
    const data = buf.getChannelData(0);
    for (let i = 0; i < len; i++) data[i] = Math.random() * 2 - 1;
    const src = ctx.createBufferSource();
    src.buffer = buf;
    const filter = ctx.createBiquadFilter();
    filter.type = 'bandpass';
    filter.frequency.value = freq;
    filter.Q.value = q;
    const gain = ctx.createGain();
    gain.gain.setValueAtTime(vol, t0);
    gain.gain.exponentialRampToValueAtTime(.0001, t0 + dur);
    src.connect(filter);
    filter.connect(gain);
    gain.connect(master);
    src.start(t0);
    src.stop(t0 + dur + .02);
  }

  function bell(freq, dur = 2.4, vol = .035, delay = 0) {
    if (!ctx) return;
    tone(freq, dur, { type: 'sine', vol, attack: .02, release: dur, delay, dest: musicGain });
    tone(freq * 2.01, dur * .7, { type: 'sine', vol: vol * .25, attack: .01, release: dur * .7, delay, dest: musicGain });
  }

  function startMusic() {
    if (!ctx || timer) return;
    const pad = ctx.createOscillator();
    const padGain = ctx.createGain();
    pad.type = 'triangle';
    pad.frequency.value = 146.83;
    padGain.gain.value = .018;
    pad.connect(padGain);
    padGain.connect(musicGain);
    pad.start();
    drone = { pad, padGain };
    const scale = [293.66, 329.63, 369.99, 440, 493.88, 587.33, 659.25];
    let step = 0;
    timer = setInterval(() => {
      if (!enabled || !ctx) return;
      if (document.hidden) return;
      step++;
      const n = scale[(step * 3 + (step % 2)) % scale.length];
      bell(n, 2.6, .032);
      if (step % 3 === 0) bell(n / 2, 3.4, .018);
      if (step % 5 === 0) bell(scale[(step + 4) % scale.length], 2.2, .02);
    }, 2600);
  }

  const sfx = {
    click() { tone(620, .05, { type: 'triangle', vol: .03, slide: 80 }); },
    plant() { tone(300, .13, { type: 'triangle', vol: .05, slide: 150 }); noise(.09, { vol: .02, freq: 700 }); },
    water() { noise(.28, { vol: .035, freq: 1100, q: .7 }); tone(700, .2, { type: 'sine', vol: .015, slide: 300 }); },
    harvest() { tone(520, .12, { type: 'triangle', vol: .05 }); tone(780, .16, { type: 'triangle', vol: .04, delay: .06 }); },
    chop() { noise(.1, { vol: .07, freq: 320, q: 1.4 }); tone(150, .1, { type: 'square', vol: .03, slide: -50 }); },
    mine() { tone(1050, .07, { type: 'triangle', vol: .035, slide: -350 }); noise(.09, { vol: .04, freq: 1800, q: 1.2 }); },
    rockBreak() { noise(.26, { vol: .075, freq: 500, q: .8 }); tone(120, .22, { type: 'square', vol: .035, slide: -60 }); },
    craft() { [440, 554.37, 659.25, 880].forEach((f, i) => tone(f, .22, { type: 'triangle', vol: .045, delay: i * .07 })); },
    coin() { tone(880, .09, { type: 'sine', vol: .04 }); tone(1318.5, .16, { type: 'sine', vol: .03, delay: .06 }); },
    sale() { [659.25, 880, 1108.7].forEach((f, i) => tone(f, .18, { type: 'sine', vol: .04, delay: i * .06 })); },
    error() { tone(180, .14, { type: 'sawtooth', vol: .025, slide: -40 }); },
    quest() { [659.25, 880, 987.77].forEach((f, i) => tone(f, .2, { type: 'triangle', vol: .045, delay: i * .08 })); },
    upgrade() { [523.25, 659.25, 783.99, 1046.5].forEach((f, i) => tone(f, .28, { type: 'triangle', vol: .04, delay: i * .09 })); },
    day() { [392, 523.25, 659.25, 783.99].forEach((f, i) => tone(f, 1.4, { type: 'sine', vol: .035, delay: i * .11 })); },
    start() { [392, 523.25, 659.25, 880].forEach((f, i) => tone(f, .8, { type: 'triangle', vol: .04, delay: i * .12 })); },
    page() { noise(.1, { vol: .02, freq: 2200, q: .8 }); },
    ui() { tone(440, .06, { type: 'sine', vol: .018 }); },
  };

  return {
    init,
    get enabled() { return enabled; },
    play(name) {
      if (!enabled || !ctx) return;
      try { sfx[name]?.(); } catch {}
    },
    toggle() {
      enabled = !enabled;
      if (master) master.gain.setTargetAtTime(enabled ? .9 : 0, ctx.currentTime, .05);
      if (enabled) init();
      return enabled;
    },
    setEnabled(v) {
      enabled = v;
      if (master && ctx) master.gain.setTargetAtTime(v ? .9 : 0, ctx.currentTime, .05);
    },
  };
}

/* ============================================================
   IRONROOT & IVY — frame renderer
   ============================================================ */
import { TAU, clamp, lerp, hash, DAY_START, DAY_END, SHOP, WEAPONS } from './data.js';
import { drawPlot, drawTree, drawRock, drawBush, drawDecor, drawTargetRing } from './art.js';
import { drawBarn, drawShopBack, drawCounter, drawForge, drawLedger, drawPedestal, drawWell, drawWindmill, drawCave, drawLantern } from './buildings.js';
import { drawPlayer, drawCustomer, drawBubble } from './chars.js';

export function createRenderer(canvas, state, world, groundCanvas) {
  const ctx = canvas.getContext('2d');
  let W = 0, H = 0, dpr = 1;
  const motes = Array.from({ length: 46 }, (_, i) => ({
    x: hash(i, 3) * 1.2 - .1,
    y: hash(i, 7) * 1.2 - .1,
    s: .6 + hash(i, 11) * 1.8,
    speed: .008 + hash(i, 13) * .02,
    phase: hash(i, 17) * TAU,
  }));

  function resize() {
    const w = window.innerWidth;
    const h = window.innerHeight;
    dpr = Math.min(window.devicePixelRatio || 1, 2);
    if (w === W && h === H && canvas.width === Math.round(w * dpr)) return;
    W = w; H = h;
    canvas.width = Math.round(w * dpr);
    canvas.height = Math.round(h * dpr);
    canvas.style.width = w + 'px';
    canvas.style.height = h + 'px';
  }

  function worldTransform(view) {
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
    ctx.clearRect(0, 0, W, H);
    ctx.save();
    ctx.translate(W / 2, H / 2);
    ctx.scale(view.scale, view.scale);
    ctx.translate(-view.x, -view.y);
  }

  function visible(x, y, view, margin = 180) {
    const halfW = W / (2 * view.scale) + margin;
    const halfH = H / (2 * view.scale) + margin;
    return Math.abs(x - view.x) < halfW && Math.abs(y - view.y) < halfH;
  }

  function drawWater(view, t) {
    const p = world.pond;
    if (!visible(p.x, p.y, view, 260)) return;
    ctx.save();
    ctx.beginPath();
    ctx.ellipse(p.x, p.y, p.rx - 8, p.ry - 6, 0, 0, TAU);
    ctx.clip();
    // shimmer
    ctx.strokeStyle = 'rgba(219, 246, 242, .18)';
    ctx.lineWidth = 1;
    for (let i = 0; i < 7; i++) {
      const yy = p.y - p.ry * .6 + i * 26;
      const off = Math.sin(t * .7 + i * 1.4) * 18;
      ctx.beginPath();
      ctx.ellipse(p.x + off, yy, 24 + i * 9, 3, 0, 0, TAU);
      ctx.stroke();
    }
    // glints
    for (let i = 0; i < 6; i++) {
      const a = t * .3 + i * 1.7;
      const gx = p.x + Math.cos(a) * p.rx * .62;
      const gy = p.y + Math.sin(a * 1.4) * p.ry * .5;
      ctx.fillStyle = `rgba(245, 255, 249, ${.12 + Math.sin(t * 2 + i) * .08})`;
      ctx.beginPath();
      ctx.ellipse(gx, gy, 5, 1.3, 0, 0, TAU);
      ctx.fill();
    }
    ctx.restore();
    // ducks
    const dx = p.x + Math.sin(t * .18) * 55 - 30;
    const dy = p.y + Math.cos(t * .24) * 22 + 10;
    ctx.save();
    ctx.translate(dx, dy);
    ctx.fillStyle = 'rgba(235, 228, 200, .92)';
    ctx.beginPath();
    ctx.ellipse(0, 0, 8, 4.6, 0, 0, TAU);
    ctx.fill();
    ctx.beginPath();
    ctx.arc(7, -4, 3.4, 0, TAU);
    ctx.fill();
    ctx.fillStyle = '#d59a3a';
    ctx.beginPath();
    ctx.moveTo(10, -4);
    ctx.lineTo(14, -2.6);
    ctx.lineTo(10, -1.4);
    ctx.closePath();
    ctx.fill();
    ctx.fillStyle = '#3e3a2c';
    ctx.beginPath();
    ctx.arc(8.2, -4.8, .7, 0, TAU);
    ctx.fill();
    ctx.restore();
    // wake
    ctx.strokeStyle = 'rgba(229, 248, 243, .22)';
    ctx.beginPath();
    ctx.ellipse(dx - 14, dy + 1, 12, 2, 0, 0, TAU);
    ctx.stroke();
  }

  function drawParticles(particles) {
    for (const p of particles) {
      const a = clamp(p.life / p.maxLife, 0, 1);
      ctx.save();
      ctx.globalAlpha = a;
      if (p.type === 'coin') {
        ctx.fillStyle = '#efc45b';
        ctx.beginPath();
        ctx.ellipse(p.x, p.y, 3.2, 4.2, p.rot || 0, 0, TAU);
        ctx.fill();
        ctx.strokeStyle = '#9f6f1d';
        ctx.lineWidth = .7;
        ctx.stroke();
      } else if (p.type === 'spark') {
        ctx.strokeStyle = p.color || '#f6d37a';
        ctx.lineWidth = 1.6;
        ctx.beginPath();
        ctx.moveTo(p.x, p.y);
        ctx.lineTo(p.x - p.vx * .02, p.y - p.vy * .02);
        ctx.stroke();
      } else if (p.type === 'leaf') {
        ctx.fillStyle = p.color || '#7fa85d';
        ctx.beginPath();
        ctx.ellipse(p.x, p.y, 3.4, 1.7, p.rot || 0, 0, TAU);
        ctx.fill();
      } else if (p.type === 'chip') {
        ctx.fillStyle = p.color || '#a8a49a';
        ctx.fillRect(p.x, p.y, p.size || 2, p.size || 2);
      } else if (p.type === 'water') {
        ctx.fillStyle = 'rgba(139, 201, 220, .8)';
        ctx.beginPath();
        ctx.arc(p.x, p.y, p.size || 1.6, 0, TAU);
        ctx.fill();
      } else {
        ctx.fillStyle = p.color || 'rgba(226, 213, 174, .7)';
        ctx.beginPath();
        ctx.arc(p.x, p.y, p.size || 1.8, 0, TAU);
        ctx.fill();
      }
      ctx.restore();
    }
  }

  function drawFloaters(floaters) {
    for (const f of floaters) {
      const a = clamp(f.life / f.maxLife, 0, 1);
      ctx.save();
      ctx.globalAlpha = a;
      ctx.font = `700 ${f.size || 13}px "Avenir Next", "Segoe UI", sans-serif`;
      ctx.textAlign = 'center';
      ctx.lineWidth = 3;
      ctx.strokeStyle = 'rgba(27, 40, 28, .45)';
      ctx.strokeText(f.text, f.x, f.y);
      ctx.fillStyle = f.color || '#f6e4a7';
      ctx.fillText(f.text, f.x, f.y);
      ctx.restore();
    }
  }

  function lighting(view, t) {
    const m = state.time;
    const phase = state.phase;
    let night = 0;
    if (m > 990) night = clamp((m - 990) / 170, 0, 1);
    let tint = 'rgba(0,0,0,0)';
    if (m < 585) {
      const k = 1 - clamp((m - DAY_START) / 105, 0, 1);
      tint = `rgba(255, 206, 152, ${.10 * k})`;
    } else if (m > 900 && m < 1020) {
      const k = clamp((m - 900) / 120, 0, 1);
      tint = `rgba(255, 142, 78, ${.13 * k})`;
    } else if (m >= 1020) {
      const k = clamp((m - 1020) / 160, 0, 1);
      tint = `rgba(26, 43, 84, ${.15 + .31 * k})`;
    }
    if (phase === 'title') {
      tint = `rgba(255, 186, 110, ${.06 + Math.sin(t * .1) * .015})`;
    }
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
    if (tint !== 'rgba(0,0,0,0)') {
      ctx.fillStyle = tint;
      ctx.fillRect(0, 0, W, H);
    }

    // warm light pools
    if (night > .05 || phase === 'title') {
      const lights = [
        { x: SHOP.sign.x, y: SHOP.sign.y + 60, r: 190, a: .5 },
        { x: SHOP.forge.x + 28, y: SHOP.forge.y + 30, r: 170, a: .7 },
        { x: 1040, y: 1330, r: 120, a: .4 },
        { x: 1410, y: 1330, r: 120, a: .4 },
        { x: world.cave.x - 10, y: world.cave.y + 14, r: 120, a: .35, cool: true },
      ];
      for (const l of world.lanterns) lights.push({ x: l.x + 10, y: l.y - l.h + 14, r: 145, a: .55 });
      ctx.save();
      ctx.globalCompositeOperation = 'screen';
      for (const l of lights) {
        const sx = (l.x - view.x) * view.scale + W / 2;
        const sy = (l.y - view.y) * view.scale + H / 2;
        const r = l.r * view.scale;
        if (sx < -r || sy < -r || sx > W + r || sy > H + r) continue;
        const g = ctx.createRadialGradient(sx, sy, 0, sx, sy, r);
        const a = l.a * (night * .85 + (phase === 'title' ? .5 : .06));
        if (l.cool) {
          g.addColorStop(0, `rgba(148, 124, 220, ${a * .5})`);
          g.addColorStop(.5, `rgba(96, 78, 160, ${a * .18})`);
        } else {
          g.addColorStop(0, `rgba(255, 216, 130, ${a})`);
          g.addColorStop(.45, `rgba(255, 181, 84, ${a * .35})`);
        }
        g.addColorStop(1, 'rgba(255, 180, 80, 0)');
        ctx.fillStyle = g;
        ctx.beginPath();
        ctx.arc(sx, sy, r, 0, TAU);
        ctx.fill();
      }
      ctx.restore();
    }

    // fireflies / pollen
    ctx.save();
    for (const mo of motes) {
      const x = ((mo.x + t * mo.speed * .06) % 1.2 - .1) * W;
      const y = ((mo.y + Math.sin(t * .3 + mo.phase) * .01) % 1.2 - .1) * H;
      if (night > .3) {
        const blink = Math.max(0, Math.sin(t * 1.8 + mo.phase * 3));
        ctx.globalAlpha = blink * .55 * night;
        ctx.fillStyle = '#f7e39a';
        ctx.shadowColor = '#f6d36d';
        ctx.shadowBlur = 8;
        ctx.beginPath();
        ctx.arc(x, y, 1.4 + mo.s * .5, 0, TAU);
        ctx.fill();
      } else {
        ctx.globalAlpha = .18 + Math.sin(t * .5 + mo.phase) * .08;
        ctx.fillStyle = '#fff3cb';
        ctx.beginPath();
        ctx.arc(x, y, mo.s * .7, 0, TAU);
        ctx.fill();
      }
    }
    ctx.restore();

    // vignette
    const v = ctx.createRadialGradient(W / 2, H * .46, Math.min(W, H) * .34, W / 2, H * .5, Math.max(W, H) * .78);
    v.addColorStop(0, 'rgba(20, 30, 20, 0)');
    v.addColorStop(1, `rgba(15, 24, 17, ${.18 + night * .18})`);
    ctx.fillStyle = v;
    ctx.fillRect(0, 0, W, H);
  }

  function draw(t, view, player, nearest, particles, floaters) {
    resize();
    worldTransform(view);

    // ground
    ctx.drawImage(groundCanvas, 0, 0, groundCanvas.width, groundCanvas.height, 0, 0, 2400, 1800);
    drawWater(view, t);

    // interaction ring under objects
    if (nearest && state.phase === 'playing' && !state.modal) {
      drawTargetRing(ctx, nearest.x, nearest.y, nearest.r || 30, t);
    }

    const items = [];
    const add = (base, fn) => items.push({ base, fn });

    for (const p of world.plots) {
      if (!visible(p.cx, p.cy, view)) continue;
      add(p.y + p.h, () => drawPlot(ctx, p, t));
    }
    for (const n of world.nodes) {
      if (!visible(n.x, n.y, view)) continue;
      add(n.y + 8, () => (n.kind === 'tree' ? drawTree(ctx, n, t) : drawRock(ctx, n, t)));
    }
    for (const d of world.decoTrees) {
      if (!visible(d.x, d.y, view)) continue;
      add(d.y + 8, () => drawTree(ctx, d, t, true));
    }
    for (const b of world.bushes) {
      if (!visible(b.x, b.y, view)) continue;
      add(b.y + 4, () => drawBush(ctx, b, t));
    }
    for (const d of world.decorations) {
      if (!visible(d.x, d.y, view)) continue;
      add(d.y + 2, () => drawDecor(ctx, d, t));
    }

    if (visible(world.barn.x, world.barn.y, view, 320)) add(world.barn.y + world.barn.h, () => drawBarn(ctx, world.barn));
    if (visible(SHOP.wall.x, SHOP.wall.y, view, 320)) add(SHOP.wall.y + SHOP.wall.h, () => drawShopBack(ctx, t));
    if (visible(SHOP.counter.x, SHOP.counter.y, view, 260)) add(SHOP.counter.y + SHOP.counter.h, () => drawCounter(ctx));
    if (visible(SHOP.forge.x, SHOP.forge.y, view, 220)) add(SHOP.forge.y + SHOP.forge.h, () => drawForge(ctx, t));
    if (visible(SHOP.ledger.x, SHOP.ledger.y, view, 200)) add(SHOP.ledger.y + SHOP.ledger.h, () => drawLedger(ctx, t));
    state.pedestals.forEach((ped, i) => {
      if (!visible(ped.x, ped.y, view, 180)) return;
      add(ped.y + 16, () => drawPedestal(ctx, ped, i, t));
    });
    if (visible(world.well.x, world.well.y, view, 240)) add(world.well.y + 38, () => drawWell(ctx, world.well, t));
    if (visible(world.windmill.x, world.windmill.y, view, 300)) add(world.windmill.y + 42, () => drawWindmill(ctx, world.windmill, t));
    if (visible(world.cave.x, world.cave.y, view, 320)) add(world.cave.y + 70, () => drawCave(ctx, world.cave, t));
    for (const l of world.lanterns) {
      if (!visible(l.x, l.y, view, 140)) continue;
      add(l.y + 2, () => drawLantern(ctx, l, t));
    }

    // people
    if (state.phase !== 'title') {
      for (const c of state.customers) {
        if (!visible(c.x, c.y, view, 120)) continue;
        add(c.y + 2, () => drawCustomer(ctx, c, t));
      }
    }
    add(player.y + 2, () => drawPlayer(ctx, player, t, state.player.tool));

    items.sort((a, b) => a.base - b.base);
    for (const item of items) item.fn();

    // bubbles & floaters above everything
    if (state.phase !== 'title') {
      for (const c of state.customers) {
        if (!visible(c.x, c.y, view, 160)) continue;
        if (c.bubble) drawBubble(ctx, c, c.bubble, t);
      }
    }
    drawParticles(particles);
    drawFloaters(floaters);

    ctx.restore();
    lighting(view, t);
  }

  return { draw, resize, get size() { return { W, H, dpr }; } };
}

/* ============================================================
   IRONROOT & IVY — interface controller
   ============================================================ */
import { WEAPONS, WEAPON_ORDER, RESOURCES, RES_ORDER, QUESTS, GOAL, DAYS, fmt, clamp } from './data.js';
import { drawWeaponIcon } from './art.js';

const TAG_LABEL = { swift: 'Swift blade', heavy: 'Heavy weapon', farm: 'Field tool', arcane: 'Arcane arm' };
const DAY_WORDS = ['one', 'two', 'three', 'four', 'five', 'six', 'seven', 'eight', 'nine', 'ten'];

export function createUI({ state, actions, audio }) {
  const $ = (id) => document.getElementById(id);
  const el = {
    hud: $('hud'),
    start: $('startScreen'),
    startBtn: $('startBtn'),
    startHelp: $('startHelpBtn'),
    dayNum: $('dayNum'),
    clock: $('clock'),
    dayPhase: $('dayPhase'),
    sunDot: $('sunDot'),
    gold: $('gold'),
    goalText: $('goalText'),
    goalFill: $('goalFill'),
    questList: $('questList'),
    questCount: $('questCount'),
    questDots: $('questDots'),
    inventory: $('inventory'),
    satchel: $('satchel'),
    prompt: $('prompt'),
    promptKey: $('promptKey'),
    promptText: $('promptText'),
    toasts: $('toasts'),
    saleBanner: $('saleBanner'),
    cornerHint: $('cornerHint'),
    modalLayer: $('modalLayer'),
    modalBody: $('modalBody'),
    dayScreen: $('dayScreen'),
    dayEyebrow: $('dayEyebrow'),
    dayTitle: $('dayTitle'),
    daySub: $('daySub'),
    dayStats: $('dayStats'),
    dayGoalFill: $('dayGoalFill'),
    dayGoalText: $('dayGoalText'),
    dayTip: $('dayTip'),
    nextDayBtn: $('nextDayBtn'),
    endScreen: $('endScreen'),
    endSeal: $('endSeal'),
    endEyebrow: $('endEyebrow'),
    endTitle: $('endTitle'),
    endSub: $('endSub'),
    endStats: $('endStats'),
    endMainBtn: $('endMainBtn'),
    endNewBtn: $('endNewBtn'),
    pauseScreen: $('pauseScreen'),
    resumeBtn: $('resumeBtn'),
    pauseHelp: $('pauseHelpBtn'),
    restartBtn: $('restartBtn'),
    soundBtn: $('soundBtn'),
    helpBtn: $('helpBtn'),
    pauseBtn: $('pauseBtn'),
    touch: $('touch'),
    actionBtn: $('actionBtn'),
  };

  let currentModal = null;
  let toastTimer = 0;
  let saleTimer = 0;
  let hintTimer = 0;
  let lastWeaponSig = '';
  let lastGold = state.gold;
  const resEls = {};
  let touchEnabled = false;

  /* ---------------- init ---------------- */
  function init() {
    el.inventory.innerHTML = RES_ORDER.map((id) => {
      const r = RESOURCES[id];
      return `<div class="res-chip zero" data-res="${id}" title="${r.name}">
        <svg><use href="#i-${r.icon}"/></svg>
        <span class="res-num">0</span>
        <span class="res-name">${r.name}</span>
      </div>`;
    }).join('');
    for (const id of RES_ORDER) resEls[id] = el.inventory.querySelector(`[data-res="${id}"]`);

    el.questList.innerHTML = QUESTS.map((q) => `
      <li data-quest="${q.id}">
        <span class="q-box"><svg><use href="#i-check"/></svg></span>
        <span class="q-text">${q.text}</span>
        <span class="q-reward">+${q.reward}g</span>
      </li>`).join('');
    el.questDots.innerHTML = QUESTS.map(() => '<i></i>').join('');

    el.startBtn.addEventListener('click', () => { audio.init(); audio.play('start'); actions.startGame(); });
    el.startHelp.addEventListener('click', () => { audio.init(); audio.play('ui'); openModal('help'); });
    el.soundBtn.addEventListener('click', () => { const on = audio.toggle(); updateSoundIcon(on); audio.play('ui'); });
    el.helpBtn.addEventListener('click', () => { audio.play('ui'); openModal('help'); });
    el.pauseBtn.addEventListener('click', () => { audio.play('ui'); actions.pause(); });
    el.resumeBtn.addEventListener('click', () => { audio.play('ui'); actions.resume(); });
    el.pauseHelp.addEventListener('click', () => { audio.play('ui'); openModal('help'); });
    el.restartBtn.addEventListener('click', () => actions.restart());
    el.nextDayBtn.addEventListener('click', () => { audio.play('ui'); actions.nextDay(); });
    el.endMainBtn.addEventListener('click', () => { audio.play('ui'); actions.endMain(); });
    el.endNewBtn.addEventListener('click', () => { audio.play('ui'); actions.restart(); });

    el.modalLayer.addEventListener('click', (e) => {
      if (e.target.closest('[data-close-modal]')) {
        audio.play('ui');
        closeModal();
        return;
      }
      const btn = e.target.closest('[data-action]');
      if (!btn) return;
      handleAction(btn.dataset.action, btn.dataset, btn);
    });

    window.addEventListener('resize', () => { updateTouchVisibility(); });
    updateSoundIcon(audio.enabled);
    updateTouchVisibility();
    sync();
  }

  function updateTouchVisibility() {
    const should = state.phase === 'playing' && (window.innerWidth < 820 || matchMedia('(pointer: coarse)').matches);
    touchEnabled = should;
    el.touch.classList.toggle('is-hidden', !should);
  }

  function updateSoundIcon(on) {
    el.soundBtn.innerHTML = `<svg><use href="#i-${on ? 'sound' : 'muted'}"/></svg>`;
    el.soundBtn.title = on ? 'Sound on (M)' : 'Sound off (M)';
  }

  /* ---------------- phases ---------------- */
  function setPhase(phase) {
    if (phase === 'title') {
      el.start.classList.remove('out');
      el.start.style.display = '';
      el.hud.classList.add('is-hidden');
      el.touch.classList.add('is-hidden');
      el.dayScreen.classList.add('is-hidden');
      el.endScreen.classList.add('is-hidden');
      el.pauseScreen.classList.add('is-hidden');
      closeModal(true);
    } else if (phase === 'playing') {
      if (!el.start.classList.contains('out')) {
        el.start.classList.add('out');
        setTimeout(() => { el.start.style.display = 'none'; }, 650);
      }
      el.hud.classList.remove('is-hidden');
      el.dayScreen.classList.add('is-hidden');
      el.endScreen.classList.add('is-hidden');
      el.pauseScreen.classList.add('is-hidden');
      updateTouchVisibility();
    } else if (phase === 'summary') {
      el.hud.classList.remove('is-hidden');
      el.touch.classList.add('is-hidden');
    } else if (phase === 'end') {
      el.hud.classList.remove('is-hidden');
      el.touch.classList.add('is-hidden');
    } else if (phase === 'paused') {
      el.pauseScreen.classList.remove('is-hidden');
      el.touch.classList.add('is-hidden');
    }
  }

  /* ---------------- HUD sync ---------------- */
  function sync() {
    el.dayNum.textContent = state.day;
    const mins = Math.floor(state.time);
    const hh = String(Math.floor(mins / 60)).padStart(2, '0');
    const mm = String(mins % 60).padStart(2, '0');
    el.clock.textContent = `${hh}:${mm}`;
    el.dayPhase.textContent = mins < 660 ? 'Morning' : mins < 900 ? 'Afternoon' : mins < 1080 ? 'Evening' : 'Night';
    const dayPct = clamp((state.time - 480) / 720, 0, 1);
    el.sunDot.style.left = `${dayPct * 100}%`;

    el.gold.textContent = fmt(state.gold);
    el.goalText.textContent = `${fmt(state.gold)} / ${fmt(GOAL)}g`;
    el.goalFill.style.width = `${clamp(state.gold / GOAL, 0, 1) * 100}%`;
    if (state.gold > lastGold) {
      el.gold.animate?.(
        [{ transform: 'scale(1)' }, { transform: 'scale(1.18)' }, { transform: 'scale(1)' }],
        { duration: 320, easing: 'ease-out' }
      );
    }
    lastGold = state.gold;

    for (const id of RES_ORDER) {
      const node = resEls[id];
      if (!node) continue;
      const val = state.resources[id] || 0;
      const num = node.querySelector('.res-num');
      if (num.textContent !== String(val)) {
        num.textContent = val;
        if (Number(num.dataset.prev || 0) < val) {
          node.classList.remove('bump');
          void node.offsetWidth;
          node.classList.add('bump');
        }
        num.dataset.prev = val;
      }
      node.classList.toggle('zero', val === 0);
    }

    // quests
    let done = 0;
    let activeFound = false;
    for (const q of QUESTS) {
      const qs = state.quests[q.id];
      const row = el.questList.querySelector(`[data-quest="${q.id}"]`);
      if (!row) continue;
      const isDone = qs.progress >= q.target;
      if (isDone) done++;
      row.classList.toggle('done', isDone);
      const isActive = !isDone && !activeFound;
      if (isActive) activeFound = true;
      row.classList.toggle('active', isActive);
      row.querySelector('.q-text').textContent = isDone ? q.text : `${q.text}${q.target > 1 ? ` · ${Math.min(qs.progress, q.target)}/${q.target}` : ''}`;
    }
    el.questCount.textContent = `${done} / ${QUESTS.length}`;
    [...el.questDots.children].forEach((d, i) => d.classList.toggle('on', i < done));

    // satchel
    const sig = WEAPON_ORDER.map((id) => `${id}:${state.weapons[id] || 0}`).join('|');
    if (sig !== lastWeaponSig) {
      lastWeaponSig = sig;
      renderSatchel();
    }

    // day goal if visible
    if (!el.dayScreen.classList.contains('is-hidden')) {
      el.dayGoalFill.style.width = `${clamp(state.gold / GOAL, 0, 1) * 100}%`;
      el.dayGoalText.textContent = `${fmt(state.gold)} / ${fmt(GOAL)}g`;
    }
  }

  function renderSatchel() {
    const entries = WEAPON_ORDER.filter((id) => (state.weapons[id] || 0) > 0);
    const total = entries.reduce((s, id) => s + state.weapons[id], 0);
    if (!entries.length) {
      el.satchel.innerHTML = `<div class="satchel-head"><span>Satchel</span><b>empty</b></div><div class="satchel-empty">Forge a weapon, then stock a pedestal.</div>`;
      return;
    }
    const shown = entries.slice(0, 4);
    el.satchel.innerHTML = `<div class="satchel-head"><span>Satchel</span><b>${total} wares</b></div>
      <div class="satchel-list">${shown.map((id) => {
        const w = WEAPONS[id];
        const icon = w.kind === 'axe' ? 'axe' : w.kind === 'scythe' ? 'scythe' : 'sword';
        return `<span class="satchel-item" title="${w.name}"><svg><use href="#i-${icon}"/></svg><b>${state.weapons[id]}</b></span>`;
      }).join('')}${entries.length > 4 ? `<span class="satchel-item"><b>+${entries.length - 4}</b></span>` : ''}</div>`;
  }

  /* ---------------- prompt ---------------- */
  function updatePrompt(nearest) {
    if (!nearest || state.modal || state.phase !== 'playing') {
      el.prompt.classList.add('is-hidden');
      return;
    }
    el.prompt.classList.remove('is-hidden');
    el.promptText.innerHTML = nearest.prompt;
    if (nearest.key) el.promptKey.textContent = nearest.key;
  }

  /* ---------------- toasts ---------------- */
  function toast(text, opts = {}) {
    const { kind = '', icon = 'leaf', duration = 3400 } = opts;
    while (el.toasts.children.length >= 4) el.toasts.firstElementChild.remove();
    const node = document.createElement('div');
    node.className = `toast ${kind}`;
    node.innerHTML = `<span class="t-ico"><svg><use href="#i-${icon}"/></svg></span><span>${text}</span>`;
    el.toasts.appendChild(node);
    setTimeout(() => {
      node.classList.add('out');
      setTimeout(() => node.remove(), 320);
    }, duration);
  }

  function sale(name, price) {
    el.saleBanner.innerHTML = `<div class="sb-eyebrow"><svg><use href="#i-spark"/></svg> Sold at the counter</div>
      <div class="sb-name">${name}</div>
      <div class="sb-price">+<b>${fmt(price)} gold</b> · a happy customer</div>`;
    el.saleBanner.classList.add('show');
    clearTimeout(saleTimer);
    saleTimer = setTimeout(() => el.saleBanner.classList.remove('show'), 3400);
  }

  function hint(text, duration = 4200) {
    el.cornerHint.textContent = text;
    el.cornerHint.classList.add('show');
    clearTimeout(hintTimer);
    hintTimer = setTimeout(() => el.cornerHint.classList.remove('show'), duration);
  }

  /* ---------------- modal ---------------- */
  function openModal(type, data = {}) {
    currentModal = { type, data };
    state.modal = { type, data };
    el.modalLayer.classList.remove('is-hidden');
    renderModal();
  }

  function closeModal(silent = false) {
    currentModal = null;
    state.modal = null;
    el.modalLayer.classList.add('is-hidden');
    if (!silent) audio.play('page');
  }

  function refreshModal() {
    if (!currentModal) return;
    renderModal();
  }

  function renderModal() {
    if (!currentModal) return;
    let html = '';
    if (currentModal.type === 'craft') html = renderCraft();
    else if (currentModal.type === 'pedestal') html = renderPedestal(currentModal.data.index);
    else if (currentModal.type === 'ledger') html = renderLedger();
    else if (currentModal.type === 'help') html = renderHelp();
    el.modalBody.innerHTML = html;
    el.modalBody.scrollTop = 0;
    for (const c of el.modalBody.querySelectorAll('canvas[data-weapon]')) drawWeaponIcon(c, c.dataset.weapon);
  }

  function bonus() { return state.upgrades.bellows ? 1.2 : 1; }

  function renderCraft() {
    const cards = WEAPON_ORDER.map((id) => {
      const w = WEAPONS[id];
      const can = Object.entries(w.cost).every(([r, n]) => (state.resources[r] || 0) >= n);
      const costs = Object.entries(w.cost).map(([r, n]) => {
        const have = state.resources[r] || 0;
        return `<span class="cost-chip ${have < n ? 'missing' : ''}"><svg><use href="#i-${RESOURCES[r].icon}"/></svg>${n}</span>`;
      }).join('');
      return `<article class="recipe-card ${can ? '' : 'cant'}">
        <canvas class="weapon-thumb" data-weapon="${id}" width="74" height="74"></canvas>
        <div class="recipe-info">
          <h3>${w.name}</h3>
          <span class="recipe-tag">${TAG_LABEL[w.tag]}</span>
          <p class="recipe-desc">${w.desc}</p>
          <div class="cost-row">${costs}</div>
        </div>
        <div class="recipe-foot">
          <span class="recipe-value">${fmt(w.base * bonus())}g<small>value</small></span>
          <button class="craft-btn" data-action="craft" data-id="${id}" ${can ? '' : 'disabled'}>Forge</button>
        </div>
      </article>`;
    }).join('');
    return `<div class="modal-head">
      <div class="head-row">
        <div>
          <p class="eyebrow">The forge</p>
          <h2>Hammer something worth selling</h2>
          <p>Everything you grow and dig comes together here. Forge a weapon, then carry it to a display pedestal.</p>
        </div>
        <span class="forge-bonus"><svg><use href="#i-spark"/></svg>${state.upgrades.bellows ? 'Bellows lit · +20% value' : 'Bellows unlit'}</span>
      </div>
    </div>
    <div class="recipe-grid">${cards}</div>
    <div class="craft-note"><svg><use href="#i-shop"/></svg>Weapons wait in your satchel until you stock them on a pedestal.</div>`;
  }

  function renderPedestal(index) {
    const ped = state.pedestals[index];
    if (!ped) return '';
    if (!ped.unlocked) {
      return `<div class="modal-head"><p class="eyebrow">Display ${index + 1}</p><h2>A covered pedestal</h2>
        <p>This spot is waiting for a little investment. Buy another display pedestal from the shop ledger and put it to work.</p></div>
        <button class="btn btn-paper" data-action="open-ledger">Open the shop ledger <span>→</span></button>`;
    }
    if (!ped.weapon) {
      const entries = WEAPON_ORDER.filter((id) => (state.weapons[id] || 0) > 0);
      const cards = entries.map((id) => {
        const w = WEAPONS[id];
        return `<article class="stock-card">
          <canvas data-weapon="${id}" width="78" height="78"></canvas>
          <h3>${w.name}</h3>
          <small>${state.weapons[id]} in satchel · ${fmt(w.base * bonus())}g base</small>
          <button data-action="place" data-id="${id}">Place here</button>
        </article>`;
      }).join('');
      return `<div class="modal-head"><p class="eyebrow">Display ${index + 1}</p><h2>Dress the pedestal</h2>
        <p>Choose a weapon from your satchel. Customers will browse whatever is on show.</p></div>
        ${entries.length ? `<div class="stock-grid">${cards}</div>` : `<div class="empty-note">Your satchel is empty. Visit the forge and make something beautiful.</div>
        <button class="btn btn-paper" style="margin-top:14px" data-action="open-forge">Open the forge <span>→</span></button>`}`;
    }
    const w = WEAPONS[ped.weapon];
    const mult = ped.mult || 1;
    const demand = mult <= .92 ? ['Bargain', 'They will queue for this', 92]
      : mult <= 1.1 ? ['Fair', 'Most will bite', 66]
        : mult <= 1.3 ? ['Dear', 'Only keen collectors', 38]
          : ['Bold', 'Expect a lot of browsing', 18];
    const pricePct = clamp((mult - .7) / .8, 0, 1) * 100;
    return `<div class="modal-head"><p class="eyebrow">Display ${index + 1}</p><h2>Set the price</h2>
      <p>Low prices empty the shelf. High prices fill the ledger — if the right customer walks in.</p></div>
      <div class="display-grid">
        <div class="display-preview">
          <canvas data-weapon="${ped.weapon}" width="150" height="150"></canvas>
          <span class="dp-stock">In stock ×${ped.qty}</span>
        </div>
        <div class="display-info">
          <span class="display-tag">${TAG_LABEL[w.tag]} · base ${fmt(w.base * bonus())}g</span>
          <h2>${w.name}</h2>
          <p class="display-desc">${w.desc}</p>
          <div class="price-editor">
            <button class="price-btn" data-action="price" data-delta="-1" aria-label="Lower price">−</button>
            <div class="price-main"><b>${fmt(ped.price)}g</b><small>asking price</small></div>
            <button class="price-btn" data-action="price" data-delta="1" aria-label="Raise price">+</button>
          </div>
          <div class="demand">
            <div class="demand-head"><span>Customer appetite</span><b>${demand[0]}</b></div>
            <div class="demand-track"><span style="width:${pricePct}%"></span></div>
            <div class="demand-head" style="margin-top:4px"><span>${demand[1]}</span><span>${Math.round(mult * 100)}% of base</span></div>
          </div>
          <div class="display-actions">
            <button class="btn btn-paper" data-action="addstock" ${(state.weapons[ped.weapon] || 0) > 0 && ped.qty < 3 ? '' : 'disabled'}>Add stock (${state.weapons[ped.weapon] || 0} left)</button>
            <button class="btn btn-outline" data-action="clear">Return to satchel</button>
          </div>
        </div>
      </div>`;
  }

  function renderLedger() {
    const unlocked = state.pedestals.filter((p) => p.unlocked).length;
    const up = state.upgrades;
    const upgradeCard = (id, icon, title, desc, cost, owned) => `
      <article class="upgrade-card">
        <span class="u-ico"><svg><use href="#i-${icon}"/></svg></span>
        <h4>${title}</h4>
        <p>${desc}</p>
        <div class="u-buy">
          ${owned ? `<span class="u-owned">Owned</span>` : `<span class="u-price"><svg><use href="#i-coin"/></svg>${cost}</span>`}
          ${owned ? '' : `<button data-action="buy-upgrade" data-id="${id}" ${state.gold < cost ? 'disabled' : ''}>Buy</button>`}
        </div>
      </article>`;
    return `<div class="modal-head"><p class="eyebrow">The shop ledger</p><h2>Keep the lights on</h2>
      <p>Seven days to earn <b>${fmt(GOAL)} gold</b>. Spend a little to make the shop busier, brighter, and harder to ignore.</p></div>
      <div class="ledger-stats">
        <div class="stat-tile"><span>Shop fund</span><b class="gold">${fmt(state.gold)}g</b></div>
        <div class="stat-tile"><span>Total earned</span><b>${fmt(state.earned)}g</b></div>
        <div class="stat-tile"><span>Weapons sold</span><b>${state.totalSales}</b></div>
        <div class="stat-tile"><span>Day</span><b>${state.day} / ${DAYS}</b></div>
      </div>
      <div class="ledger-section">
        <h3><svg><use href="#i-spark"/></svg>Investments</h3>
        <div class="upgrade-grid">
          ${upgradeCard('sign', 'shop', 'Painted sign', 'Word travels faster. More customers visit each day.', 140, up.sign)}
          ${upgradeCard('pedestal', 'hammer', 'Display pedestal', `One more shelf for your wares. ${unlocked} of 4 in use.`, 180, unlocked >= 4)}
          ${upgradeCard('bellows', 'spark', 'Forge bellows', 'A hotter fire. Every weapon is worth 20% more.', 240, up.bellows)}
        </div>
      </div>
      <div class="ledger-foot">
        <p>Close up early and the day still counts. The festival waits for no one.</p>
        <button class="btn btn-paper" data-action="end-day">Close up for the night</button>
      </div>`;
  }

  function renderHelp() {
    const steps = [
      ['Grow', 'Interact with a farm plot to plant. Water it to double the growth. Harvest when the sparkle appears.'],
      ['Delve', 'Chop oak in the wood, mine stone and iron in the quarry. Crystal hides near the old cave.'],
      ['Forge', 'The forge by the shop turns crops, wood, and ore into six kinds of weapon.'],
      ['Sell', 'Place a weapon on a pedestal. Set the price, keep it stocked, and customers will do the rest.'],
      ['Read the room', 'Rangers like swift blades. Knights want weight. Mages chase crystal. Farmers need a scythe.'],
      ['Save the shop', `Reach ${fmt(GOAL)} gold before the end of day ${DAYS}. Upgrade the shop along the way.`],
    ];
    return `<div class="modal-head"><p class="eyebrow">A field guide</p><h2>How to run a shop</h2>
      <p>Farm by dawn, forge by dusk, sell by lantern light. There is no wrong way to spend a day — only a shop that stays open.</p></div>
      <div class="help-grid">${steps.map((s, i) => `<div class="help-step"><span class="h-num">${i + 1}</span><div><h4>${s[0]}</h4><p>${s[1]}</p></div></div>`).join('')}</div>
      <div class="help-controls">
        <span><kbd>WASD</kbd> / <kbd>↑↓←→</kbd> move</span>
        <span><kbd>E</kbd> / <kbd>Space</kbd> interact</span>
        <span><kbd>Shift</kbd> hurry</span>
        <span><kbd>M</kbd> sound</span>
        <span><kbd>Esc</kbd> pause / close</span>
      </div>`;
  }

  function handleAction(action, data, btn) {
    audio.play('ui');
    if (action === 'craft') {
      actions.craft(data.id);
      refreshModal();
      sync();
    } else if (action === 'place') {
      actions.placeWeapon(currentModal.data.index, data.id);
      refreshModal();
      sync();
    } else if (action === 'price') {
      actions.adjustPrice(currentModal.data.index, Number(data.delta));
      refreshModal();
      sync();
    } else if (action === 'addstock') {
      actions.addStock(currentModal.data.index);
      refreshModal();
      sync();
    } else if (action === 'clear') {
      actions.clearPedestal(currentModal.data.index);
      refreshModal();
      sync();
    } else if (action === 'buy-upgrade') {
      actions.buyUpgrade(data.id);
      refreshModal();
      sync();
    } else if (action === 'open-ledger') {
      openModal('ledger');
    } else if (action === 'open-forge') {
      openModal('craft');
    } else if (action === 'end-day') {
      closeModal(true);
      actions.endDay();
    }
  }

  /* ---------------- day / end / pause ---------------- */
  function showDay(summary) {
    el.dayEyebrow.textContent = `Day ${DAY_WORDS[summary.day - 1] || summary.day}, closed`;
    el.dayTitle.textContent = summary.title;
    el.daySub.textContent = summary.sub;
    el.dayStats.innerHTML = `
      <div class="stat-tile"><span>Earned today</span><b class="gold">${fmt(summary.earned)}g</b></div>
      <div class="stat-tile"><span>Weapons sold</span><b>${summary.sales}</b></div>
      <div class="stat-tile"><span>Shop fund</span><b>${fmt(summary.gold)}g</b></div>`;
    el.dayGoalFill.style.width = `${clamp(summary.gold / GOAL, 0, 1) * 100}%`;
    el.dayGoalText.textContent = `${fmt(summary.gold)} / ${fmt(GOAL)}g`;
    el.dayTip.textContent = summary.tip;
    el.nextDayBtn.innerHTML = summary.final ? 'See how the week ends <span>→</span>' : 'Sleep until morning <span>→</span>';
    el.dayScreen.classList.remove('is-hidden');
    state.phase = 'summary';
    setPhase('summary');
  }

  function hideDay() {
    el.dayScreen.classList.add('is-hidden');
  }

  function showEnd(result) {
    el.endSeal.innerHTML = `<svg><use href="#i-${result.win ? 'spark' : 'leaf'}"/></svg>`;
    el.endEyebrow.textContent = result.win ? 'Seven days later' : 'The festival morning';
    el.endTitle.textContent = result.title;
    el.endSub.textContent = result.sub;
    el.endStats.innerHTML = `
      <div class="stat-tile"><span>Shop fund</span><b class="gold">${fmt(result.gold)}g</b></div>
      <div class="stat-tile"><span>Total earned</span><b>${fmt(result.earned)}g</b></div>
      <div class="stat-tile"><span>Weapons sold</span><b>${result.sales}</b></div>`;
    el.endMainBtn.textContent = result.win ? 'Keep trading' : 'Try again';
    el.endNewBtn.classList.toggle('is-hidden', !result.win);
    el.endScreen.classList.remove('is-hidden');
    state.phase = 'end';
    setPhase('end');
  }

  function hideEnd() {
    el.endScreen.classList.add('is-hidden');
  }

  function showPause() {
    el.pauseScreen.classList.remove('is-hidden');
    state.phase = 'paused';
    setPhase('paused');
  }

  function hidePause() {
    el.pauseScreen.classList.add('is-hidden');
  }

  return {
    init, sync, setPhase, updatePrompt, toast, sale, hint, openModal, closeModal, refreshModal,
    showDay, hideDay, showEnd, hideEnd, showPause, hidePause, updateSoundIcon, updateTouchVisibility,
    get currentModal() { return currentModal; },
    get touchEnabled() { return touchEnabled; },
  };
}

content.text:
Need add `.btn-outline` CSS later.

Now game.js core. Need state, player, camera, input, actions, update, loop, interactions, particles, customers, quests, economy, day flow, attract mode, testing hooks.

Let's carefully design.

Imports:
```js
import { WORLD, GOAL, DAYS, DAY_START, DAY_END, TIME_RATE, clamp, lerp, rand, pick, dist, fmt, TAU, SHOP, CROPS, WEAPONS, WEAPON_ORDER, RESOURCES, RES_ORDER, CUSTOMER_TYPES, QUESTS, createWorld } from './data.js';
import { buildGround } from './ground.js';
import { createRenderer } from './render.js';
import { createAudio } from './audio.js';
import { createUI } from './ui.js';
```

Setup:
```js
const canvas = document.getElementById('game');
const world = createWorld();
const ground = buildGround(world);
const audio = createAudio();
const state = {
 phase:'title', day:1, time:DAY_START, gold:60, earned:0, totalSales:0,
 resources:{...0}, weapons:{...0},
 pedestals: SHOP.pedestals.map((p,i)=>({...p,unlocked:i<2,weapon:null,qty:0,mult:1,price:0})),
 upgrades:{sign:false,pedestals:2,bellows:false},
 quests: Object.fromEntries(QUESTS.map(q=>[q.id,{progress:0}])),
 customers:[], particles:[], floaters:[],
 modal:null, firstDisplay:false, customerTimer:8, dayEarned:0, daySales:0,
 endless:false, startedAt:0, lastFrame:0, attract:0,
};
const player={x:1210,y:1590,r:16,facing:-Math.PI/2,speed:0,moving:false,walkTime:0,tool:null};
const view={x:player.x,y:player.y,scale:1};
```
Pedestal price default: `price: Math.round(weapon.base*bonus*mult)` computed when placed.

Set initial resources maybe 0. Start gold 60.

Camera initial at player for title? Attract mode camera pans. Set view to shop.

Renderer created after state.

UI created with actions object referencing functions defined later (function declarations hoisted). `const ui = createUI({ state, actions, audio })` but actions object needs ui? We can create actions object with methods that call `ui` variable; define `let ui;` then actions functions reference ui after init. Or create UI after actions object with callbacks that use `ui` declared later. JS closures fine as long as called after assignment. We'll define `const actions = {...}` using function declarations, then `const ui = createUI({state, actions, audio})`. But actions.startGame calls `ui.toast`; ui defined by then at click time. Fine. `actions` object literal references functions declared below (hoisted) or methods inline.

Simpler:
```js
const actions = {
 startGame, craft, placeWeapon, adjustPrice, addStock, clearPedestal, buyUpgrade,
 endDay, nextDay, endMain, pause, resume, restart, ...
};
const ui = createUI({state, actions, audio});
ui.init();
```

But functions use `ui` const declared after; closure fine as long as invoked after initialization. `startGame` not called during UI init except button events later. Good.

**StartGame**:
```js
function startGame(){
 state.phase='playing';
 state.startedAt=performance.now();
 audio.init();
 ui.setPhase('playing');
 ui.sync();
 ui.toast('Welcome to Ironroot & Ivy', {icon:'leaf', duration:4200});
 setTimeout(()=>ui.toast('Seven days to earn 1,200 gold. The shop is yours.', {icon:'coin', kind:'gold', duration:4600}), 900);
 setTimeout(()=>ui.hint('Follow the checklist on the left — or ignore it and make something beautiful.'), 1600);
}
```
Maybe not too many toasts. Use 2.
- Start camera snap to player.
- state.customerTimer = 10.

**Pause**:
```js
function pause(){ if(state.phase!=='playing') return; state.prevPhase='playing'; ui.showPause(); }
function resume(){ if(state.phase!=='paused') return; ui.hidePause(); state.phase='playing'; ui.setPhase('playing'); }
```
But `ui.setPhase('playing')` hides pause and shows hud; start already out. Good.
- Help modal opened while paused; closing returns to pause screen. `state.phase` remains 'paused'. UI close sets modal null. Good.
- When open help from pause, UI openModal; game update frozen because phase != playing anyway.

**Input**:
- keys set.
- movement vector.
- keydown:
```js
if (e.code === 'Escape') {
 if (state.modal) { ui.closeModal(); return; }
 if (state.phase==='playing') pause();
 else if (state.phase==='paused') resume();
 return;
}
if (state.phase==='title') { if (Enter/Space) start? Maybe. }
if (e.code==='KeyM') toggle sound.
if (e.code==='KeyE'||e.code==='Space') { e.preventDefault(); if(!e.repeat) interact(); }
```
- Space in title triggers start; Enter too.
- Movement keys prevent default only for arrows/space.
- Shift sprint.
- On blur clear keys.

Touch:
- stick pointer events. Use pointer capture.
- compute vector.
- actionBtn pointerdown -> interact.
- Ensure not when modal/phase.

**Update loop**:
```js
function frame(now){
 const dt=Math.min((now-last)/1000, .05); last=now; t+=dt;
 if (state.phase==='title') updateAttract(dt);
 else if (state.phase==='playing' && !state.modal) updateGame(dt);
 else updateAmbient(dt);
 updateParticles(dt); updateFloaters(dt); // particles should update even in modal? maybe freeze. Only update when playing; but ambient particles can continue.
 camera...
 renderer.draw(t, view, player, nearest, state.particles, state.floaters);
 ui.updatePrompt(nearest); // only if changed
 requestAnimationFrame(frame);
}
```
Need nearest computed even when paused? hide prompt when modal. `findNearest()` each frame. UI updatePrompt each frame sets innerHTML every frame; that's bad. Cache prompt string. UI could track. We can compute nearest and call `ui.updatePrompt` only if changed. Implement in game: `let lastPromptKey=''`; compare nearest?.id+prompt. But UI hides when modal; call with null. Good.

- `state.time` increments dt*TIME_RATE (3.51 game min/s) while playing and no modal. At day end call endDay.
- update crops, nodes, customers, spawn.
- Update player movement.
- camera follow. In title, camera pans.
- UI sync every ~0.15s (timer).
- update ambient particles.

**Attract mode**:
- Camera moves between points with smooth sin:
```js
const attractPts=[{x:600,y:660},{x:1200,y:1180},{x:1700,y:560},{x:900,y:900}];
state.attract += dt*.035;
const idx=Math.floor(state.attract)%len; next; t=...
view.x=lerp; view.y=...
```
- player stands at shop, not moving; maybe tool none.
- no customers.
- scale computed in renderer? We need view.scale set. Compute in updateView:
```js
function computeScale(){ const w=innerWidth,h=innerHeight; if(w<900) return clamp(Math.max(w/620,h/880),.82,1.15); return clamp(Math.min(w/1220,h/780),.95,1.35); }
```
- In title, maybe scale *= .98.
- Camera clamp with half view. For attract, clamp too.
- On start, view snap to player; computeScale.

**Player movement/collision**:
```js
function updatePlayer(dt){
 let ix=..., iy=...
 if touchVec magnitude > .12 use.
 normalize if len>1.
 const sprint = keys.has('ShiftLeft')||...
 const speed = sprint?300:210;
 player.moving = len>0.1;
 if moving: player.facing=atan2(iy,ix); player.walkTime += dt*(sprint?1.3:1);
 moveWithCollision(player, ix*speed*dt, iy*speed*dt);
 if moving && Math.random()<dt*8 spawn dust at feet
}
```
- Collision:
```js
function collides(x,y,r){
 for c of world.colliders:
  if c.type rect: nearest point...
  if circle: dist<r+c.r
  if ellipse: ((x-c.x)/(c.rx+r))^2 + ... <1
 return true
}
function movePlayer(dx,dy){
 if(!collides(player.x+dx,player.y,player.r)) player.x+=dx; else maybe small slide? axis.
 if(!collides(player.x,player.y+dy,player.r)) player.y+=dy;
 clamp.
}
```
- Dynamic node colliders: when node dead, should not collide. Colliders have `node` reference. In collides skip if c.node && !c.node.alive. Good.
- Pedestals always.
- Player spawn not inside collider: (1210,1590) floor, pedestals y1494, safe. Lantern posts at 1062,1610 and 1388,1610 but no collision. Good.

**Find nearest interactable**:
Objects:
- plots: if dist to center < 72; prompt based state.
- nodes: dist < 82; only alive; prompt "Chop oak" / "Mine iron vein" etc.
- forge: dist to center (x+w/2,y+h/2) < 78.
- pedestals: dist < 62.
- ledger: dist < 72.
Choose smallest normalized distance? Use actual distance; but plot center vs node etc. Fine.
- Prompt HTML with em for action and details:
  - plot empty: `<em>Plant</em> turnip`; key E.
  - growing unwatered: `<em>Water</em> turnip`; watered: `<em>Turnip</em> growing · 62%` but pressing E no action? Could show `Check turnip` maybe. Better if watered, action could add nothing. We can still allow "Inspect" and show toast with growth percent? To avoid no-op confusion, prompt "Turnip · 62% — watered" and pressing E shows toast "Growing nicely. Ripe soon." maybe. Or allow E to harvest only ripe. Fine.
  - ripe: `<em>Harvest</em> turnip`.
  - node tree: `<em>Chop</em> oak · 2 hits` maybe. Use hp.
  - rock: `<em>Mine</em> iron vein · 2 hits`.
  - forge: `<em>Open</em> the forge`.
  - pedestal empty: `<em>Stock</em> display N`; occupied: `<em>Adjust</em> display N`.
  - ledger: `<em>Open</em> the ledger`.
- nearest target ring coords:
  - plot cx, cy+28, r=26.
  - node x,y+4, r=30/26.
  - forge center, y+34.
  - pedestal x,y+4.
  - ledger center.
- Also set `player.tool`:
  - plot -> 'hoe' (or 'water'? drawTool doesn't have water; use hoe)
  - tree -> 'axe'
  - rock -> 'pick'
  - forge -> 'hammer'
  - else null.
- Return {x,y,r,prompt,key,action,id}.

**Interact**:
- If phase not playing or modal return.
- nearest = currentNearest (computed each update) or compute fresh.
- switch action:
  - plot: 
    - empty -> plant: plot.empty=false; growth=0; stage=1; watered=false; particles; sfx plant; toast? maybe hint "Water it to grow faster." first time. 
    - growing: if !watered -> watered=true; sfx water; particles; toast? no.
      if watered -> toast "It's growing. Ripe in Xs." maybe use remaining = (1-growth)*grow/2. 
    - ripe -> harvest: amount = rand int crop.yield; state.resources[crop]+=amount; floating +n; quest harvest; reset plot empty; particles; sfx harvest; bump. Maybe toast every time? no. Show floating text only. If first harvest, toast.
  - node:
    - hit node: hp--; node.hit=...; node.shake=.35; particles; sfx chop/mine; screenShake? add `state.shake=4`; if hp<=0: alive=false; respawn=50/60/80; yield resources; quest (tree -> chop; rock -> mine); floating; sfx rockBreak; particles. Node revive update.
  - forge: openModal('craft').
  - pedestal: openModal('pedestal',{index}).
  - ledger: openModal('ledger').
- After action, ui.sync().

**Screen shake**: state.shake decays; renderer doesn't use. Could apply camera offset in view? Add `state.shake` and in updateCamera add random offset to view. Simpler view.x/y plus shake in render? Use in game:
```js
if(state.shake>0){ state.shake=Math.max(0,state.shake-dt*20); view.shakeX=(Math.random()-.5)*state.shake; ...}
```
Renderer doesn't use shake offsets; could add to view.x/y temporarily. Use `view.x += (Math.random()-.5)*state.shake` in draw call? Better compute camera target then add shake in frame. We'll do in updateCamera, but smoothing will fight. Add separate `view.sx/sy` not used. Skip shake or implement in renderer worldTransform using state.shake. Let's add in render worldTransform:
```js
const sx = state.shake? (Math.random()-.5)*state.shake : 0;
```
But random per frame fine. Renderer can read state.shake. We'll add. Need patch render later.

**Craft**:
```js
function craft(id){
 const w=WEAPONS[id]; 
 for costs if insufficient -> ui.toast('Not enough ...', warn); audio error; return false;
 subtract; state.weapons[id]=(||0)+1; quest craft; audio craft; particles at forge; toast(`${w.name} forged`, {icon:kind...}); sync; return true;
}
```
- Particles at forge position: sparks.
- `state.firstCraft` maybe toast hint "Carry it to a pedestal".
- Quest bump function handles toast; avoid duplicate toasts. If quest completes, show quest toast + reward.
- Need if craft modal open, world paused; particles still animate? updateParticles should run even in modal for visual. We'll update particles always in frame. Good.

**Place weapon**:
```js
function placeWeapon(index,id){
 const ped=state.pedestals[index]; if(!ped||!ped.unlocked||ped.weapon) return;
 if((state.weapons[id]||0)<1) return;
 state.weapons[id]--;
 ped.weapon=id; ped.qty=1; ped.mult=1; ped.price=Math.round(WEAPONS[id].base*valueBonus()*ped.mult);
 if(!state.firstDisplay){ state.firstDisplay=true; toast('Your first display is up. Word is spreading...',{icon:'shop'}); state.customerTimer=4; }
 bumpQuest('display');
 audio.play('ui');
 sync;
}
```
- If weapon qty becomes 0, delete or keep 0.
- `valueBonus = upgrades.bellows?1.2:1`.
- Note pedestal `price` recalculated on bellows purchase? If bellows bought, existing pedestal prices should increase? Could adjust price with bonus: after upgrade, for each ped with weapon set price = round(base*bonus*mult). We'll do in buyUpgrade.

**Adjust price**:
- ped.mult = clamp(mult+delta*0.05, .7,1.5); price = round(base*bonus*mult).
- audio ui.

**Add stock**:
- if have weapon and qty<3, move 1.
- If same weapon type only (ped.weapon). yes.
- bump? no.

**Clear**:
- return ped.qty to state.weapons[ped.weapon]; reset. toast maybe.

**Buy upgrade**:
- sign cost 140; if gold enough and !owned -> gold-=; upgrades.sign=true; toast; audio upgrade; quest? no.
- pedestal: if unlocked<4 and gold>=180 -> gold-=; unlock next; toast; audio upgrade.
- bellows: 240 -> upgrade; recompute prices; toast.
- sync.

**Quest bump**:
```js
function bumpQuest(id, n=1){
 const def=QUESTS.find; const q=state.quests[id];
 if(q.progress>=def.target) return;
 q.progress=Math.min(def.target,q.progress+n);
 if(q.progress>=def.target){ state.gold+=def.reward; state.earned+=def.reward; audio.play('quest'); ui.toast(`Quest complete — ${def.text}`, {kind:'gold',icon:'spark'}); ui.toast(`+${def.reward} gold`, ...)? Too many. Use one toast with +reward: `${def.text} · +${def.reward}g`; maybe.
 }
 ui.sync();
}
```
- Only one toast: `Quest complete: ${def.text} · +${def.reward}g`.
- Avoid gold added counting toward dayEarned? It's income; add to dayEarned too maybe. Add to gold and earned; dayEarned? It's not sale; day summary "earned today" could include quests. Add dayEarned. Fine.

**Customers**:
Spawn:
```js
function spawnCustomer(){
 if(state.customers.length>=4) return;
 const type=pick(CUSTOMER_TYPES);
 const side=Math.random()<.5?'left':'right';
 const budget=(65 + state.day*30 + rand(0,135)) * type.budget;
 const c={x:side==='left'?560:1880,y:986,...}
 c.path=[{x:1220,y:986},{x:1220,y:1578}];
 c.state='toShop'; c.bubble=null; c.bubbleTimer=0; ...
 state.customers.push(c);
}
```
- Use `type.names` pick.
- `seed=Math.random()*10`.
- `walkTime`, `moving`, `dir`, `speed=58+rand(0,16)`.
- `budget` maybe round.
- `bubble` show "Good morning!"? Set initial bubble maybe "Morning!" and timer 2.
- Need customer path logic. Let's implement generic:
```js
function moveCustomer(c,dt){
 if(c.state==='wait'){ c.wait-=dt; c.moving=false; return; }
 const target=c.path[c.pathIndex];
 if(!target){ ... }
 const d=dist(c.x,c.y,target.x,target.y);
 if(d<4){ c.pathIndex++; onReach...; return; }
 const speed=c.speed; c.x += (target.x-c.x)/d*speed*dt; ...
 c.dir=target.x-c.x; c.moving=true; c.walkTime+=dt;
}
```
- On reaching final shop waypoint (pathIndex exhausted), state='choose'. Then choose pedestal after brief pause.
Simpler state machine with timers:
  - state 'walk' with path array; when pathIndex>=len -> handle arrival callback based on `stage`.
  - stages: 'enter' -> at shop, choose pedestal; 'toPedestal' -> browse; 'toCounter' -> pay; 'leave'.
Let's write explicit:
```js
function updateCustomer(c,dt){
  c.bubbleTimer-=dt; if(c.bubbleTimer<=0) c.bubble=null;
  if(c.wait>0){ c.wait-=dt; c.moving=false; if(c.wait<=0) advanceCustomer(c); return; }
  if(c.path.length){
    const target=c.path[0];
    if(dist<5){ c.path.shift(); c.moving=false; if(!c.path.length) advanceCustomer(c); return; }
    move toward; c.moving=true; walkTime+=dt; c.dir=dx; return;
  }
  c.moving=false;
}
function advanceCustomer(c){
 switch(c.stage){
  case 'enter': choose pedestal; ...
  case 'browse': decide; ...
  case 'counter': completeSale; ...
  case 'leave': remove;
 }
}
```
- At spawn stage='enter', path to shop front.
- On reaching shop front:
  - `c.stage='choose'`; choose among unlocked pedestals with qty>0. Use affinity.
  - If none: set bubble "No wares? Hm."; wait 1.8; stage='leaving'; path back to road.
  - If found: c.targetPed=ped; path=[{x:ped.x, y:ped.y+52}]; stage='toBrowse'. At arrival: stage='browse'; wait=rand(1.8,3); bubble = one of type.lines or reaction to weapon.
- On browse wait end: evaluate:
  - `const ped=c.targetPed; if(!ped.weapon||ped.qty<=0)` -> maybe choose another; simplify leave disappointed.
  - effective budget = c.budget * (type.tags.includes(weapon.tag)?1.28:1); maybe + collector.
  - if ped.price <= effective budget: stage='toCounter'; path=[{x:SHOP.customerStand.x, y:SHOP.customerStand.y}]; bubble="I'll take it."; wait 0? At arrival stage='pay'; wait=1.0.
  - else: bubble pick ["A bit rich for me.", "Lovely... but no.", "I'll think on it."]; stage='leaving' after wait 1.6. Need wait then leave: set stage='leavingSoon'; wait=1.5; on wait end call leave.
- On pay: call completeSale(c), then stage='leaving'; bubble "Pleasure doing business."; path back.
- Leaving path: [{x:1220,y:1578},{x:1220,y:986},{x:c.exitX,y:986},{x:c.exitX+(side...),y:986}] then remove.
  - At shop front y 1578 then road. On reaching final, remove.
- Set `c.stage='gone'` and filter.
- If day ends, customers leave: set path to exit, stage='leaving'.
- `completeSale`: find ped by id? c.targetPed reference. qty--. If qty<=0 -> ped.weapon=null; ped.qty=0; ped.mult=1; ped.price=0. Else keep.
  - gold += price, earned, dayEarned, totalSales, daySales.
  - quest sell.
  - floaters at customer, coin particles.
  - ui.sale(weapon.name, price)
  - audio sale/coin
  - sync.
  - If pedestal sold out, maybe toast "Sold out of X — restock when you can."? Avoid spam; hint. Add ui.hint maybe.
- Customer bubbles should be set with timer (e.g., 4s).
- Customer name not displayed; bubble text enough.

Spawn logic:
```js
state.customerTimer -= dt;
if(state.customerTimer<=0 && state.firstDisplay && state.time < 18.5*60 && state.customers.length<4){
 spawn; state.customerTimer = max(5, 12 - state.day*.4 - (sign?2.5:0) + rand(-2,3));
}
```
If no stock, maybe spawn less. `hasStock = state.pedestals.some(p=>p.unlocked&&p.qty>0)`. If no stock, interval *=1.6. But customers disappointed is feedback. Keep.
- Initial customerTimer 8. After first display set 4.
- Also cap if day ends.

**Day end**:
```js
function endDay(){
 if(state.phase!=='playing' && state.phase!=='paused') return;
 state.phase='summary';
 ui.closeModal(true);
 state.customers.forEach(c=>startLeaving(c)); // but summary freezes; could clear
 state.customers.length=0;
 const final = state.day >= DAYS;
 const summary = {day, earned:state.dayEarned, sales:state.daySales, gold:state.gold, final, title, sub, tip}
 ui.showDay(summary);
 audio.play('day');
}
```
- Title/sub based on earned:
  - if sales===0: "A quiet day in the valley." sub "Not a single sale..." tip "Stock a pedestal..."
  - if earned>=200: "The till is singing." etc.
- tip based on state: no weapons -> "Forge..." ; pedestals empty -> "Stock..." ; gold<GOAL/DAYS*day -> "Try raising prices..." ; else "Lovely..."
- final summary button.
- `nextDay`:
  - if current day>=DAYS -> showEnd.
  - else day++, time=DAY_START, dayEarned=0, daySales=0, customerTimer=8; clear customers; overnight growth: plots not empty growth += .35 (if >=1 stage3); nodes respawn timer = max(0, respawn-25); reset; phase='playing'; ui.hideDay(); ui.setPhase('playing'); toast day; audio day; sync.
- If `state.endless` after win, day continues and final should be false. If nextDay from summary and day>=DAYS and endless -> increment day. For normal day7, nextDay -> showEnd.
- `endMain`: if result win -> endless mode: state.endless=true; hideEnd; state.day++; time=DAY_START; dayEarned=0; daySales=0; phase='playing'; ui.setPhase('playing'); toast "Endless season — the shop stays open."; sync. If lose -> restart().
- We need store result win? state.resultWin.
- `showEnd` computes:
```js
const win = state.gold>=GOAL;
const result={win, gold, earned, sales:state.totalSales, title, sub}
state.resultWin=win; ui.showEnd(result); audio.play(win?'start':'error');
```
- For win, total earned maybe. Title "The shop is saved." sub "The valley has a forge-shop..." etc.
- Lose title "The bank came calling." sub "You needed 1,200g..." etc.
- If endless, showEnd only when user manually ends day? In endless, day>=DAYS but no end; endDay summary final=false if endless. So nextDay increments.

- Day summary final logic: `const final = state.day >= DAYS && !state.endless;`.

**Particles**:
Functions:
```js
function particle(x,y,opts){ if(state.particles.length>240) shift; state.particles.push({...})}
function burst(x,y,count,opts)
function floater(x,y,text,color)
```
Update:
- gravity, drag, life.
- leaf ambient spawn every ~1.5s around camera? Could spawn near player. Add occasional leaf drifting in world. `state.ambientTimer`.
- We'll spawn leaf particles randomly near player in updateAmbient.

**Floaters**:
- life 1.4, vy -30, update.

**Camera**:
- In playing:
```js
